/**
 * createCrudSlice — generic CRUD slice factory.
 *
 * Takes an entity name + API base path and returns a fully-wired Redux slice
 * with fetchList, fetchDetail, add, update, remove thunks and standard
 * loading / error / items / selected state.
 *
 * Usage:
 *   const { slice, actions, thunks } = createCrudSlice('country', '/flights/v2/countries');
 *   export const { fetchList: fetchCountries, add: addCountry } = thunks;
 *   export default slice.reducer;
 */
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import { fetchWithAuth } from '@/services/apiClient';
import { parseApiError } from '@/utils/errorUtils';

export function createCrudSlice(entityName, apiBasePath) {
  const upper = entityName.charAt(0).toUpperCase() + entityName.slice(1);

  // ─── Thunks ──────────────────────────────────────────────────────────────

  const fetchList = createAsyncThunk(
    `${entityName}/fetchList`,
    async (params = {}, { rejectWithValue }) => {
      try {
        const query = new URLSearchParams(params).toString();
        const url = query ? `${apiBasePath}/?${query}` : `${apiBasePath}/`;
        return await fetchWithAuth(url);
      } catch (err) {
        return rejectWithValue(_parseError(err, `Failed to fetch ${entityName} list`));
      }
    }
  );

  const fetchDetail = createAsyncThunk(
    `${entityName}/fetchDetail`,
    async (id, { rejectWithValue }) => {
      try {
        return await fetchWithAuth(`${apiBasePath}/${id}/`);
      } catch (err) {
        return rejectWithValue(_parseError(err, `Failed to fetch ${entityName} detail`));
      }
    }
  );

  const add = createAsyncThunk(
    `${entityName}/add`,
    async (data, { rejectWithValue }) => {
      try {
        const isFormData = data instanceof FormData;
        return await fetchWithAuth(`${apiBasePath}/`, {
          method: 'POST',
          body: isFormData ? data : JSON.stringify(data),
          headers: isFormData ? {} : { 'Content-Type': 'application/json' },
        });
      } catch (err) {
        if (err.data && typeof err.data === 'object') {
          return rejectWithValue(err.data);
        }
        return rejectWithValue({ non_field_errors: [err.message || `Failed to create ${entityName}`] });
      }
    }
  );

  const update = createAsyncThunk(
    `${entityName}/update`,
    async ({ id, data }, { rejectWithValue }) => {
      try {
        const isFormData = data instanceof FormData;
        return await fetchWithAuth(`${apiBasePath}/${id}/`, {
          method: 'PATCH',
          body: isFormData ? data : JSON.stringify(data),
          headers: isFormData ? {} : { 'Content-Type': 'application/json' },
        });
      } catch (err) {
        if (err.data && typeof err.data === 'object') {
          return rejectWithValue(err.data);
        }
        return rejectWithValue({ non_field_errors: [err.message || `Failed to update ${entityName}`] });
      }
    }
  );

  const remove = createAsyncThunk(
    `${entityName}/remove`,
    async (id, { rejectWithValue }) => {
      try {
        await fetchWithAuth(`${apiBasePath}/${id}/`, { method: 'DELETE' });
        return id;
      } catch (err) {
        return rejectWithValue(_parseError(err, `Failed to delete ${entityName}`));
      }
    }
  );

  // ─── Custom action factory (for non-CRUD calls e.g. generate-seats) ──────
  const createCustomAction = (actionName, method, buildUrl, buildBody) =>
    createAsyncThunk(
      `${entityName}/${actionName}`,
      async (arg, { rejectWithValue }) => {
        try {
          const url = buildUrl(arg);
          const opts = method !== 'GET' ? { method, body: buildBody ? JSON.stringify(buildBody(arg)) : undefined } : {};
          return await fetchWithAuth(url, opts);
        } catch (err) {
          return rejectWithValue(_parseError(err, `Failed: ${actionName}`));
        }
      }
    );

  // ─── Slice ────────────────────────────────────────────────────────────────

  const initialState = {
    items: [],
    count: 0,
    next: null,
    previous: null,
    selected: null,
    loading: false,
    detailLoading: false,
    actionLoading: false,
    error: null,
    validationErrors: null,
  };

  const slice = createSlice({
    name: entityName,
    initialState,
    reducers: {
      clearErrors: (state) => {
        state.error = null;
        state.validationErrors = null;
      },
      clearSelected: (state) => {
        state.selected = null;
      },
      clearList: (state) => {
        state.items = [];
        state.count = 0;
      },
    },
    extraReducers: (builder) => {
      // fetchList
      _pending(builder, fetchList, 'loading');
      builder.addCase(fetchList.fulfilled, (state, action) => {
        state.loading = false;
        // Support both paginated { count, results } and plain arrays
        if (Array.isArray(action.payload)) {
          state.items = action.payload;
          state.count = action.payload.length;
        } else {
          state.items = action.payload.results ?? action.payload;
          state.count = action.payload.count ?? (state.items.length);
          state.next = action.payload.next ?? null;
          state.previous = action.payload.previous ?? null;
        }
      });
      _rejected(builder, fetchList, 'loading');

      // fetchDetail
      _pending(builder, fetchDetail, 'detailLoading');
      builder.addCase(fetchDetail.fulfilled, (state, action) => {
        state.detailLoading = false;
        state.selected = action.payload;
      });
      _rejected(builder, fetchDetail, 'detailLoading');

      // add
      _pending(builder, add, 'actionLoading');
      builder.addCase(add.fulfilled, (state, action) => {
        state.actionLoading = false;
        state.items = [action.payload, ...state.items];
        state.count += 1;
      });
      builder.addCase(add.rejected, (state, action) => {
        state.actionLoading = false;
        state.validationErrors = action.payload;
      });

      // update
      _pending(builder, update, 'actionLoading');
      builder.addCase(update.fulfilled, (state, action) => {
        state.actionLoading = false;
        state.selected = action.payload;
        const idx = state.items.findIndex((i) => String(i.id) === String(action.payload.id));
        if (idx !== -1) state.items[idx] = action.payload;
      });
      builder.addCase(update.rejected, (state, action) => {
        state.actionLoading = false;
        state.validationErrors = action.payload;
      });

      // remove
      _pending(builder, remove, 'actionLoading');
      builder.addCase(remove.fulfilled, (state, action) => {
        state.actionLoading = false;
        state.items = state.items.filter((i) => String(i.id) !== String(action.payload));
        state.count = Math.max(0, state.count - 1);
      });
      _rejected(builder, remove, 'actionLoading');
    },
  });

  return {
    slice,
    thunks: { fetchList, fetchDetail, add, update, remove, createCustomAction },
    actions: slice.actions,
  };
}

// _parseError uses the centralized parseApiError utility.
function _parseError(err, fallback) {
  return parseApiError(err, fallback);
}

function _pending(builder, thunk, loadingKey) {
  builder.addCase(thunk.pending, (state) => {
    state[loadingKey] = true;
    state.error = null;
  });
}

function _rejected(builder, thunk, loadingKey) {
  builder.addCase(thunk.rejected, (state, action) => {
    state[loadingKey] = false;
    state.error = action.payload;
  });
}

import React from 'react';
import { useTranslation } from 'react-i18next';
import { TrendingUp, Ticket, CheckCircle, XCircle, Percent, AlertCircle } from 'lucide-react';

import AnalyticsFilterBar from './components/AnalyticsFilterBar';
import KpiCard from './components/KpiCard';
import MonthlyRevenueChart from './components/MonthlyRevenueChart';
import PopularRoutesChart from './components/PopularRoutesChart';
import PeakHoursChart from './components/PeakHoursChart';
import FlightOccupancyChart from './components/FlightOccupancyChart';
import AirlinePerformanceChart from './components/AirlinePerformanceChart';
import AircraftUtilizationChart from './components/AircraftUtilizationChart';
import useAnalyticsData from './hooks/useAnalyticsData';
import { INR } from '@/utils/formatters';
import { GOLD_DARK, BLUE, GREEN, RED, AMBER } from './constants';

export default function AnalyticsDashboard() {
  const { t } = useTranslation();
  const {
    summary, monthly, routes, occupancy, peakHours,
    airlinePerf, aircraftUtil, loading, error, filters,
    load, handleFilterChange,
  } = useAnalyticsData();

  return (
    <div className="min-h-screen font-ui pt-[88px] pb-[60px] bg-[linear-gradient(135deg,#f7f4ee_0%,#edeade_50%,#f0ede4_100%)]">
      <div className="w-[95%] max-w-[1800px] mx-auto px-6">

        {/* ── Header ── */}
        <div className="flex items-start justify-between gap-4 mb-8 flex-wrap">
          <div>
            <h1 className="font-ui text-2xl font-extrabold text-admin-ink tracking-[-0.02em] m-0 leading-tight">{t('admin.analytics.title')}</h1>
            <p className="text-sm text-admin-muted mt-1 mb-0">{t('admin.analytics.subtitle')}</p>
          </div>
        </div>

        {/* ── Error Banner ── */}
        {error && (
          <div className="flex items-center gap-3 bg-status-red-bg border border-status-red-bg text-status-red p-4 rounded-admin-lg mb-6 font-ui text-sm">
            <AlertCircle size={18} />
            <span>{error}</span>
            <button className="font-bold underline cursor-pointer bg-transparent border-none p-0 ml-auto transition-opacity hover:opacity-70 text-status-red" onClick={() => load(false, filters)}>{t('admin.analytics.retry')}</button>
          </div>
        )}

        {/* ── Filter Bar ── */}
        <AnalyticsFilterBar onFilterChange={handleFilterChange} disabled={loading} />

        {/* ── KPI Grid ── */}
        <div className="grid mb-6 grid-cols-2 gap-[10px] sm:grid-cols-3 sm:gap-4 lg:grid-cols-5 lg:gap-3 xl:gap-4">
          <KpiCard icon={<TrendingUp size={20} color={GOLD_DARK} />} label={t('admin.analytics.kpi.totalRevenue')} value={summary ? INR(summary.total_revenue) : '—'} sub={t('admin.analytics.kpi.revenueSub')} accent={GOLD_DARK} loading={loading}
            tooltip={summary ? `Exact: ${new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', minimumFractionDigits: 2 }).format(summary.total_revenue)}` : undefined} />
          <KpiCard icon={<Ticket size={20} color={BLUE} />} label={t('admin.analytics.kpi.totalBookings')} value={summary ? summary.total_bookings.toLocaleString() : '—'} sub={t('admin.analytics.kpi.bookingsSub')} accent={BLUE} loading={loading} />
          <KpiCard icon={<CheckCircle size={20} color={GREEN} />} label={t('admin.analytics.kpi.confirmed')} value={summary ? summary.confirmed_bookings.toLocaleString() : '—'} sub={t('admin.analytics.kpi.confirmedSub')} accent={GREEN} loading={loading} />
          <KpiCard icon={<XCircle size={20} color={RED} />} label={t('admin.analytics.kpi.cancelled')} value={summary ? summary.cancelled_bookings.toLocaleString() : '—'} sub={t('admin.analytics.kpi.cancelledSub')} accent={RED} loading={loading} />
          <KpiCard icon={<Percent size={20} color={AMBER} />} label={t('admin.analytics.kpi.cancellationRate')} value={summary ? `${summary.cancellation_rate}%` : '—'} sub={t('admin.analytics.kpi.rateSub')} accent={AMBER} loading={loading} />
        </div>

        {/* ── Row 1: Monthly Revenue + Popular Routes ── */}
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-5 mb-5">
          <MonthlyRevenueChart data={monthly} loading={loading} title={t('admin.analytics.charts.monthlyRevenue')} />
          <PopularRoutesChart data={routes} loading={loading} title={t('admin.analytics.charts.popularRoutes')} />
        </div>

        {/* ── Row 2: Peak Hours + Flight Occupancy ── */}
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-5 mb-5">
          <PeakHoursChart data={peakHours} loading={loading} title={t('admin.analytics.charts.peakHours')} />
          <FlightOccupancyChart data={occupancy} loading={loading} title={t('admin.analytics.charts.flightOccupancy')} />
        </div>

        {/* ── Row 3: Airline Performance + Aircraft Utilization ── */}
        {!(filters.airlineId || filters.aircraftId) && (
          <div className="grid grid-cols-1 xl:grid-cols-2 gap-5 mb-5">
            <AirlinePerformanceChart data={airlinePerf} loading={loading} title="Airline Performance" />
            <AircraftUtilizationChart data={aircraftUtil} loading={loading} title="Aircraft Utilization" />
          </div>
        )}

      </div>
    </div>
  );
}

import React from 'react';
import { BarChart, Bar, Cell, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Gauge } from 'lucide-react';
import ChartCard from './ChartCard';
import EmptyState from './EmptyState';
import { GOLD, GOLD_DARK, GREEN, BLUE, DARK, MUTED } from '../constants';

export default function AircraftUtilizationChart({ data, loading, title }) {
  return (
    <ChartCard title={title} loading={loading} action={
      <span className="flex items-center gap-1.5 text-xs font-semibold text-status-purple">
        <Gauge size={13} /> Top 10
      </span>
    }>
      {data.length === 0 ? <EmptyState /> : (
        <>
          <ResponsiveContainer width="100%" height={240}>
            <BarChart data={data} layout="vertical" margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(0,0,0,0.06)" horizontal={false} />
              <XAxis type="number" domain={[0, 100]} tick={{ fontSize: 11, fill: MUTED }} tickLine={false} axisLine={false} tickFormatter={v => `${v}%`} />
              <YAxis type="category" dataKey="registration" tick={{ fontSize: 11, fill: DARK, fontWeight: 600 }} width={80} tickLine={false} axisLine={false} />
              <Tooltip content={({ active, payload, label }) => {
                if (!active || !payload?.length) return null;
                const d = payload[0]?.payload;
                return (
                  <div className="bg-white/95 backdrop-blur-xl border border-admin-border rounded-xl px-3.5 py-2.5 shadow-admin-lg min-w-[200px]">
                    <div className="text-[13px] font-bold text-admin-ink mb-1">{label} · {d?.aircraft_model}</div>
                    <div className="text-xs text-admin-muted">Flights: <b className="text-admin-ink">{d?.total_flights}</b></div>
                    <div className="text-xs text-admin-muted">Avg occupancy: <b className="text-admin-accent-dark">{d?.avg_occupancy}%</b></div>
                    <div className="mt-1.5 text-xs">
                      <div className="flex justify-between text-admin-muted"><span>Economy</span><b className="text-admin-ink">{d?.economy_fill_rate}%</b></div>
                      <div className="flex justify-between text-admin-muted"><span>Business</span><b className="text-admin-ink">{d?.business_fill_rate}%</b></div>
                      <div className="flex justify-between text-admin-muted"><span>First</span><b className="text-admin-ink">{d?.first_fill_rate}%</b></div>
                    </div>
                  </div>
                );
              }} />
              <Bar dataKey="avg_occupancy" radius={[0, 6, 6, 0]} maxBarSize={20}>
                {data.map((ac, i) => {
                  const c = ac.avg_occupancy >= 80 ? GOLD_DARK : ac.avg_occupancy >= 60 ? '#9b7d00' : ac.avg_occupancy >= 40 ? '#c9a800' : GOLD;
                  return <Cell key={i} fill={c} />;
                })}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
          <div className="mt-4 space-y-1.5">
            {data.slice(0, 5).map(ac => (
              <div key={ac.aircraft_id} className="flex items-center gap-3 text-xs px-2 py-1.5 rounded-lg bg-admin-accent-dark/5">
                <span className="font-semibold w-20 flex-shrink-0 text-admin-ink">{ac.registration}</span>
                <div className="flex-1 flex gap-2">
                  {[['E', ac.economy_fill_rate, GREEN], ['B', ac.business_fill_rate, BLUE], ['F', ac.first_fill_rate, GOLD_DARK]].map(([cls, rate, color]) => (
                    <div key={cls} className="flex items-center gap-1">
                      <span className="text-admin-muted">{cls}:</span>
                      <span className="font-semibold" style={{ color }}>{rate}%</span>
                    </div>
                  ))}
                </div>
                <span className="text-admin-muted">{ac.total_flights} flt</span>
              </div>
            ))}
          </div>
        </>
      )}
    </ChartCard>
  );
}

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Building2 } from 'lucide-react';
import ChartCard from './ChartCard';
import EmptyState from './EmptyState';
