export default function FlightInstancesPage() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const routeParam = searchParams.get('route');
  const autoCreate = searchParams.get('autoCreate');
  const highlightInstance = searchParams.get('highlightInstance');

  const { items: instances, loading, actionLoading, count, error, validationErrors } = useSelector((s) => s.flightInstance);
  const { items: routes } = useSelector((s) => s.flightRoute);
  const { items: allAircraft } = useSelector((s) => s.aircraft);
  const { items: airports } = useSelector((s) => s.airport);

  const [showForm, setShowForm] = useState(false);
  const [editId, setEditId] = useState(null);
  const [form, setForm] = useState(EMPTY_FORM);
  const [localErrors, setLocalErrors] = useState({});
  const [search, setSearch] = useState('');
  const [activeSearch, setActiveSearch] = useState('');

  const pageParam = parseInt(searchParams.get('page') || '1', 10);
  const initialPage = isNaN(pageParam) ? 1 : pageParam;
  const [page, setPage] = useState(initialPage);
  const PAGE_SIZE = 10;

  const load = useCallback((s, p) => {
    dispatch(fetchFlightInstances({ search: s, page: p, page_size: PAGE_SIZE }));
  }, [dispatch]);

  const pageStr = searchParams.get('page') || '1';

  useEffect(() => {
    const p = parseInt(pageStr, 10);
    const resolvedPage = isNaN(p) ? 1 : p;
    setPage(resolvedPage);
    load(activeSearch, resolvedPage);
  }, [pageStr, activeSearch, load]);

  useEffect(() => {
    dispatch(fetchFlightRoutes({ page_size: 500 }));
    dispatch(fetchAircraft({ page_size: 500 }));
    dispatch(fetchAirports({ page_size: 500 }));
  }, [dispatch]);

  useEffect(() => {
    if (routeParam && autoCreate && routes.length > 0) {
      setEditId(null);
      setForm({ ...EMPTY_FORM, flight: routeParam });
      setLocalErrors({});
      setShowForm(true);
    }
  }, [routeParam, autoCreate, routes]);

  useEffect(() => {
    const handleOutsideClick = (e) => {
      const tableContainer = document.querySelector('.admin-table-wrap');
      if (tableContainer && !tableContainer.contains(e.target)) {
        const isInteractiveModal = e.target.closest('.admin-modal') || e.target.closest('.toast') || e.target.closest('.admin-sidebar') || e.target.closest('.admin-navbar');
        if (isInteractiveModal) return;

        setSearchParams((prev) => {
          if (!prev.has('highlightInstance')) return prev;
          const nextParams = new URLSearchParams(prev);
          nextParams.delete('highlightInstance');
          return nextParams;
        });
      }
    };
    document.addEventListener('click', handleOutsideClick);
    return () => {
      document.removeEventListener('click', handleOutsideClick);
    };
  }, [setSearchParams]);

  const handleRowClick = (e, instId) => {
    const tag = e.target.tagName.toLowerCase();
    if (
      tag === 'button' ||
      tag === 'a' ||
      tag === 'input' ||
      tag === 'svg' ||
      tag === 'path' ||
      e.target.closest('a') ||
      e.target.closest('button') ||
      e.target.closest('input')
    ) {
      return;
    }
    setSearchParams((prev) => {
      const nextParams = new URLSearchParams(prev);
      const currentHighlight = nextParams.get('highlightInstance');
      if (currentHighlight === String(instId)) {
        nextParams.delete('highlightInstance');
      } else {
        nextParams.set('highlightInstance', String(instId));
      }
      return nextParams;
    });
  };

  const calculateArrival = (routeObj, depStr) => {
    if (!routeObj || !depStr || !routeObj.legs || routeObj.legs.length === 0) return '';
    const depDate = new Date(depStr);
    if (isNaN(depDate.getTime())) return '';
    const totalMins = routeObj.legs.reduce((acc, leg) => {
      return acc + Number(leg.flight_duration_minutes || 0) + Number(leg.layover_duration_minutes || 0);
    }, 0);
    if (totalMins <= 0) return '';
    const arrDate = new Date(depDate.getTime() + totalMins * 60000);
    const yyyy = arrDate.getFullYear();
    const mm = String(arrDate.getMonth() + 1).padStart(2, '0');
    const dd = String(arrDate.getDate()).padStart(2, '0');
    const hh = String(arrDate.getHours()).padStart(2, '0');
    const mns = String(arrDate.getMinutes()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd} ${hh}:${mns}`;
  };

  // Auto-suggest times when flight selected
  const handleFlightChange = async (flightId) => {
    setForm((f) => {
      const nextForm = { ...f, flight: flightId, aircraft: '' };
      const routeObj = routes.find((r) => String(r.id) === String(flightId));
      if (routeObj && nextForm.scheduled_departure) {
        const computedArr = calculateArrival(routeObj, nextForm.scheduled_departure);
        if (computedArr) nextForm.scheduled_arrival = computedArr;
      }
      return nextForm;
    });
  };

  // Filter aircraft by airline matching selected route's airline
  const selectedRoute = routes.find((r) => String(r.id) === String(form.flight));
  const filteredAircraft = selectedRoute
    ? allAircraft.filter((ac) => String(ac.airline) === String(selectedRoute.airline))
    : allAircraft;

  const routeOptions = routes.map((r) => ({ value: r.id, label: `${r.flight_no} (${r.airline_name || r.airline})` }));
  const aircraftOptions = filteredAircraft.map((a) => ({ value: a.id, label: `${a.registration} – ${a.model_display || ''}` }));

  // Find terminals from departure/arrival airports
  const firstLeg = selectedRoute?.legs?.[0];
  const lastLeg = selectedRoute?.legs?.[(selectedRoute?.legs?.length || 1) - 1];
  const depAirport = airports.find(a => String(a.id) === String(firstLeg?.departure_airport));
  const arrAirport = airports.find(a => String(a.id) === String(lastLeg?.arrival_airport));

  const depTerminalOptions = (depAirport?.terminals || []).map(t => ({ value: t, label: t }));
  const arrTerminalOptions = (arrAirport?.terminals || []).map(t => ({ value: t, label: t }));

  // Gate suggestions from existing instances on the same route, or generic gate list
  const usedGates = [...new Set(
    instances.filter((i) => i.boarding_gate && String(i.flight) === String(form.flight)).map((i) => i.boarding_gate)
  )].map((g) => ({ value: g, label: g }));
  const GENERIC_GATES = ['A1','A2','A3','A4','B1','B2','B3','B4','C1','C2','D1','D2',
    'G1','G2','G3','G4','G5','G6','G10','G11','G12','G13','G14'].map((g) => ({ value: g, label: g }));
  const gateOptions = usedGates.length > 0 ? usedGates : GENERIC_GATES;

  const openCreate = () => { setEditId(null); setForm(EMPTY_FORM); setLocalErrors({}); setShowForm(true); };
  const openEdit = (inst) => {
    setEditId(inst.id);
    setForm({
      flight: inst.flight, date: inst.date, aircraft: inst.aircraft, status: inst.status,
      scheduled_departure: inst.scheduled_departure || '',
      scheduled_arrival: inst.scheduled_arrival || '',
      boarding_gate: inst.boarding_gate || '',
      departure_terminal: inst.departure_terminal || '',
      arrival_terminal: inst.arrival_terminal || '',
      checkin_open: inst.checkin_open || '',
      boarding_time: inst.boarding_time || '',
    });
    setLocalErrors({});
    setShowForm(true);
  };
  const closeForm = () => { setShowForm(false); setEditId(null); };

  // Clear a single field error as soon as the user provides a value
  const clearError = (field) => setLocalErrors(prev => { const e = { ...prev }; delete e[field]; return e; });

  const validateForm = () => {
    const e = {};
    if (!form.flight) e.flight = 'Flight route is required.';
    if (!form.date) {
      e.date = 'Date is required.';
    }
    if (!form.aircraft) e.aircraft = 'Aircraft is required.';
    if (!form.scheduled_departure) e.scheduled_departure = 'Scheduled departure is required.';
    if (!form.scheduled_arrival) e.scheduled_arrival = 'Scheduled arrival is required.';
    if (form.scheduled_departure && form.scheduled_arrival) {
      if (new Date(form.scheduled_arrival) <= new Date(form.scheduled_departure)) {
        e.scheduled_arrival = 'Arrival must be after departure.';
      }
    }
    if (!form.boarding_gate || !form.boarding_gate.trim()) e.boarding_gate = 'Boarding gate is required.';
    if (!form.departure_terminal || !form.departure_terminal.trim()) e.departure_terminal = 'Departure terminal is required.';
    if (!form.arrival_terminal || !form.arrival_terminal.trim()) e.arrival_terminal = 'Arrival terminal is required.';
    setLocalErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleSubmit = async (e, followUpTarget = null, inFlow = false) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!validateForm()) return; // inline errors already shown via localErrors

    // Optional datetime fields must be null (not empty string "") for the backend
    const OPTIONAL_DATETIMES = ['checkin_open', 'boarding_time', 'actual_departure', 'actual_arrival'];
    const payload = { ...form };
    OPTIONAL_DATETIMES.forEach(field => {
      if (!payload[field]) payload[field] = null;
    });

    const action = editId
      ? updateFlightInstance({ id: editId, data: payload })
      : addFlightInstance(payload);

    try {
      const res = await dispatch(action).unwrap();
      toast.success('Flight instance saved!');
      closeForm();
      const targetId = res?.id || editId;
      if (followUpTarget && targetId) {
        navigate(`/admin/operations/${followUpTarget}?instance=${targetId}${inFlow ? '&inFlow=1' : ''}`);
      } else {
        load(activeSearch, page);
      }
    } catch (err) {
      if (err && typeof err === 'object') {
        const errors = {};
        for (const [k, v] of Object.entries(err)) {
          errors[k] = Array.isArray(v) ? v[0] : v;
        }
        setLocalErrors(prev => ({ ...prev, ...errors }));
      }
      toast.error(parseApiError(err, 'Failed to save.'));
    }
  };

  const { deleteItem, setDeleteItem, deleteLoading, confirmDelete } = useDeleteAction({
    thunk: removeFlightInstance,
    onSuccess: () => load(activeSearch, page),
    successMessage: 'Flight instance deleted successfully.',
    errorMessage: 'Failed to delete flight instance.'
  });

  const totalPages = count ? Math.ceil(count / PAGE_SIZE) : 1;

  return (
    <div className="admin-page">
      <div className="admin-container">

        <div className="flex justify-between items-center mb-7">
          <div>
            <h1 className="admin-page-title">Flight Instances</h1>
            <p className="admin-page-subtitle">{count} total instances</p>
          </div>
          <button className="btn-primary" onClick={openCreate} id="add-fi-btn"><Plus size={15} /> Add Instance</button>
        </div>

        <form onSubmit={(e) => {
          e.preventDefault();
          setActiveSearch(search);
          const p = parseInt(searchParams.get('page') || '1', 10);
          if (p !== 1) {
            setSearchParams((prev) => {
              const nextParams = new URLSearchParams(prev);
              nextParams.set('page', '1');
              return nextParams;
            });
          }
        }} className="flex gap-2 mb-5">
          <div className="admin-toolbar-search">
            <Search size={14} className="search-icon" />
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search by flight number…"
            />
            {search && (
              <button
                type="button"
                className="clear-search-btn"
                onClick={() => {
                  setSearch('');
                  setActiveSearch('');
                  const p = parseInt(searchParams.get('page') || '1', 10);
                  if (p !== 1) {
                    setSearchParams((prev) => {
                      const nextParams = new URLSearchParams(prev);
                      nextParams.set('page', '1');
                      return nextParams;
                    });
                  }
                }}
                title="Clear search"
              >
                <X size={13} />
              </button>
            )}
          </div>
          <button type="submit" className="btn-primary" style={{ padding: '7px 14px', fontSize: 13 }}>Search</button>
        </form>

        {error && (
          <div className="admin-error">
            <AlertCircle size={15} /><span>{String(error)}</span>
          </div>
        )}

        <div className="admin-card admin-table-wrap">
          {loading ? (
            <SpinnerLoader />
          ) : instances?.length === 0 ? (
            <div className="admin-empty"><p>No instances. Create one above.</p></div>
          ) : (
            <div style={{ overflowX: 'auto' }}>
              <table className="admin-table">
                <thead>
                  <tr><th>Flight No</th><th>Date</th><th>Aircraft</th><th>Status</th><th>Departure</th><th>Arrival</th><th className="text-right">Actions</th></tr>
                </thead>
                <tbody>
                  {instances.map((inst) => {
                    const isHighlighted = String(inst.id) === String(highlightInstance);
                    return (
                      <tr key={inst.id} onClick={(e) => handleRowClick(e, inst.id)} className={`admin-row ${isHighlighted ? 'admin-row-highlight' : ''}`}>
                        <td><strong>{inst.flight_no}</strong></td>
                        <td>{inst.date}</td>
                        <td>{inst.aircraft_registration}</td>
                        <td>
                          <span style={{ fontSize: 11, fontWeight: 700, padding: '3px 8px', borderRadius: 20, background: STATUS_COLORS[inst.status] + '20', color: STATUS_COLORS[inst.status] }}>
                            {inst.status}
                          </span>
                        </td>
                        <td>{inst.scheduled_departure ? new Date(inst.scheduled_departure).toLocaleString() : '—'}</td>
                        <td>{inst.scheduled_arrival ? new Date(inst.scheduled_arrival).toLocaleString() : '—'}</td>
                        <td className="text-right whitespace-nowrap">
                          <div style={{ display: 'inline-flex', gap: 6, alignItems: 'center', justifyContent: 'flex-end' }}>
                            <div style={{ display: 'flex', background: 'rgba(0,0,0,0.03)', borderRadius: 8, padding: 2 }}>
                              <Link to={`/admin/operations/fares?instance=${inst.id}&fromPage=${page}&inFlow=1`} style={{ padding: '6px 10px', color: '#1a1c1d', borderRadius: 6, display: 'flex', alignItems: 'center', gap: 4, textDecoration: 'none', fontSize: 12, fontWeight: 600, transition: 'background 0.2s' }} onMouseEnter={e => e.currentTarget.style.background='rgba(0,0,0,0.05)'} onMouseLeave={e => e.currentTarget.style.background='transparent'} title="Manage Fares">
                                <Banknote size={13} /> Fares
                              </Link>
                              <Link to={`/admin/operations/seat-map?instance=${inst.id}&fromPage=${page}&inFlow=1`} style={{ padding: '6px 10px', color: '#1a1c1d', borderRadius: 6, display: 'flex', alignItems: 'center', gap: 4, textDecoration: 'none', fontSize: 12, fontWeight: 600, transition: 'background 0.2s' }} onMouseEnter={e => e.currentTarget.style.background='rgba(0,0,0,0.05)'} onMouseLeave={e => e.currentTarget.style.background='transparent'} title="Manage Seats">
                                <Armchair size={13} /> Seats
                              </Link>
                              <Link to={`/admin/operations/meals?instance=${inst.id}&fromPage=${page}&inFlow=1`} style={{ padding: '6px 10px', color: '#1a1c1d', borderRadius: 6, display: 'flex', alignItems: 'center', gap: 4, textDecoration: 'none', fontSize: 12, fontWeight: 600, transition: 'background 0.2s' }} onMouseEnter={e => e.currentTarget.style.background='rgba(0,0,0,0.05)'} onMouseLeave={e => e.currentTarget.style.background='transparent'} title="Manage Meals">
                                <Utensils size={13} /> Meals
                              </Link>
                            </div>

                            <div style={{ display: 'flex', gap: 4, marginLeft: 4 }}>
                              <button className="btn-secondary" title="Edit" onClick={() => openEdit(inst)} style={{ padding: '6px 8px' }}>
                                <Pencil size={14} />
                              </button>
                              <button className="btn-danger" title="Delete" onClick={() => setDeleteItem(inst)} style={{ padding: '6px 8px' }}>
                                <Trash2 size={14} />
                              </button>
                            </div>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <Pagination
          currentPage={page}
          totalPages={totalPages}
          totalCount={count || instances?.length || 0}
          pageSize={PAGE_SIZE}
          onPageChange={(p) => {
            setSearchParams((prev) => {
              const nextParams = new URLSearchParams(prev);
              nextParams.set('page', String(p));
              return nextParams;
            });
          }}
          entityLabel="instances"
        />
      </div>

      {showForm && (
        <div className="admin-modal-overlay" onClick={closeForm}>
          <div className="admin-modal" onClick={(e) => e.stopPropagation()}>
            <div className="admin-modal-header">
              <h2 className="admin-modal-title">
                {editId ? 'Edit Instance' : 'Add Instance'}
              </h2>
              <button className="btn-icon" onClick={closeForm}><X size={16} /></button>
            </div>

            {routeParam && (
              <div className="bg-gradient-to-r from-amber-500/10 via-amber-500/5 to-transparent border border-amber-500/30 rounded-2xl p-4 mb-5 flex flex-wrap items-center justify-between gap-4 shadow-sm">
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-xl bg-[#705d00] text-white flex items-center justify-center font-black text-xs shadow">
                    1/4
                  </div>
                  <div>
                    <div className="text-xs font-extrabold uppercase tracking-wider text-[#705d00]">
                      Instance Setup Flow • Step 1 (Flight Instance)
                    </div>
                    <div className="text-sm font-bold text-slate-800">
                      Creating Flight Instance for Route #{routeParam}
                    </div>
                  </div>
                </div>

                <div className="flex items-center gap-2 flex-wrap">
                  <button
                    type="button"
                    onClick={() => navigate(`/admin/operations/fares?route=${routeParam}&inFlow=1`)}
                    className="px-3.5 py-2 rounded-xl bg-[#705d00] hover:bg-[#5a4b00] text-white font-bold text-xs flex items-center gap-1.5 shadow-md cursor-pointer transition-all border-none"
                  >
                    Skip / Next: Fares <ChevronRight size={14} />
                  </button>
                  <button
                    type="button"
                    onClick={() => navigate('/admin/operations/flight-routes')}
                    className="px-3 py-2 rounded-xl bg-white hover:bg-slate-100 text-slate-600 font-semibold text-xs transition-all border border-slate-200 cursor-pointer"
                  >
                    Finish Flow
                  </button>
                </div>
              </div>
            )}

            {validationErrors?.non_field_errors && (
              <div className="admin-error">
                <AlertCircle size={15} /><span>{validationErrors.non_field_errors.join(', ')}</span>
              </div>
            )}

            <form onSubmit={handleSubmit}>
              <div className="admin-form-grid" style={{ marginBottom: 20 }}>
                <Select id="fi_flight" label="Flight Route" options={routeOptions} value={form.flight}
                  onChange={(e) => { handleFlightChange(e.target.value); clearError('flight'); }} error={localErrors.flight} />
                <Select id="fi_aircraft" label="Aircraft (filtered by airline)" options={aircraftOptions}
                  value={form.aircraft} onChange={(e) => { setForm((f) => ({ ...f, aircraft: e.target.value })); clearError('aircraft'); }}
                  error={localErrors.aircraft} />
                <Select id="fi_status" label="Status" options={STATUS_OPTIONS} value={form.status}
                  onChange={(e) => setForm((f) => ({ ...f, status: e.target.value }))} />
              </div>

              <div className="admin-form-grid mb-5">
                <div>
                  <label className="text-[11px] font-bold tracking-[.06em] uppercase text-[#5e5e5e] block mb-1.5">Scheduled Departure</label>
                  <DateTimePicker value={form.scheduled_departure} error={localErrors.scheduled_departure} onChange={(e) => {
                    const depTime = e.target.value;
                    const opDate = depTime ? (depTime.includes('T') ? depTime.split('T')[0] : depTime.split(' ')[0]) : '';
                    setForm((f) => {
                      const nextForm = { ...f, scheduled_departure: depTime, date: opDate || f.date };
                      const routeObj = routes.find((r) => String(r.id) === String(f.flight));
                      if (routeObj && depTime) {
                        const computedArr = calculateArrival(routeObj, depTime);
                        if (computedArr) nextForm.scheduled_arrival = computedArr;
                      }
                      return nextForm;
                    });
                    if (depTime) clearError('scheduled_departure');
                  }} />
                  {localErrors.scheduled_departure && <p style={{ fontSize: 12, color: '#b91c1c', marginTop: 4 }}>{localErrors.scheduled_departure}</p>}
                </div>
                <div>
                  <label className="text-[11px] font-bold tracking-[.06em] uppercase text-[#5e5e5e] block mb-1.5">Scheduled Arrival</label>
                  <DateTimePicker value={form.scheduled_arrival} error={localErrors.scheduled_arrival} onChange={(e) => {
                    setForm((f) => ({ ...f, scheduled_arrival: e.target.value }));
                    if (e.target.value) clearError('scheduled_arrival');
                  }} />
                  {localErrors.scheduled_arrival && <p style={{ fontSize: 12, color: '#b91c1c', marginTop: 4 }}>{localErrors.scheduled_arrival}</p>}
                </div>
                <ComboInput id="fi_gate" label="Boarding Gate" placeholder="e.g. G12"
                  value={form.boarding_gate} options={gateOptions}
                  onChange={(e) => { setForm((f) => ({ ...f, boarding_gate: e.target.value })); if (e.target.value) clearError('boarding_gate'); }}
                  error={localErrors.boarding_gate} />
                <ComboInput id="fi_dep_term" label="Departure Terminal" placeholder="e.g. Terminal 1"
                  value={form.departure_terminal} options={depTerminalOptions}
                  onChange={(e) => { setForm((f) => ({ ...f, departure_terminal: e.target.value })); if (e.target.value) clearError('departure_terminal'); }}
                  error={localErrors.departure_terminal} />
                <ComboInput id="fi_arr_term" label="Arrival Terminal" placeholder="e.g. Terminal 2"
                  value={form.arrival_terminal} options={arrTerminalOptions}
                  onChange={(e) => { setForm((f) => ({ ...f, arrival_terminal: e.target.value })); if (e.target.value) clearError('arrival_terminal'); }}
                  error={localErrors.arrival_terminal} />
              </div>

              <div className="flex flex-wrap items-center justify-between gap-3 pt-6 border-t border-slate-200 mt-8">
                <button type="button" className="btn-secondary" onClick={closeForm}><X size={14} /> Cancel</button>

                <div className="flex flex-wrap items-center gap-2">
                  <button type="submit" className="btn-secondary" disabled={actionLoading} onClick={(e) => handleSubmit(e, null)}>
                    <Save size={14} /> {actionLoading ? 'Saving…' : 'Save'}
                  </button>

                  <button
                    type="button"
                    disabled={actionLoading}
                    onClick={(e) => handleSubmit(e, 'fares', true)}
                    className="px-4 py-2 rounded-xl bg-[#705d00] hover:bg-[#5a4b00] text-white font-bold text-xs flex items-center gap-1.5 shadow-md cursor-pointer transition-all border-none"
                  >
                    Save & Next <ChevronRight size={14} />
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}

      <DeleteConfirmationModal
        isOpen={deleteItem !== null}
        loading={deleteLoading}
        title="Delete Flight Instance"
        message="Are you sure you want to delete this flight instance?"
        details={deleteItem ? { 'FLIGHT NO': deleteItem.flight_no, DATE: deleteItem.date, AIRCRAFT: deleteItem.aircraft_registration } : null}
        onClose={() => setDeleteItem(null)}
        onConfirm={confirmDelete}
      />
    </div>
  );
}

import { useEffect, useState, useCallback, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Link, useNavigate } from 'react-router-dom';
import { fetchFlightInstances, updateFlightInstance, fetchAirports } from '@/admin/_core/store/adminSlices';
import { Select } from '@/components/ui/Select';
import DatePicker from '@/components/ui/DatePicker';
import { Edit2, Eye, Plane, RefreshCw, AlertCircle, Search, X, SlidersHorizontal, MapPin } from 'lucide-react';
import toast from 'react-hot-toast';
import { parseApiError } from '@/utils/errorUtils';
import { Pagination } from '@/components/ui/Pagination';
import { useTranslation } from 'react-i18next';

import '@/admin/_core/styles/admin.css';
import { INR } from '@/utils/formatters';
import StatusBadge from '@/admin/_core/components/StatusBadge';
import PageLoader from '@/admin/_core/components/PageLoader';
const fmtDT = (iso) => new Date(iso).toLocaleString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false });

const getStatusOptions = (t) => [
    { value: '', label: t("flights.allStatuses", { defaultValue: 'All Statuses' }) },
    { value: 'SCHEDULED', label: 'Scheduled' },
    { value: 'DELAYED', label: 'Delayed' },
    { value: 'CANCELLED', label: 'Cancelled' },
    { value: 'BOARDING', label: 'Boarding' },
    { value: 'DEPARTED', label: 'Departed' },
    { value: 'ARRIVED', label: 'Arrived' },
];

export default function FlightOverviewPage() {
    const { t } = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();

    // Using flightInstance slice for live data
    const { items: flights, count, loading, actionLoading, error } = useSelector(s => s.flightInstance);
    const { items: airports = [] } = useSelector(s => s.airport || {});

    const [currentPage, setCurrentPage] = useState(1);
    const [sourceFocus, setSourceFocus] = useState(false);
    const [destFocus, setDestFocus] = useState(false);
    const PAGE_SIZE = 10;
    const totalPages = Math.ceil((count || 0) / PAGE_SIZE);

    const [editTarget, setEditTarget] = useState(null);
    const [editStatus, setEditStatus] = useState('');
    const [editDelay, setEditDelay] = useState(0);
    const [confirmOpen, setConfirmOpen] = useState(false);

    // Active filter/sort state
    const [activeSearch, setActiveSearch] = useState('');
    const [statusFilter, setStatusFilter] = useState('');
    const [dateFilter, setDateFilter] = useState('');
    const [arrivalDateFilter, setArrivalDateFilter] = useState('');
    const [sourceFilter, setSourceFilter] = useState('');
    const [destFilter, setDestFilter] = useState('');
    const [sortBy, setSortBy] = useState('scheduled_departure');
    const [sortOrder, setSortOrder] = useState('desc');

    // Input state for inline quick search
    const [searchInput, setSearchInput] = useState('');

    // Modal open/close states
    const [filterOpen, setFilterOpen] = useState(false);

    // Draft states for advanced filters modal
    const [draftStatus, setDraftStatus] = useState('');
    const [draftDate, setDraftDate] = useState('');
    const [draftArrivalDate, setDraftArrivalDate] = useState('');
    const [draftSource, setDraftSource] = useState('');
    const [draftDest, setDraftDest] = useState('');
    const [draftSortBy, setDraftSortBy] = useState('scheduled_departure');
    const [draftSortOrder, setDraftSortOrder] = useState('desc');

    const buildParams = useCallback((search, status, date, arrivalDate, source, dest, sortingBy, sortingOrder) => {
        const p = {};
        if (search) p.search = search;
        if (status) p.status = status;
        if (date) p.date = date;
        if (arrivalDate) p.arrival_date = arrivalDate;
        if (source) p.source = source;
        if (dest) p.destination = dest;

        // Sort direction prefix logic
        const orderingPrefix = sortingOrder === 'desc' ? '-' : '';
        p.ordering = `${orderingPrefix}${sortingBy}`;

        return p;
    }, []);

    const fetchFiltered = useCallback((page = 1, params) => {
        dispatch(fetchFlightInstances({ page, page_size: PAGE_SIZE, ...params }));
    }, [dispatch]);

    useEffect(() => {
        fetchFiltered(1, buildParams('', '', '', '', '', '', 'scheduled_departure', 'desc'));
        dispatch(fetchAirports({ page_size: 500 }));
    }, [fetchFiltered, buildParams, dispatch]); // initial load only

    // Lock background page scroll when any modal is open
    const anyModalOpen = filterOpen || (!!editTarget && !confirmOpen) || confirmOpen;
    useEffect(() => {
        if (anyModalOpen) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = '';
        }
        return () => {
            document.body.style.overflow = '';
        };
    }, [anyModalOpen]);

    // Quick search input change handler (only updates local state, fetching happens on submit/clear)
    const handleSearchChange = (e) => {
        setSearchInput(e.target.value);
    };

    const getAirportSuggestions = (query) => {
        if (!query || query.trim().length < 1) return [];
        const cleanQuery = query.toLowerCase().trim();
        return airports.filter(a => 
            a.iata_code?.toLowerCase().includes(cleanQuery) || 
            a.city?.toLowerCase().includes(cleanQuery) || 
            a.airport_name?.toLowerCase().includes(cleanQuery)
        ).slice(0, 5);
    };

    const handleOpenFilters = () => {
        setDraftStatus(statusFilter);
        setDraftDate(dateFilter);
        setDraftArrivalDate(arrivalDateFilter);
        setDraftSource(sourceFilter);
        setDraftDest(destFilter);
        setDraftSortBy(sortBy);
        setDraftSortOrder(sortOrder);
        setFilterOpen(true);
    };

    const handleApplyFilters = () => {
        setStatusFilter(draftStatus);
        setDateFilter(draftDate);
        setArrivalDateFilter(draftArrivalDate);
        setSourceFilter(draftSource);
        setDestFilter(draftDest);
        setSortBy(draftSortBy);
        setSortOrder(draftSortOrder);

        setCurrentPage(1);
        fetchFiltered(1, buildParams(activeSearch, draftStatus, draftDate, draftArrivalDate, draftSource, draftDest, draftSortBy, draftSortOrder));
        setFilterOpen(false);
    };

    const handleClearFilters = () => {
        setSearchInput('');
        setActiveSearch('');
        setStatusFilter('');
        setDateFilter('');
        setArrivalDateFilter('');
        setSourceFilter('');
        setDestFilter('');
        setSortBy('scheduled_departure');
        setSortOrder('desc');

        // Also reset drafts
        setDraftStatus('');
        setDraftDate('');
        setDraftArrivalDate('');
        setDraftSource('');
        setDraftDest('');
        setDraftSortBy('scheduled_departure');
        setDraftSortOrder('desc');

        setCurrentPage(1);
        fetchFiltered(1, buildParams('', '', '', '', '', '', 'scheduled_departure', 'desc'));
        setFilterOpen(false);
    };

    const handleRemoveFilter = (filterKey) => {
        let nextSearch = activeSearch;
        let nextStatus = statusFilter;
        let nextDate = dateFilter;
        let nextArrivalDate = arrivalDateFilter;
        let nextSource = sourceFilter;
        let nextDest = destFilter;
        let nextSortBy = sortBy;
        let nextSortOrder = sortOrder;

        if (filterKey === 'search') {
            nextSearch = '';
            setSearchInput('');
            setActiveSearch('');
        } else if (filterKey === 'status') {
            nextStatus = '';
            setStatusFilter('');
        } else if (filterKey === 'date') {
            nextDate = '';
            setDateFilter('');
        } else if (filterKey === 'arrivalDate') {
            nextArrivalDate = '';
            setArrivalDateFilter('');
        } else if (filterKey === 'source') {
            nextSource = '';
            setSourceFilter('');
        } else if (filterKey === 'dest') {
            nextDest = '';
            setDestFilter('');
        } else if (filterKey === 'sort') {
            nextSortBy = 'scheduled_departure';
            nextSortOrder = 'desc';
            setSortBy('scheduled_departure');
            setSortOrder('desc');
        }

        setCurrentPage(1);
        fetchFiltered(1, buildParams(nextSearch, nextStatus, nextDate, nextArrivalDate, nextSource, nextDest, nextSortBy, nextSortOrder));
    };

    const hasActiveFilters = !!(
        activeSearch ||
        statusFilter ||
        dateFilter ||
        arrivalDateFilter ||
        sourceFilter ||
        destFilter ||
        sortBy !== 'scheduled_departure' ||
        sortOrder !== 'desc'
    );

    const handlePageChange = (page) => {
        setCurrentPage(page);
        fetchFiltered(page, buildParams(activeSearch, statusFilter, dateFilter, arrivalDateFilter, sourceFilter, destFilter, sortBy, sortOrder));
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const handleStatusUpdate = async () => {
        if (!editTarget || !editStatus) return;
        setConfirmOpen(false);
        try {
            await dispatch(updateFlightInstance({
                id: editTarget.id,
                data: { status: editStatus, delay_minutes: Number(editDelay) || 0 }
            })).unwrap();

            const delayMsg = editDelay > 0 ? ` — delayed by ${editDelay} min` : '';
            toast.success(`Flight status updated to ${editStatus}${delayMsg}`);
            setEditTarget(null);
            fetchFiltered(currentPage, buildParams(activeSearch, statusFilter, dateFilter, arrivalDateFilter, sourceFilter, destFilter, sortBy, sortOrder));
        } catch (err) {
            toast.error(parseApiError(err, 'Failed to update flight status'));
        }
    };

    return (
        <div className="admin-page">
            <div className="admin-container">

                {/* Header */}
                <div className="flex justify-between items-start flex-wrap gap-4 mb-8">
                    <div>
                        <h1 className="admin-page-title">{t("admin.overviewTitle", { defaultValue: 'Flight Overview' })}</h1>
                        <p className="admin-page-subtitle">{t("admin.overviewSubtitle", { defaultValue: 'Monitor live flight instances, update statuses and check schedules.' })}</p>
                    </div>
                </div>

                {/* Main Control & Search Bar */}
                <div className="glass-card" style={{ borderRadius: 16, padding: '14px 20px', marginBottom: 12, display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap', overflow: 'visible' }}>
                    {/* Quick Search */}
                    <form
                        onSubmit={(e) => {
                            e.preventDefault();
                            setActiveSearch(searchInput);
                            setCurrentPage(1);
                            fetchFiltered(1, buildParams(searchInput, statusFilter, dateFilter, arrivalDateFilter, sourceFilter, destFilter, sortBy, sortOrder));
                        }}
                        style={{ display: 'flex', alignItems: 'center', gap: 8, flex: '1 1 300px', maxWidth: 480 }}
                    >
                        <div className="admin-toolbar-search">
                            <Search size={14} className="search-icon" />
                            <input
                                className="filter-input"
                                type="text"
                                placeholder={t("admin.searchPlaceholder", { defaultValue: 'Search flight no., airline, airport...' })}
                                value={searchInput}
                                onChange={handleSearchChange}
                            />
                            {searchInput && (
                                <button
                                    type="button"
                                    className="clear-search-btn"
                                    onClick={() => {
                                        setSearchInput('');
                                        setActiveSearch('');
                                        setCurrentPage(1);
                                        fetchFiltered(1, buildParams('', statusFilter, dateFilter, arrivalDateFilter, sourceFilter, destFilter, sortBy, sortOrder));
                                    }}
                                    title="Clear search"
                                >
                                    <X size={13} />
                                </button>
                            )}
                        </div>
                        <button
                            type="submit"
                            className="btn-primary"
                            style={{ padding: '7px 14px', fontSize: 13, flexShrink: 0 }}
                        >
                            {t("admin.search", { defaultValue: 'Search' })}
                        </button>
                    </form>

                    <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                        {/* Filter & Sort Modal Button */}
                        <button
                            onClick={handleOpenFilters}
                            style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '10px 20px', background: 'rgba(255,255,255,0.7)', border: '1.5px solid rgba(0,0,0,0.08)', borderRadius: 12, fontSize: 14, fontWeight: 600, color: '#1a1c1d', cursor: 'pointer', transition: 'all 0.2s', boxShadow: '0 2px 8px rgba(0,0,0,0.02)' }}
                            onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.9)'; e.currentTarget.style.borderColor = 'rgba(112,93,0,0.2)'; }}
                            onMouseLeave={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.7)'; e.currentTarget.style.borderColor = 'rgba(0,0,0,0.08)'; }}
                        >
                            <SlidersHorizontal size={15} color="#705d00" />
                            <span>{t("admin.filtersAndSorting", { defaultValue: 'Filters & Sorting' })}</span>
                            {hasActiveFilters && (
                                <span style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', minWidth: 18, height: 18, borderRadius: '50%', background: '#705d00', color: '#fff', fontSize: 10, fontWeight: 700, padding: '0 2px' }}>
                                    {
                                        (statusFilter ? 1 : 0) +
                                        (dateFilter ? 1 : 0) +
                                        (arrivalDateFilter ? 1 : 0) +
                                        (sourceFilter ? 1 : 0) +
                                        (destFilter ? 1 : 0) +
                                        (sortBy !== 'scheduled_departure' || sortOrder !== 'desc' ? 1 : 0)
                                    }
                                </span>
                            )}
                        </button>

                        {/* Clear All quick button */}
                        {hasActiveFilters && (
                            <button
                                onClick={handleClearFilters}
                                style={{ padding: '10px 16px', background: 'rgba(220,38,38,0.08)', border: '1.5px solid rgba(220,38,38,0.15)', borderRadius: 12, fontSize: 14, fontWeight: 600, color: '#dc2626', cursor: 'pointer', transition: 'background 0.2s' }}
                                onMouseEnter={e => e.currentTarget.style.background = 'rgba(220,38,38,0.12)'}
                                onMouseLeave={e => e.currentTarget.style.background = 'rgba(220,38,38,0.08)'}
                            >
                                {t("admin.clearAll", { defaultValue: 'Clear All' })}
                            </button>
                        )}
                    </div>
                </div>



                {/* Error */}
                {error && (
                    <div className="admin-error">
                        <AlertCircle size={16} />{error}
                    </div>
                )}

                {/* Table */}
                <div className="glass-card" style={{ borderRadius: 20, overflow: 'hidden' }}>
                    {loading ? (
                        <PageLoader fullScreen={true} label={t("admin.fetching", { defaultValue: 'Fetching flights...' })} />
                    ) : flights.length === 0 ? (
                        <div style={{ padding: '64px 24px', textAlign: 'center' }}>
                            <Plane size={44} color="#d0c6ab" style={{ margin: '0 auto 16px' }} />
                            <p style={{ fontWeight: 700, fontSize: 16, color: '#5e5e5e' }}>
                                {hasActiveFilters ? t("admin.noMatch", { defaultValue: 'No flights match your filters.' }) : t("admin.noFlights", { defaultValue: 'No flights registered yet.' })}
                            </p>
                        </div>
                    ) : (
                        <div style={{ overflowX: 'auto' }}>
                            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                                <thead>
                                    <tr style={{ background: 'rgba(255,255,255,0.5)', borderBottom: '1px solid rgba(0,0,0,0.06)' }}>
                                        {[t("admin.table.flightNo", { defaultValue: 'Flight No.' }), t("admin.table.route", { defaultValue: 'Route' }), t("admin.table.times", { defaultValue: 'Times (Dep / Arr)' }), t("admin.table.gate", { defaultValue: 'Gate/Terminal' }), t("admin.table.status", { defaultValue: 'Status' }), t("admin.table.actions", { defaultValue: 'Actions' })].map(h => (
                                            <th key={h} style={{ padding: '14px 16px', fontSize: 11, fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase', color: '#5e5e5e', whiteSpace: 'nowrap' }}>{h}</th>
                                        ))}
                                    </tr>
                                </thead>
                                <tbody>
                                    {flights.map(f => (
                                        <tr key={f.id} className="admin-row" style={{ borderBottom: '1px solid rgba(0,0,0,0.05)', transition: 'background 0.2s' }}>
                                            <td style={{ padding: '16px', fontWeight: 800, fontSize: 14, color: '#1a1c1d', whiteSpace: 'nowrap' }}>{f.flight_number}</td>
                                            <td style={{ padding: '16px', fontWeight: 700, fontSize: 14, color: '#1a1c1d', whiteSpace: 'nowrap' }}>
                                                {f.route?.source?.iata_code}<span style={{ color: '#705d00', margin: '0 4px' }}>→</span>{f.route?.destination?.iata_code}
                                            </td>
                                            <td style={{ padding: '16px', fontSize: 12, color: '#5e5e5e', lineHeight: 1.7 }}>
                                                <div>Dep: {fmtDT(f.scheduled_departure)}</div>
                                                <div>Arr: {fmtDT(f.scheduled_arrival)}</div>
                                            </td>
                                            <td style={{ padding: '16px', fontSize: 13, color: '#5e5e5e', whiteSpace: 'nowrap' }}>
                                                <div>Gate: {f.boarding_gate || '-'}</div>
                                                <div>Term: {f.departure_terminal || '-'} / {f.arrival_terminal || '-'}</div>
                                            </td>
                                            <td style={{ padding: '16px' }}><StatusBadge status={f.status} /></td>
                                            <td style={{ padding: '16px' }}>
                                                <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                                                    <button className="act" onClick={() => { setEditTarget(f); setEditStatus(f.status); setEditDelay(f.delay_minutes || 0); }} title="Update Status" style={{ padding: 8, borderRadius: 8, color: '#5e5e5e', background: 'transparent', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', transition: 'background 0.2s' }}><Edit2 size={16} /></button>
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}

                    {!loading && flights.length > 0 && (
                        <div style={{ padding: '0 20px 20px' }}>
                            <Pagination currentPage={currentPage} totalPages={totalPages} totalCount={count} pageSize={PAGE_SIZE} onPageChange={handlePageChange} />
                        </div>
                    )}
                </div>

                {/* Advanced Filters & Sorting Modal */}
                {filterOpen && (
                    <div className="admin-modal-overlay" onClick={() => setFilterOpen(false)}>
                        <div className="admin-modal" onClick={(e) => e.stopPropagation()}>
                            <div className="admin-modal-header">
                                <h2 className="admin-modal-title">
                                    {t("admin.filtersAndSorting", { defaultValue: 'Filters & Sorting' })}
                                </h2>
                                <button className="btn-icon" onClick={() => setFilterOpen(false)}><X size={16} /></button>
                            </div>

                            <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
                                {/* Sorting Section */}
                                <div>
                                    <label style={{ display: 'block', fontSize: 11, fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase', color: '#5e5e5e', marginBottom: 8 }}>{t("admin.modals.sortBy", { defaultValue: 'Sort By' })}</label>
                                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                                        <Select
                                            options={[
                                                { value: 'scheduled_departure', label: 'Departure Time' },
                                                { value: 'scheduled_arrival', label: 'Arrival Time' },
                                                { value: 'flight__flight_number', label: 'Flight Number' },
                                                { value: 'status', label: 'Status' }
                                            ]}
                                            value={draftSortBy}
                                            onChange={(e) => setDraftSortBy(e.target.value)}
                                        />
                                        <Select
                                            options={[
                                                { value: 'asc', label: 'Ascending' },
                                                { value: 'desc', label: 'Descending' }
                                            ]}
                                            value={draftSortOrder}
                                            onChange={(e) => setDraftSortOrder(e.target.value)}
                                        />
                                    </div>
                                </div>


                                {/* Routing Section */}
                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                                    <div style={{ position: 'relative' }}>
                                        <label style={{ display: 'block', fontSize: 11, fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase', color: '#5e5e5e', marginBottom: 6 }}>{t("admin.modals.sourceAirport", { defaultValue: 'Source Airport (IATA)' })}</label>
                                        <div style={{ position: 'relative' }}>
                                            <MapPin size={14} style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', color: '#9e9488', pointerEvents: 'none' }} />
                                            <input
                                                className="filter-input"
                                                type="text"
                                                placeholder="e.g. BOM"
                                                maxLength={5}
                                                value={draftSource}
                                                onChange={(e) => setDraftSource(e.target.value)}
                                                onFocus={() => setSourceFocus(true)}
                                                onBlur={() => setSourceFocus(false)}
                                                style={{ width: '100%', padding: '9px 12px 9px 34px', background: 'rgba(255,255,255,0.65)', border: '1.5px solid rgba(0,0,0,0.1)', borderRadius: 10, fontSize: 14, color: '#1a1c1d', fontFamily: 'Inter,sans-serif', outline: 'none', transition: 'border-color 0.2s, box-shadow 0.2s', boxSizing: 'border-box' }}
                                            />
                                        </div>
                                        {sourceFocus && getAirportSuggestions(draftSource).length > 0 && (
                                            <div style={{ position: 'absolute', top: '100%', left: 0, right: 0, zIndex: 1000, background: '#fff', border: '1px solid rgba(0,0,0,0.1)', borderRadius: 8, maxHeight: 180, overflowY: 'auto', boxShadow: '0 4px 12px rgba(0,0,0,0.1)', marginTop: 4 }}>
                                                {getAirportSuggestions(draftSource).map(apt => (
                                                    <div
                                                        key={apt.id}
                                                        onMouseDown={() => {
                                                            setDraftSource(apt.iata_code);
                                                            setSourceFocus(false);
                                                        }}
                                                        style={{ padding: '8px 12px', cursor: 'pointer', borderBottom: '1px solid rgba(0,0,0,0.04)', display: 'flex', flexDirection: 'column', gap: 2 }}
                                                        onMouseEnter={e => e.currentTarget.style.background = 'rgba(112,93,0,0.06)'}
                                                        onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                                                    >
                                                        <span style={{ fontWeight: 700, color: '#705d00', fontSize: 13 }}>{apt.iata_code}</span>
                                                        <span style={{ fontSize: 11, color: '#5e5e5e' }}>{apt.city} ({apt.airport_name})</span>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                    <div style={{ position: 'relative' }}>
                                        <label style={{ display: 'block', fontSize: 11, fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase', color: '#5e5e5e', marginBottom: 6 }}>{t("admin.modals.destAirport", { defaultValue: 'Destination Airport (IATA)' })}</label>
                                        <div style={{ position: 'relative' }}>
                                            <MapPin size={14} style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', color: '#9e9488', pointerEvents: 'none' }} />
                                            <input
                                                className="filter-input"
                                                type="text"
                                                placeholder="e.g. DEL"
                                                maxLength={5}
                                                value={draftDest}
                                                onChange={(e) => setDraftDest(e.target.value)}
                                                onFocus={() => setDestFocus(true)}
                                                onBlur={() => setDestFocus(false)}
                                                style={{ width: '100%', padding: '9px 12px 9px 34px', background: 'rgba(255,255,255,0.65)', border: '1.5px solid rgba(0,0,0,0.1)', borderRadius: 10, fontSize: 14, color: '#1a1c1d', fontFamily: 'Inter,sans-serif', outline: 'none', transition: 'border-color 0.2s, box-shadow 0.2s', boxSizing: 'border-box' }}
                                            />
                                        </div>
                                        {destFocus && getAirportSuggestions(draftDest).length > 0 && (
                                            <div style={{ position: 'absolute', top: '100%', left: 0, right: 0, zIndex: 1000, background: '#fff', border: '1px solid rgba(0,0,0,0.1)', borderRadius: 8, maxHeight: 180, overflowY: 'auto', boxShadow: '0 4px 12px rgba(0,0,0,0.1)', marginTop: 4 }}>
                                                {getAirportSuggestions(draftDest).map(apt => (
                                                    <div
                                                        key={apt.id}
                                                        onMouseDown={() => {
                                                            setDraftDest(apt.iata_code);
                                                            setDestFocus(false);
                                                        }}
                                                        style={{ padding: '8px 12px', cursor: 'pointer', borderBottom: '1px solid rgba(0,0,0,0.04)', display: 'flex', flexDirection: 'column', gap: 2 }}
                                                        onMouseEnter={e => e.currentTarget.style.background = 'rgba(112,93,0,0.06)'}
                                                        onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                                                    >
                                                        <span style={{ fontWeight: 700, color: '#705d00', fontSize: 13 }}>{apt.iata_code}</span>
                                                        <span style={{ fontSize: 11, color: '#5e5e5e' }}>{apt.city} ({apt.airport_name})</span>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {/* Status and Dates */}
                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                                    <Select
                                        label={t("admin.table.status", { defaultValue: 'Status' })}
                                        options={getStatusOptions(t)}
                                        value={draftStatus}
                                        onChange={(e) => setDraftStatus(e.target.value)}
                                    />
                                    <div />
                                </div>

                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                                    <div>
                                        <DatePicker
                                            label={t("admin.modals.departureDate", { defaultValue: 'Departure Date' })}
                                            placeholder={t("admin.modals.anyDate", { defaultValue: 'Any date' })}
                                            value={draftDate}
                                            onChange={(val) => setDraftDate(val)}
                                        />
                                    </div>
                                    <div>
                                        <DatePicker
                                            label={t("admin.modals.arrivalDate", { defaultValue: 'Arrival Date' })}
                                            placeholder={t("admin.modals.anyDate", { defaultValue: 'Any date' })}
                                            value={draftArrivalDate}
                                            onChange={(val) => setDraftArrivalDate(val)}
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="flex flex-wrap items-center justify-end gap-3 pt-6 border-t border-slate-200 mt-8">
                                <button
                                    onClick={handleClearFilters}
                                    className="btn-secondary"
                                >
                                    {t("admin.modals.resetAll", { defaultValue: 'Reset All' })}
                                </button>
                                <button
                                    onClick={handleApplyFilters}
                                    className="btn-primary"
                                >
                                    {t("admin.modals.applyFilters", { defaultValue: 'Apply Filters' })}
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* Edit Status Modal */}
                {!!editTarget && !confirmOpen && (
                    <div className="admin-modal-overlay" onClick={() => setEditTarget(null)}>
                        <div className="admin-modal" onClick={(e) => e.stopPropagation()}>
                            <div className="admin-modal-header">
                                <h2 className="admin-modal-title">Update Flight Status</h2>
                                <button className="btn-icon" onClick={() => setEditTarget(null)}><X size={16} /></button>
                            </div>

                            <div style={{ display: 'flex', flexDirection: 'column', gap: 18, padding: '4px 0' }}>
                                {/* Flight identifier banner */}
                                <div style={{ background: 'rgba(112,93,0,0.06)', border: '1px solid rgba(112,93,0,0.12)', borderRadius: 10, padding: '10px 14px', display: 'flex', alignItems: 'center', gap: 10 }}>
                                    <span style={{ fontSize: 18, fontWeight: 900, color: '#1a1c1d', letterSpacing: '-0.02em' }}>{editTarget.flight_number}</span>
                                    <span style={{ fontSize: 13, color: '#9e9488' }}>·</span>
                                    <span style={{ fontSize: 13, color: '#5e5e5e', fontWeight: 500 }}>
                                        {editTarget.route?.source?.iata_code} → {editTarget.route?.destination?.iata_code}
                                    </span>
                                </div>

                                {/* Status + Delay side by side */}
                                <div style={{ display: 'grid', gridTemplateColumns: editStatus === 'DELAYED' ? '1.4fr 1fr' : '1fr', gap: 14, alignItems: 'start' }}>
                                    <Select
                                        label="New Status"
                                        options={getStatusOptions(t).filter(o => o.value !== '')}
                                        value={editStatus}
                                        onChange={(e) => {
                                            const nextStatus = e.target.value;
                                            setEditStatus(nextStatus);
                                            // Auto reset delay to 0 if they change status away from DELAYED
                                            if (nextStatus !== 'DELAYED') {
                                                setEditDelay(0);
                                            }
                                        }}
                                    />

                                    {/* Delay stepper */}
                                    {editStatus === 'DELAYED' && (
                                        <div style={{ display: 'flex', flexDirection: 'column', gap: 6, maxWidth: 140 }}>
                                            <label style={{ fontSize: 11, fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase', color: '#5e5e5e' }}>Delay (min)</label>
                                            <div style={{ display: 'flex', alignItems: 'center', border: '1.5px solid rgba(0,0,0,0.15)', borderRadius: 9, overflow: 'hidden', background: '#fff', height: 38 }}>
                                                <button
                                                    type="button"
                                                    onClick={() => { const v = Math.max(0, editDelay - 5); setEditDelay(v); if (v === 0 && editStatus === 'DELAYED') setEditStatus('SCHEDULED'); }}
                                                    style={{ width: 34, height: '100%', border: 'none', background: 'rgba(0,0,0,0.03)', borderRight: '1px solid rgba(0,0,0,0.09)', fontSize: 18, fontWeight: 700, cursor: 'pointer', color: '#5e5e5e', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}
                                                >−</button>
                                                <input
                                                    type="text"
                                                    inputMode="numeric"
                                                    value={editDelay}
                                                    onChange={e => {
                                                        const v = Math.max(0, parseInt(e.target.value.replace(/\D/g, '')) || 0);
                                                        setEditDelay(v);
                                                        if (v > 0) setEditStatus('DELAYED');
                                                    }}
                                                    style={{ flex: 1, minWidth: 0, width: '100%', border: 'none', outline: 'none', textAlign: 'center', fontSize: 15, fontWeight: 800, fontFamily: 'Inter, sans-serif', color: '#1a1c1d', background: 'transparent' }}
                                                />
                                                <button
                                                    type="button"
                                                    onClick={() => { const v = Math.min(999, editDelay + 5); setEditDelay(v); setEditStatus('DELAYED'); }}
                                                    style={{ width: 34, height: '100%', border: 'none', background: 'rgba(0,0,0,0.03)', borderLeft: '1px solid rgba(0,0,0,0.09)', fontSize: 18, fontWeight: 700, cursor: 'pointer', color: '#5e5e5e', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}
                                                >+</button>
                                            </div>
                                            {editDelay > 0 ? (
                                                <span style={{ fontSize: 10, color: '#92400e', fontWeight: 600 }}>⚠ Auto-sets to Delayed</span>
                                            ) : (
                                                <span style={{ fontSize: 10, color: '#9e9488' }}>0 = no delay</span>
                                            )}
                                        </div>
                                    )}
                                </div>

                                <div className="flex flex-wrap items-center justify-end gap-3 pt-6 border-t border-slate-200 mt-4">
                                    <button
                                        onClick={() => setEditTarget(null)}
                                        className="btn-secondary"
                                    >
                                        Cancel
                                    </button>
                                    <button
                                        onClick={() => {
                                            if (editStatus === 'DELAYED' && Number(editDelay) <= 0) {
                                                toast.error("Please enter a delay greater than 0 minutes for Delayed status.");
                                                return;
                                            }
                                            if (editStatus !== 'DELAYED' && Number(editDelay) > 0) {
                                                toast.error("Delay minutes can only be set when flight status is Delayed.");
                                                return;
                                            }
                                            setConfirmOpen(true);
                                        }}
                                        disabled={actionLoading}
                                        className="btn-primary"
                                        style={{ opacity: actionLoading ? 0.7 : 1 }}
                                    >
                                        Save
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* Confirmation Modal */}
                {confirmOpen && (
                    <div className="admin-modal-overlay" onClick={() => setConfirmOpen(false)}>
                        <div className="admin-modal" onClick={(e) => e.stopPropagation()}>
                            <div className="admin-modal-header">
                                <h2 className="admin-modal-title">Confirm Update</h2>
                                <button className="btn-icon" onClick={() => setConfirmOpen(false)}><X size={16} /></button>
                            </div>

                            <div style={{ display: 'flex', flexDirection: 'column', gap: 20, padding: '12px 4px' }}>
                                <p style={{ fontSize: 14, color: '#1a1c1d', margin: 0, lineHeight: 1.7 }}>
                                    You are about to update <strong>{editTarget?.flight_number}</strong>:
                                </p>
                                <div style={{ background: 'rgba(112,93,0,0.06)', borderRadius: 10, padding: '14px 16px', display: 'flex', flexDirection: 'column', gap: 8 }}>
                                    <div style={{ fontSize: 13, display: 'flex', justifyContent: 'space-between' }}>
                                        <span style={{ color: '#5e5e5e', fontWeight: 600 }}>Status</span>
                                        <span style={{ fontWeight: 800, color: '#1a1c1d' }}>{editStatus}</span>
                                    </div>
                                    <div style={{ fontSize: 13, display: 'flex', justifyContent: 'space-between' }}>
                                        <span style={{ color: '#5e5e5e', fontWeight: 600 }}>Delay</span>
                                        <span style={{ fontWeight: 800, color: editDelay > 0 ? '#92400e' : '#1a1c1d' }}>
                                            {editDelay > 0 ? `${editDelay} minutes` : 'No delay'}
                                        </span>
                                    </div>
                                </div>
                                <p style={{ fontSize: 12, color: '#9e9488', margin: 0 }}>This will update the live flight record and notify affected passengers.</p>
                                <div className="flex flex-wrap items-center justify-end gap-3 pt-6 border-t border-slate-200 mt-4">
                                    <button
                                        onClick={() => setConfirmOpen(false)}
                                        className="btn-secondary"
                                    >
                                        Go Back
                                    </button>
                                    <button
                                        onClick={handleStatusUpdate}
                                        disabled={actionLoading}
                                        className="btn-primary"
                                        style={{ opacity: actionLoading ? 0.7 : 1 }}
                                    >
                                        {actionLoading ? 'Updating...' : 'Confirm Update'}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

            </div>
        </div>
    );
}

/**
 * FlightRoutesPage — list + create/edit form for FlightRoute with dynamic nested Flight Leg rows.
 * leg_order is auto-assigned by row position.
 * Cross-row layover validation: each leg's departure must be after prev leg's arrival.
 */
import { useEffect, useState, useRef, useCallback } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { Input } from '@/components/ui/Input';
import '@/admin/_core/styles/admin.css';
import DeleteConfirmationModal from '../../_core/DeleteConfirmationModal';
import { Select } from '@/components/ui/Select';
import DateTimePicker from '@/components/ui/DateTimePicker';
import {
  fetchFlightRoutes, fetchFlightRouteDetail, addFlightRoute, updateFlightRoute, removeFlightRoute,
  fetchAirlines, fetchAirports,
  flightRouteActions,
} from '@/admin/_core/store/adminSlices';
import { Pagination } from '@/components/ui/Pagination';
import {
  Plus, Pencil, Trash2, Save, X, AlertCircle, ChevronLeft, ChevronRight,
  Search, PlusCircle, MinusCircle, MapPin,
} from 'lucide-react';
import toast from 'react-hot-toast';
import useDeleteAction from '../../_core/hooks/useDeleteAction';
import { SpinnerLoader } from '@/components/ui/Loaders';
import { parseApiError } from '@/utils/errorUtils';

const ACCENT = '#705d00';
const EMPTY_LEG = { departure_airport: '', arrival_airport: '', flight_duration_minutes: 120, layover_duration_minutes: 0 };

const EMPTY_FORM = {
  flight_no: '', airline: '',
  baggage_weight_allowed_per_person: '20',
  baggage_number_allowed_per_person: '',
  handbag_weight_allowed_per_person: '7',
  legs: [{ ...EMPTY_LEG }],
};

export default function FlightRoutesPage() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { items: routes, loading, actionLoading, count, error, validationErrors } = useSelector((s) => s.flightRoute);
  const { items: airlines } = useSelector((s) => s.airline);
  const { items: airports } = useSelector((s) => s.airport);

  const [showForm, setShowForm] = useState(false);
  const [editId, setEditId] = useState(null);
  const [form, setForm] = useState(EMPTY_FORM);
  const [localErrors, setLocalErrors] = useState({});
  const [search, setSearch] = useState('');
  const [activeSearch, setActiveSearch] = useState('');
  const [isFlightNoFocused, setIsFlightNoFocused] = useState(false);
  const [page, setPage] = useState(1);
  const PAGE_SIZE = 10;

  const load = useCallback((s, p) => {
    dispatch(fetchFlightRoutes({ search: s, page: p, page_size: PAGE_SIZE }));
  }, [dispatch]);

  useEffect(() => {
    load(activeSearch, page);
    dispatch(fetchAirlines({}));
    dispatch(fetchAirports({ page_size: 500 }));
  }, [load, dispatch, activeSearch, page]);

  const airlineOptions = airlines.map((a) => ({ value: a.id, label: `${a.iata_airline_code} – ${a.airline_name}` }));
  const airportOptions = airports.map((a) => ({ value: a.id, label: `${a.iata_code} – ${a.airport_name}` }));

  const openCreate = () => {
    dispatch(flightRouteActions.clearErrors());
    setEditId(null);
    setForm(EMPTY_FORM);
    setLocalErrors({});
    setShowForm(true);
  };

  const openEdit = (route) => {
    dispatch(flightRouteActions.clearErrors());
    setEditId(route.id);
    const selectedAirline = airlines.find((a) => String(a.id) === String(route.airline));
    let numericFlightNo = route.flight_no || '';
    if (selectedAirline && selectedAirline.iata_airline_code) {
      const regex = new RegExp(`^${selectedAirline.iata_airline_code}[-]?`, 'i');
      numericFlightNo = numericFlightNo.replace(regex, '');
    }
    setForm({
      flight_no: numericFlightNo,
      airline: route.airline || '',
      baggage_weight_allowed_per_person: route.baggage_weight_allowed_per_person || '20',
      baggage_number_allowed_per_person: route.baggage_number_allowed_per_person || '',
      handbag_weight_allowed_per_person: route.handbag_weight_allowed_per_person || '7',
      legs: (route.legs || []).map((leg) => ({
        departure_airport: leg.departure_airport,
        arrival_airport: leg.arrival_airport,
        flight_duration_minutes: leg.flight_duration_minutes || 120,
        layover_duration_minutes: leg.layover_duration_minutes || 0,
      })),
    });
    setLocalErrors({});
    setShowForm(true);
  };

  const closeForm = () => { setShowForm(false); setEditId(null); dispatch(flightRouteActions.clearErrors()); };

  // ─── Leg management ─────────────────────────────────────────────────────────
  const addLeg = () => setForm((f) => {
    const newLeg = { ...EMPTY_LEG };
    if (f.legs.length > 0) {
      const prevLeg = f.legs[f.legs.length - 1];
      newLeg.departure_airport = prevLeg.arrival_airport;
      newLeg.layover_duration_minutes = 60; // 1 hour default layover
    }
    return { ...f, legs: [...f.legs, newLeg] };
  });
  const removeLeg = (i) => setForm((f) => ({ ...f, legs: f.legs.filter((_, idx) => idx !== i) }));
  const updateLeg = (i, key, val) =>
    setForm((f) => ({
      ...f,
      legs: f.legs.map((l, idx) => idx === i ? { ...l, [key]: val } : l),
    }));

  // ─── Validation ──────────────────────────────────────────────────────────────
  const validateForm = () => {
    const e = {};
    if (!form.flight_no || !/^\d+$/.test(form.flight_no.trim())) {
      e.flight_no = 'Flight number must be numeric (e.g., 202).';
    }
    if (!form.airline) e.airline = 'Airline is required.';
    if (form.legs.length === 0) e.legs = 'At least one leg is required.';
    if (Number(form.baggage_weight_allowed_per_person) < 0) e.baggage_weight_allowed_per_person = 'Cannot be negative.';
    if (Number(form.handbag_weight_allowed_per_person) < 0) e.handbag_weight_allowed_per_person = 'Cannot be negative.';

    form.legs.forEach((leg, i) => {
      if (!leg.departure_airport) e[`leg_${i}_dep_apt`] = 'Departure airport required.';
      if (!leg.arrival_airport) e[`leg_${i}_arr_apt`] = 'Arrival airport required.';
      if (leg.departure_airport && leg.arrival_airport && leg.departure_airport === leg.arrival_airport) {
        e[`leg_${i}_arr_apt`] = 'Arrival must differ from departure.';
      }
      if (!leg.flight_duration_minutes || Number(leg.flight_duration_minutes) <= 0) {
        e[`leg_${i}_duration`] = 'Flight duration must be > 0 mins.';
      }
      if (i > 0 && Number(leg.layover_duration_minutes) < 0) {
        e[`leg_${i}_layover`] = 'Layover duration cannot be negative.';
      }
    });

    setLocalErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleSubmit = async (e, goNext = false) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!validateForm()) { toast.error('Fix validation errors.'); return; }

    const selectedAirline = airlines.find((a) => String(a.id) === String(form.airline));
    const prefix = selectedAirline ? `${selectedAirline.iata_airline_code}-` : '';
    const fullFlightNo = `${prefix}${form.flight_no.trim()}`;

    const payload = {
      ...form,
      flight_no: fullFlightNo,
      legs: form.legs.map((leg, i) => ({
        ...leg,
        leg_order: i + 1,
        flight_duration_minutes: Number(leg.flight_duration_minutes),
        layover_duration_minutes: i > 0 ? Number(leg.layover_duration_minutes) : 0,
      })),
    };

    let promise;
    if (editId) {
      promise = dispatch(updateFlightRoute({ id: editId, data: payload })).unwrap();
    } else {
      promise = dispatch(addFlightRoute(payload)).unwrap();
    }

    try {
      const res = await promise;
      toast.success('Flight route saved!');
      closeForm();
      const routeId = res?.id || editId;
      if (goNext && routeId) {
        navigate(`/admin/operations/flight-instances?route=${routeId}&autoCreate=1`);
      } else {
        load(activeSearch, page);
      }
    } catch (err) {
      toast.error(parseApiError(err, 'Failed to save.'));
    }
  };

  const { deleteItem, setDeleteItem, deleteLoading, confirmDelete } = useDeleteAction({
    thunk: removeFlightRoute,
    onSuccess: () => load(activeSearch, page),
    successMessage: 'Flight route deleted successfully.',
    errorMessage: 'Failed to delete flight route.'
  });

  const formatMins = (mins) => {
    if (!mins) return '0m';
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return h > 0 ? `${h}h ${m > 0 ? `${m}m` : ''}` : `${m}m`;
  };

  const totalPages = count ? Math.ceil(count / PAGE_SIZE) : 1;

  return (
    <div className="admin-page">
      <div className="admin-container">
        <div className="flex justify-between items-center mb-7">
          <div>
            <h1 className="admin-page-title">Flight Routes</h1>
            <p className="admin-page-subtitle">{count} total routes</p>
          </div>
          <button className="btn-primary" onClick={openCreate} id="add-flight-route-btn">
            <Plus size={15} /> Add Route
          </button>
        </div>

        {/* Search */}
        <form onSubmit={(e) => { e.preventDefault(); setActiveSearch(search); setPage(1); }} className="flex gap-2 mb-5">
          <div className="admin-toolbar-search">
            <Search size={14} className="search-icon" />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search by flight number…" />
          </div>
          <button type="submit" className="btn-primary">Search</button>
        </form>

        {error && (
          <div className="admin-error">
            <AlertCircle size={16} /><span>{typeof error === 'string' ? error : JSON.stringify(error)}</span>
          </div>
        )}

        {/* Table */}
        <div className="admin-card admin-table-wrap">
          {loading ? (
            <SpinnerLoader />
          ) : routes?.length === 0 ? (
            <div className="admin-empty">
              <div className="admin-empty-icon"><MapPin size={28} /></div>
              <h3>No flight routes yet</h3>
              <p>Click &ldquo;Add Route&rdquo; to create one.</p>
              <button className="btn-primary" onClick={openCreate}><Plus size={14} /> Add Route</button>
            </div>
          ) : (
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Flight No</th><th>Airline</th><th>Legs &amp; Duration</th>
                  <th>Baggage (kg)</th><th>Handbag (kg)</th><th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {routes.map((r) => (
                  <tr key={r.id} className="admin-row">
                    <td><strong>{r.flight_no}</strong></td>
                    <td>{r.airline_name || r.airline}</td>
                    <td>
                      {(r.legs || []).map((leg, i) => (
                        <span key={i} className="inline-flex items-center gap-1 mr-1.5 mb-1">
                          {i > 0 && (
                            <span className="text-[10px] text-[#888] bg-black/5 px-1.5 py-px rounded">
                              Layover {formatMins(leg.layover_duration_minutes)}
                            </span>
                          )}
                          <span className="text-[11px] bg-[rgba(112,93,0,0.08)] rounded-md px-2 py-0.5 font-semibold">
                            {leg.departure_airport_iata || leg.departure_airport} → {leg.arrival_airport_iata || leg.arrival_airport}
                            <span className="text-[#666] font-normal ml-1">({formatMins(leg.flight_duration_minutes)})</span>
                          </span>
                        </span>
                      ))}
                    </td>
                    <td>{r.baggage_weight_allowed_per_person}</td>
                    <td>{r.handbag_weight_allowed_per_person}</td>
                    <td className="text-right whitespace-nowrap">
                      <div className="flex gap-1.5 items-center justify-end">
                        <button className="btn-secondary" title="Edit" onClick={() => openEdit(r)} style={{ padding: '6px 8px' }}>
                          <Pencil size={14} />
                        </button>
                         <button className="btn-danger" title="Delete" onClick={() => setDeleteItem(r)} style={{ padding: '6px 8px' }}>
                          <Trash2 size={14} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        <Pagination
          currentPage={page}
          totalPages={totalPages}
          totalCount={count || routes?.length || 0}
          pageSize={PAGE_SIZE}
          onPageChange={(p) => { setPage(p); }}
          entityLabel="routes"
        />
      </div>

      {/* Form Modal */}
      {showForm && (
        <div className="admin-modal-overlay" onClick={closeForm}>
          <div className="admin-modal" onClick={(e) => e.stopPropagation()}>
            <div className="admin-modal-header">
              <h2 className="admin-modal-title">
                {editId ? 'Edit Flight Route' : 'Add Flight Route'}
              </h2>
              <button className="btn-icon" onClick={closeForm}><X size={16} /></button>
            </div>

            {validationErrors && (
              <div className="admin-error">
                <AlertCircle size={16} style={{ flexShrink: 0, marginTop: 2 }} />
                <div className="flex flex-col gap-1">
                  {typeof validationErrors === 'string' ? (
                    <span>{validationErrors}</span>
                  ) : (
                    Object.entries(validationErrors).map(([key, val]) => {
                      const msg = Array.isArray(val) ? val.join(', ') : String(val);
                      return (
                        <div key={key}>
                          <strong className="capitalize">{key.replace('_', ' ')}:</strong> {msg}
                        </div>
                      );
                    })
                  )}
                </div>
              </div>
            )}

            <form onSubmit={handleSubmit}>
              {/* General */}
              <div className="admin-form-grid mb-5">
                 <Select id="airline" label="Airline" options={airlineOptions} value={form.airline}
                  onChange={(e) => {
                    const airlineId = e.target.value;
                    setForm((f) => ({
                      ...f,
                      airline: airlineId,
                      flight_no: '',
                    }));
                  }}
                  error={localErrors.airline} />
                <div className="flex flex-col gap-1.5">
                  <label htmlFor="flight_no" className="text-[11px] font-bold tracking-[0.06em] uppercase text-[#5e5e5e]">
                    Flight Number
                  </label>
                  <div style={{ display: 'flex', alignItems: 'center' }}>
                    {form.airline ? (() => {
                      const selected = airlines.find((a) => String(a.id) === String(form.airline));
                      if (selected) {
                        return (
                          <div style={{
                            padding: '9px 14px',
                            background: 'rgba(0, 0, 0, 0.04)',
                            border: `1.5px solid ${
                              (localErrors.flight_no || validationErrors?.flight_no)
                                ? '#b91c1c'
                                : (isFlightNoFocused ? '#888888' : 'rgba(0,0,0,0.1)')
                            }`,
                            borderRight: 'none',
                            borderRadius: '10px 0 0 10px',
                            fontSize: 14,
                            fontWeight: 700,
                            color: '#5e5e5e',
                            fontFamily: 'Inter, sans-serif',
                            height: '40px',
                            display: 'flex',
                            alignItems: 'center',
                            boxSizing: 'border-box',
                            whiteSpace: 'nowrap',
                            flexShrink: 0
                          }}>
                            {selected.iata_airline_code} -
                          </div>
                        );
                      }
                      return null;
                    })() : null}
                    <input
                      id="flight_no"
                      placeholder={form.airline ? "e.g. 202" : "Select airline first..."}
                      value={form.flight_no}
                      disabled={!!editId || !form.airline}
                      onChange={(e) => {
                        const val = e.target.value.replace(/\D/g, ''); // only allow digits
                        setForm((f) => ({ ...f, flight_no: val }));
                      }}
                      onFocus={() => setIsFlightNoFocused(true)}
                      onBlur={() => setIsFlightNoFocused(false)}
                      style={{
                        flex: 1,
                        background: form.airline
                          ? (isFlightNoFocused ? 'rgba(255,255,255,0.92)' : 'rgba(255,255,255,0.65)')
                          : 'rgba(0,0,0,0.03)',
                        border: `1.5px solid ${
                          (localErrors.flight_no || validationErrors?.flight_no)
                            ? '#b91c1c'
                            : (isFlightNoFocused ? '#888888' : 'rgba(0,0,0,0.1)')
                        }`,
                        borderLeft: form.airline ? 'none' : undefined,
                        borderRadius: form.airline ? '0 10px 10px 0' : '10px',
                        padding: '9px 13px',
                        fontSize: 14,
                        fontWeight: 500,
                        color: '#1a1c1d',
                        fontFamily: 'Inter, sans-serif',
                        outline: 'none',
                        height: '40px',
                        boxSizing: 'border-box',
                        boxShadow: (localErrors.flight_no || validationErrors?.flight_no)
                          ? (isFlightNoFocused ? '0 0 0 3px rgba(185,28,28,0.18)' : '0 0 0 3px rgba(185,28,28,0.1)')
                          : (isFlightNoFocused ? '0 0 0 3px rgba(0,0,0,0.05)' : 'none'),
                        transition: 'border-color 0.2s, box-shadow 0.2s, background 0.2s'
                      }}
                    />
                  </div>
                  {(localErrors.flight_no || validationErrors?.flight_no) && (
                    <p style={{ fontSize: 12, color: '#b91c1c', marginTop: 2, paddingLeft: 2 }}>
                      {localErrors.flight_no || (Array.isArray(validationErrors.flight_no) ? validationErrors.flight_no.join(', ') : validationErrors.flight_no)}
                    </p>
                  )}
                </div>
                <Input id="baggage_weight" label="Baggage Allowance (kg)" type="number"
                  value={form.baggage_weight_allowed_per_person}
                  onChange={(e) => setForm((f) => ({ ...f, baggage_weight_allowed_per_person: e.target.value }))} />
                <Input id="baggage_number" label="Baggage Count (optional)" type="number"
                  value={form.baggage_number_allowed_per_person}
                  onChange={(e) => setForm((f) => ({ ...f, baggage_number_allowed_per_person: e.target.value }))} />
                <Input id="handbag_weight" label="Handbag Allowance (kg)" type="number"
                  value={form.handbag_weight_allowed_per_person}
                  onChange={(e) => setForm((f) => ({ ...f, handbag_weight_allowed_per_person: e.target.value }))} />
              </div>

              {/* Legs */}
              <div className="mb-5">
                <div className="flex justify-between items-center mb-3">
                  <h3 className="m-0 text-[13px] font-bold uppercase tracking-[.06em] text-[#705d00] flex items-center gap-1.5">
                    <MapPin size={14} /> Flight Legs
                  </h3>
                  <button type="button" className="btn-secondary" onClick={addLeg} style={{ fontSize: 12, padding: '5px 10px' }}>
                    <PlusCircle size={13} /> Add Leg
                  </button>
                </div>
                {localErrors.legs && <p className="text-xs text-[#b91c1c] mb-2">{localErrors.legs}</p>}

                {form.legs.map((leg, i) => (
                  <div key={i} className="leg-row">
                    <div className="flex justify-between items-center mb-3">
                      <span className="text-xs font-bold text-[#705d00]">Leg {i + 1}</span>
                      {form.legs.length > 1 && (
                        <button type="button" onClick={() => removeLeg(i)} className="bg-transparent border-none cursor-pointer text-[#b91c1c] p-0">
                          <MinusCircle size={16} />
                        </button>
                      )}
                    </div>
                    {/* Airports row: DEP ──▶ ARR */}
                    <div className="leg-airports-row">
                      <Select id={`dep_apt_${i}`} label="Departure Airport" options={airportOptions}
                        value={leg.departure_airport}
                        onChange={(e) => updateLeg(i, 'departure_airport', e.target.value)}
                        error={localErrors[`leg_${i}_dep_apt`]} />
                      <div className="leg-arrow-container select-none">
                        <div style={{ height: 21 }} />
                        <div className="leg-arrow">→</div>
                      </div>
                      <Select id={`arr_apt_${i}`} label="Arrival Airport" options={airportOptions}
                        value={leg.arrival_airport}
                        onChange={(e) => updateLeg(i, 'arrival_airport', e.target.value)}
                        error={localErrors[`leg_${i}_arr_apt`]} />
                    </div>

                    {/* Duration + Layover row */}
                    <div className="leg-details-row">
                      <Input id={`duration_${i}`} label="Flight Duration (mins)" type="number"
                        placeholder="e.g. 150"
                        value={leg.flight_duration_minutes}
                        onChange={(e) => updateLeg(i, 'flight_duration_minutes', e.target.value)}
                        error={localErrors[`leg_${i}_duration`]} />
                      {i > 0 ? (
                        <Input id={`layover_${i}`} label="Layover Before This Leg (mins)" type="number"
                          placeholder="e.g. 60"
                          value={leg.layover_duration_minutes}
                          onChange={(e) => updateLeg(i, 'layover_duration_minutes', e.target.value)}
                          error={localErrors[`leg_${i}_layover`]} />
                      ) : <div />}
                    </div>
                  </div>
                ))}
              </div>

              <div className="flex flex-wrap items-center justify-between gap-3 pt-6 border-t border-slate-200 mt-8">
                <button type="button" className="btn-secondary" onClick={closeForm}><X size={14} /> Cancel</button>

                <div className="flex flex-wrap items-center gap-2">
                  <button type="button" className="btn-secondary" disabled={actionLoading} onClick={(e) => handleSubmit(e, false)}>
                    <Save size={14} /> {actionLoading ? 'Saving…' : 'Save'}
                  </button>

                  <button
                    type="button"
                    disabled={actionLoading}
                    onClick={(e) => handleSubmit(e, true)}
                    className="px-4 py-2 rounded-xl bg-[#705d00] hover:bg-[#5a4b00] text-white font-bold text-xs flex items-center gap-1.5 shadow-md cursor-pointer transition-all border-none"
                  >
                    Save & Next <ChevronRight size={14} />
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}

      <DeleteConfirmationModal
        isOpen={deleteItem !== null}
        loading={deleteLoading}
        title="Delete Flight Route"
        message="Are you sure you want to delete this flight route?"
        details={deleteItem ? { 'FLIGHT NO': deleteItem.flight_no, AIRLINE: deleteItem.airline_name, ID: deleteItem.id } : null}
        onClose={() => setDeleteItem(null)}
        onConfirm={confirmDelete}
      />
    </div>
  );
}

import { useEffect, useState, useRef, Fragment, useCallback } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useSearchParams, useNavigate } from 'react-router-dom';
import '@/admin/_core/styles/admin.css';
import { Select } from '@/components/ui/Select';
import { Input } from '@/components/ui/Input';
import { fetchFlightInstances, fetchSeats, generateSeats, bulkPriceSeats } from '@/admin/_core/store/adminSlices';
import { Zap, ArrowLeft, AlertTriangle, Check, DollarSign, X, ChevronRight, Utensils } from 'lucide-react';
import toast from 'react-hot-toast';
import { parseApiError } from '@/utils/errorUtils';

const ATTRS = [
  { id: 'window', label: 'Window' },
  { id: 'aisle', label: 'Aisle' },
  { id: 'middle', label: 'Middle' },
];
const CLASS_TABS = ['ALL', 'FIRST', 'BUSINESS', 'ECONOMY'];
const CLASS_LABELS = { ALL: 'All Classes', FIRST: 'First', BUSINESS: 'Business', ECONOMY: 'Economy' };
const CLASS_COLORS = { FIRST: '#fbbf24', BUSINESS: '#818cf8', ECONOMY: '#34d399' };

/* Derive position from seat_number column letter + cabin layout.
   E.g. for Economy 3-3 (ABCDEF): A=window, B=middle, C=aisle | D=aisle, E=middle, F=window
   For Business/First 2-2 (ABCD): A=window, B=aisle | C=aisle, D=window */
function derivePosition(seatNumber, seatClass) {
  if (!seatNumber) return '';
  const letter = seatNumber.slice(-1).toUpperCase();
  if (!/[A-Z]/.test(letter)) return '';
  const colIdx = letter.charCodeAt(0) - 65; // A=0, B=1, ...

  // Determine cols_per_row by class
  let cols;
  if (seatClass === 'ECONOMY') cols = 6;
  else cols = 4; // FIRST and BUSINESS use 2-2

  const leftBlock = Math.floor(cols / 2);

  if (colIdx < leftBlock) {
    // Left block: first=window, last=aisle, else middle
    if (colIdx === 0) return 'window';
    if (colIdx === leftBlock - 1) return 'aisle';
    return 'middle';
  } else {
    // Right block: first=aisle, last=window, else middle
    const ri = colIdx - leftBlock;
    const rightBlock = cols - leftBlock;
    if (ri === 0) return 'aisle';
    if (ri === rightBlock - 1) return 'window';
    return 'middle';
  }
}

function getEffectiveAttrs(seat) {
  // Use DB-stored position first, fallback to derivation
  const pos = seat.position || derivePosition(seat.seat_number, seat.seat_class);
  const attrs = [];
  if (pos) attrs.push(pos.toLowerCase());
  if (seat.exit_row) attrs.push('exit_row');
  if (seat.extra_legroom) attrs.push('extra_legroom');
  return attrs;
}

export default function SeatMapPage() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { items: instances } = useSelector(s => s.flightInstance);
  const { items: seats, loading: seatsLoading, actionLoading } = useSelector(s => s.seat);
  const [searchParams] = useSearchParams();
  const instanceParam = searchParams.get('instance') || '';
  const inFlow = searchParams.get('inFlow') === '1';

  const [selInstance, setSelInstance] = useState(instanceParam);
  const [showMap, setShowMap] = useState(!!instanceParam);
  const [activeFilters, setActiveFilters] = useState([]);
  const [selectedIds, setSelectedIds] = useState(new Set());
  const [classTab, setClassTab] = useState('ALL');
  const [bulkPrice, setBulkPrice] = useState('');

  const mapRef = useRef(null);
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState(null);
  const [dragCur, setDragCur] = useState(null);
  const [dragMode, setDragMode] = useState('add');

  const load = useCallback(id => {
    if (!id) return;
    dispatch(fetchSeats({ flight_instance: id, page_size: 2000 }))
      .unwrap()
      .then(() => setShowMap(true))
      .catch(err => toast.error(parseApiError(err, 'Failed to load seats. Check if the backend is running.')));
  }, [dispatch]);

  useEffect(() => {
    dispatch(fetchFlightInstances({ page_size: 500 }));
  }, [dispatch]);

  useEffect(() => {
    if (instanceParam) {
      setSelInstance(instanceParam);
      load(instanceParam);
    }
  }, [instanceParam, load]);

  const handleInstanceChange = id => {
    setSelInstance(id); setSelectedIds(new Set()); setActiveFilters([]);
    if (id) load(id); else setShowMap(false);
  };

  const handleGenerate = () => {
    if (!selInstance) return;
    toast.promise(dispatch(generateSeats(selInstance)).unwrap(), {
      loading: 'Generating seats…',
      success: r => { load(selInstance); return r?.detail || 'Seats generated successfully!'; },
      error: e => String(e?.detail || e || 'Failed to generate seats.'),
    });
  };

  // Filter by class scope then attribute
  const scopedSeats = classTab === 'ALL' ? seats : seats.filter(s => s.seat_class === classTab);

  const handleFilterToggle = attrId => {
    setActiveFilters(prev => {
      const next = prev.includes(attrId) ? prev.filter(x => x !== attrId) : [...prev, attrId];
      if (!next.length) { setSelectedIds(new Set()); return next; }
      const sel = new Set();
      scopedSeats.forEach(seat => {
        const ea = getEffectiveAttrs(seat);
        if (next.some(a => ea.includes(a))) sel.add(seat.id);
      });
      setSelectedIds(sel);
      return next;
    });
  };

  // Re-run filter selection when classTab changes
  useEffect(() => {
    if (!activeFilters.length) return;
    const scoped = classTab === 'ALL' ? seats : seats.filter(s => s.seat_class === classTab);
    const sel = new Set();
    scoped.forEach(seat => {
      const ea = getEffectiveAttrs(seat);
      if (activeFilters.some(a => ea.includes(a))) sel.add(seat.id);
    });
    setSelectedIds(sel);
  }, [classTab, seats, activeFilters]);

  const handleSeatClick = (e, seat) => {
    e.preventDefault(); e.stopPropagation();
    setSelectedIds(prev => { const n = new Set(prev); n.has(seat.id) ? n.delete(seat.id) : n.add(seat.id); return n; });
  };

  // Drag selection
  const handlePointerDown = e => {
    if (e.button !== 0 || !mapRef.current) return;
    const r = mapRef.current.getBoundingClientRect();
    setIsDragging(true); setDragStart({ x: e.clientX - r.left, y: e.clientY - r.top });
    setDragCur({ x: e.clientX - r.left, y: e.clientY - r.top });
    setDragMode(e.shiftKey ? 'remove' : 'add');
    e.target.setPointerCapture(e.pointerId);
  };
  const handlePointerMove = e => {
    if (!isDragging || !mapRef.current) return;
    const r = mapRef.current.getBoundingClientRect();
    setDragCur({ x: Math.max(0, Math.min(e.clientX - r.left, r.width)), y: Math.max(0, Math.min(e.clientY - r.top, r.height)) });
  };
  const handlePointerUp = () => {
    if (!isDragging) return; setIsDragging(false);
    if (!dragStart || !dragCur) return;
    const l = Math.min(dragStart.x, dragCur.x), ri = Math.max(dragStart.x, dragCur.x);
    const t = Math.min(dragStart.y, dragCur.y), b = Math.max(dragStart.y, dragCur.y);
    const sel = new Set(selectedIds);
    document.querySelectorAll('[data-seat-id]').forEach(n => {
      const sr = n.getBoundingClientRect(), mr = mapRef.current.getBoundingClientRect();
      const sl = sr.left - mr.left, sR = sr.right - mr.left, st = sr.top - mr.top, sb = sr.bottom - mr.top;
      if (!(ri < sl || l > sR || b < st || t > sb)) {
        const id = parseInt(n.getAttribute('data-seat-id'), 10);
        dragMode === 'add' ? sel.add(id) : sel.delete(id);
      }
    });
    setSelectedIds(sel); setDragStart(null); setDragCur(null);
  };

  const handleBulkApply = () => {
    if (!selectedIds.size) return toast.error('No seats selected.');
    if (!bulkPrice || isNaN(bulkPrice) || Number(bulkPrice) < 0) return toast.error('Enter a valid price.');
    const autoRule = activeFilters.length ? activeFilters.join('+') : '';
    toast.promise(dispatch(bulkPriceSeats({ seatIds: [...selectedIds], price: bulkPrice, ruleLabel: autoRule })).unwrap(), {
      loading: 'Applying…', success: r => { load(selInstance); return r.detail || 'Done!'; }, error: e => String(e),
    });
  };

  // Build seat grid grouped by class
  const parseSeat = s => {
    const m = s.seat_number.match(/^([A-Z]?)(\d+)([A-Z])$/);
    if (!m) {
      const numMatch = s.seat_number.match(/\d+/);
      const row = numMatch ? parseInt(numMatch[0], 10) : 0;
      const letterMatch = s.seat_number.match(/[A-Z]$/);
      const col = letterMatch ? letterMatch[0] : '';
      return { prefix: '', row, col };
    }
    return { prefix: m[1], row: parseInt(m[2], 10), col: m[3] };
  };

  const buildGrid = (seatList) => {
    const byClass = {};
    seatList.forEach(s => {
      if (!byClass[s.seat_class]) byClass[s.seat_class] = {};
      const p = parseSeat(s);
      const rowKey = `${p.prefix}${p.row}`;
      if (!byClass[s.seat_class][rowKey]) byClass[s.seat_class][rowKey] = [];
      byClass[s.seat_class][rowKey].push(s);
    });
    // Sort cols within each row
    Object.values(byClass).forEach(rows => {
      Object.values(rows).forEach(cols => cols.sort((a, b) => a.seat_number.localeCompare(b.seat_number)));
    });
    return byClass;
  };

  const grid = buildGrid(seats);
  const classOrder = ['FIRST', 'BUSINESS', 'ECONOMY'].filter(c => grid[c] && Object.keys(grid[c]).length > 0);

  const instanceOptions = instances.map(i => ({ value: String(i.id), label: `${i.flight_no || i.flight_number} — ${i.date} (${i.status})` }));
  const selInstanceObj = instances.find(i => String(i.id) === String(selInstance));
  const hasSeatCountWarning = selInstanceObj && seats.length > 0 && seats.length !== selInstanceObj.total_capacity;

  // Selection class summary
  const selClasses = new Set();
  selectedIds.forEach(id => { const s = seats.find(x => x.id === id); if (s) selClasses.add(s.seat_class); });
  const selClassLabel = selClasses.size === 0 ? '' : selClasses.size === 1 ? CLASS_LABELS[Array.from(selClasses)[0]] || '' : 'Mixed Classes';

  const dragBox = () => {
    if (!isDragging || !dragStart || !dragCur) return { display: 'none' };
    return {
      position: 'absolute', left: Math.min(dragStart.x, dragCur.x), top: Math.min(dragStart.y, dragCur.y),
      width: Math.abs(dragCur.x - dragStart.x), height: Math.abs(dragCur.y - dragStart.y),
      backgroundColor: dragMode === 'add' ? 'rgba(14,165,233,0.15)' : 'rgba(239,68,68,0.15)',
      border: `1.5px dashed ${dragMode === 'add' ? '#0ea5e9' : '#ef4444'}`, pointerEvents: 'none', zIndex: 100,
    };
  };


  return (
    <>
      <div className="smp-wrap">
        <div className="smp-breadcrumb">
          FLIGHT INSTANCES / SEAT MAP {selInstance ? `(INSTANCE #${selInstance})` : ''}
        </div>

        <div className="smp-header">
          <div className="smp-header-left">
            {instanceParam && (
              <button
                className="smp-back"
                onClick={() => {
                  const fromPage = searchParams.get('fromPage');
                  if (fromPage) {
                    navigate(`/admin/operations/flight-instances?page=${fromPage}&highlightInstance=${instanceParam}`);
                  } else {
                    navigate('/admin/operations/flight-instances');
                  }
                }}
              >
                <ArrowLeft size={14} /> Back
              </button>
            )}
            <h1 className="smp-title">Seat Pricing & Selection</h1>
          </div>
          {instanceParam && inFlow && (
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() => {
                  const fromPage = searchParams.get('fromPage');
                  navigate(`/admin/operations/meals?instance=${instanceParam}&inFlow=1${fromPage ? `&fromPage=${fromPage}` : ''}`);
                }}
                className="px-3.5 py-2 rounded-xl bg-[#705d00] hover:bg-[#5a4b00] text-white font-bold text-xs flex items-center gap-1.5 shadow-md cursor-pointer transition-all border-none"
              >
                <Utensils size={14} /> Skip / Next: Flight Meals <ChevronRight size={14} />
              </button>
              <button
                type="button"
                onClick={() => {
                  const fromPage = searchParams.get('fromPage');
                  if (fromPage) {
                    navigate(`/admin/operations/flight-instances?page=${fromPage}&highlightInstance=${instanceParam}`);
                  } else {
                    navigate('/admin/operations/flight-instances');
                  }
                }}
                className="px-3 py-2 rounded-xl bg-white hover:bg-slate-100 text-slate-600 font-semibold text-xs transition-all border border-slate-200 cursor-pointer"
              >
                Finish Flow
              </button>
            </div>
          )}
        </div>

        <div className="smp-body">
          {/* ── LEFT SIDEBAR ── */}
          <div className="smp-sidebar">

            {/* Filters Section A: Flight Instance */}
            <div className="smp-section">
              <span className="smp-section-label">Flight Instance</span>
              <div className="smp-instance-row">
                <div style={{ flex: 1, minWidth: 0 }}>
                  <Select id="seat-map-instance" options={[{ value: '', label: '— Select Flight Instance —' }, ...instanceOptions]} value={selInstance} onChange={e => handleInstanceChange(e.target.value)} style={{ margin: 0, height: '38px', padding: '0 32px 0 12px' }} />
                </div>
                <button className="btn-primary" onClick={() => { setSelectedIds(new Set()); load(selInstance); }} disabled={!selInstance || seatsLoading} style={{ padding: '0 14px', height: '38px', whiteSpace: 'nowrap', flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  {seatsLoading ? 'Loading…' : 'Search Seats'}
                </button>
              </div>
              {hasSeatCountWarning && (
                <div className="smp-warning">
                  <AlertTriangle size={14} />
                  Showing {seats.length} of {selInstanceObj.total_capacity} seats — check seat generation logic, capacity may have changed.
                </div>
              )}
            </div>

            {showMap && seats.length > 0 && (
              <div className="smp-section" style={{ background: '#f8fafc', padding: '12px 16px', borderRadius: 12, border: '1px solid #e2e8f0' }}>
                {/* Filters Section B: Cabin Class */}
                <div style={{ marginBottom: 10 }}>
                  <span className="smp-section-label">Cabin Class Scope</span>
                  <div className="smp-chip-group">
                    {CLASS_TABS.map(c => (
                      <button key={c} className={`smp-ctab ${classTab === c ? 'on' : ''}`} onClick={() => setClassTab(c)}>{CLASS_LABELS[c]}</button>
                    ))}
                  </div>
                </div>

                {/* Filters Section C: Attributes */}
                <div>
                  <span className="smp-section-label">Select By Attribute</span>
                  <div className="smp-chip-group" style={{ borderBottom: 'none', paddingBottom: 0 }}>
                    {ATTRS.map(a => (
                      <button key={a.id} className={`smp-chip ${activeFilters.includes(a.id) ? 'on' : ''}`} onClick={() => handleFilterToggle(a.id)}>{a.label}</button>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Legend */}
            {showMap && seats.length > 0 && (
              <div className="smp-legend" style={{ justifyContent: 'flex-start', flexWrap: 'wrap', marginTop: 8 }}>
                <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}><span className="smp-lbox fr" /> Free</span>
                <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}><span className="smp-lbox pr" /> ₹1–460</span>
                <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}><span className="smp-lbox sp" /> ₹461+</span>
              </div>
            )}
            {showMap && seats.length > 0 && (
              <p style={{ fontSize: 11, color: '#94a3b8', marginTop: 6, lineHeight: 1.4 }}>Drag to select • Shift+drag to deselect • Click to toggle</p>
            )}
          </div>{/* end sidebar */}

          {/* ── RIGHT COLUMN (seat map) ── */}
          <div className="smp-main">
            {selInstance && showMap && (
              seatsLoading ? (
                <div style={{ display: 'flex', justifyContent: 'center', padding: 48 }}>
                  <div style={{ width: 28, height: 28, border: '2.5px solid rgba(15,23,42,.12)', borderTopColor: '#0f172a', borderRadius: '50%', animation: 'spin .7s linear infinite' }} />
                </div>
              ) : seats.length === 0 ? (
                <div style={{ background: '#fff', border: '1px solid #e2e8f0', borderRadius: 12, padding: '48px 24px', textAlign: 'center' }}>
                  <h3 style={{ fontSize: 18, fontWeight: 700, color: '#1e293b', marginBottom: 6 }}>No Seats Found for this Flight</h3>
                  <p style={{ fontSize: 14, color: '#64748b', maxWidth: 420, margin: '0 auto 20px', lineHeight: 1.5 }}>
                    Seats have not been generated for this flight instance yet. Click below to automatically generate seats based on the aircraft layout.
                  </p>
                  <button className="btn-primary" onClick={handleGenerate} disabled={actionLoading} style={{ padding: '10px 20px', display: 'inline-flex', alignItems: 'center', gap: 8 }}>
                    {actionLoading ? 'Generating…' : 'Get Seats'}
                  </button>
                </div>
              ) : (
                <div className="smp-plane">
                  <div className="smp-fuselage" ref={mapRef} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerCancel={handlePointerUp}>
                    <div style={dragBox()} />

                    {classOrder.filter(c => classTab === 'ALL' || classTab === c).map(cabinClass => {
                      const rows = grid[cabinClass];
                      const rowKeys = Object.keys(rows).sort((a, b) => {
                        const na = parseInt(a.replace(/\D/g, ''), 10), nb = parseInt(b.replace(/\D/g, ''), 10);
                        return na - nb;
                      });

                      return (
                        <div key={cabinClass}>
                          <div className="smp-class-hdr" style={{ background: `${CLASS_COLORS[cabinClass]}22`, color: CLASS_COLORS[cabinClass] }}>{CLASS_LABELS[cabinClass]}</div>
                          {rowKeys.map(rowKey => {
                            const rowSeats = rows[rowKey];

                            // Get layout string from flight instance or fallback
                            let layoutStr = '3-3';
                            if (selInstanceObj) {
                              if (cabinClass === 'FIRST') layoutStr = selInstanceObj.aircraft_first_class_layout || '2-2';
                              else if (cabinClass === 'BUSINESS') layoutStr = selInstanceObj.aircraft_business_layout || '2-2';
                              else if (cabinClass === 'ECONOMY') layoutStr = selInstanceObj.aircraft_economy_layout || '3-3';
                            }
                            const layout = layoutStr.split('-').map(x => parseInt(x, 10)).filter(x => !isNaN(x) && x > 0);
                            if (layout.length === 0) layout.push(3, 3);
                            const colCount = layout.reduce((a, b) => a + b, 0);

                            // Pad to expected columns
                            const padded = [];
                            for (let ci = 0; ci < colCount; ci++) {
                              const letter = String.fromCharCode(65 + ci);
                              const found = rowSeats.find(s => s.seat_number.endsWith(letter));
                              padded.push(found || null);
                            }

                            const groups = [];
                            let currentOffset = 0;
                            layout.forEach((segSize) => {
                              groups.push(padded.slice(currentOffset, currentOffset + segSize));
                              currentOffset += segSize;
                            });

                            const rowNum = rowKey.replace(/\D/g, '');

                            const renderSeat = seat => {
                              if (!seat) return <div key={Math.random()} style={{ width: 28, height: 28 }} />;
                              const avail = seat.status === 'AVAILABLE';
                              const fee = Number(seat.seat_fee);
                              const isSel = selectedIds.has(seat.id);
                              let cls = 'smp-seat';
                              if (!avail) cls += ' una';
                              else if (fee === 0) cls += ' free';
                              else if (fee > 460) cls += ' sprem';
                              else cls += ' prem';
                              if (isSel) cls += ' sel';
                              const ea = getEffectiveAttrs(seat);
                              return (
                                <div key={seat.id} data-seat-id={seat.id} className={cls} onClick={e => avail && handleSeatClick(e, seat)} title={`${seat.seat_number} | ${ea.join(', ')} | ₹${seat.seat_fee}`}>
                                  {isSel ? <Check size={12} strokeWidth={3} color="#0ea5e9" /> : <span>{seat.seat_number}</span>}
                                </div>
                              );
                            };

                            return (
                              <div key={rowKey} className="smp-row">
                                <div className="smp-rn">{rowNum}</div>
                                {groups.map((group, gIdx) => (
                                  <Fragment key={gIdx}>
                                    <div className="smp-grp">{group.map(renderSeat)}</div>
                                    {gIdx < groups.length - 1 && <div className="smp-aisle" />}
                                  </Fragment>
                                ))}
                                <div className="smp-rn">{rowNum}</div>
                              </div>
                            );
                          })}
                          <div style={{ height: 6 }} />
                        </div>
                      );
                    })}
                  </div>
                </div>
              )
            )}
          </div>{/* end smp-main */}
        </div>{/* end smp-body */}

        {/* Sticky bulk action bar */}
        {selectedIds.size > 0 && (
          <div className="smp-bar">
            <div style={{ background: '#e0f2fe', color: '#0284c7', padding: '5px 10px', borderRadius: 6, fontWeight: 700, fontSize: 12, whiteSpace: 'nowrap' }}>
              {selectedIds.size} seats {selClassLabel && `— ${selClassLabel}`}
            </div>
            <div style={{ width: 100 }}>
              <Input id="bulk-price" type="text" inputMode="numeric" placeholder="Price ₹" value={bulkPrice} onChange={e => { const val = e.target.value; if (val === '' || /^\d*$/.test(val)) setBulkPrice(val); }} style={{ margin: 0, padding: '5px 8px', fontSize: 12 }} />
            </div>
            <button className="btn-primary" onClick={handleBulkApply} disabled={actionLoading} style={{ padding: '6px 16px', fontSize: 12, display: 'flex', alignItems: 'center', gap: 4, whiteSpace: 'nowrap', flexShrink: 0 }}>
              <DollarSign size={13} /> Apply Price
            </button>
            <div style={{ width: '1px', height: '18px', background: '#e2e8f0', margin: '0 4px', flexShrink: 0 }} />
            <button
              onClick={() => { setSelectedIds(new Set()); setActiveFilters([]); }}
              style={{
                background: 'transparent',
                border: 'none',
                color: '#94a3b8',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                padding: '4px',
                borderRadius: '50%',
                transition: 'background 0.2s, color 0.2s',
                flexShrink: 0
              }}
              onMouseEnter={e => { e.currentTarget.style.background = '#f1f5f9'; e.currentTarget.style.color = '#475569'; }}
              onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = '#94a3b8'; }}
              title="Clear selection"
            >
              <X size={15} />
            </button>
          </div>
        )}
      </div>
    </>
  );
}

import { useEffect, useState, useCallback } from 'react';
import { fetchWithAuth } from '@/services/apiClient';
import { Search, AlertCircle, X, Eye, Plane, User as UserIcon, CreditCard, Calendar, Ticket } from 'lucide-react';
import { Pagination } from '@/components/ui/Pagination';
import { Select } from '@/components/ui/Select';
import '@/admin/_core/styles/admin.css';
import { parseApiError } from '@/utils/errorUtils';

const STATUS_COLORS = {
  CONFIRMED: '#22c55e',
  PENDING_PAYMENT: '#f59e0b',
  CREATED: '#3b82f6',
  CANCELLED: '#ef4444',
  EXPIRED: '#6b7280',
  REFUNDED: '#8b5cf6',
};

export default function AdminBookingsPage() {
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
