    const d = new Date(isoString);
    const fullDateStr = d.toLocaleDateString("en-US", {
      weekday: "long",
      day: "numeric",
      month: "long",
      year: "numeric",
    });
    return { fullDateStr };
  };

  const dep = formatDateTime(depTime);

  // Duration calculation matching FlightItineraryCard
  const calculateDuration = (depIso, arrIso) => {
    if (!depIso || !arrIso) return "0h 0m";
    const depMs = new Date(depIso).getTime();
    const arrMs = new Date(arrIso).getTime();
    const diffMins = Math.max(0, Math.floor((arrMs - depMs) / (1000 * 60)));
    const h = Math.floor(diffMins / 60);
    const m = diffMins % 60;
    return `${h}h ${m}m`;
  };

  const durationStr = calculateDuration(depTime, arrTime);
  const stopCount = Array.isArray(stops) ? stops.length : typeof stops === "number" ? stops : 0;
  const stopsStr = stopCount === 0 ? "Non-stop" : `${stopCount} Stop${stopCount > 1 ? "s" : ""}`;

  return (
    <div className="booking-container-card animate-fade-in transition-all duration-300 relative">
      {/* Top Header Row: Route Title & Airline Badge */}
      <div className="flex items-center gap-2 mb-2">
        {/* Airline Badge */}
        <div className="inline-flex items-center bg-sky-100/70 border border-sky-200/60 rounded-xl px-3 py-1.5">
          <span className="text-xs font-bold text-slate-900">{airline}</span>
        </div>

        <h2 className="text-xl font-bold text-slate-950">
          {sourceInfo.city} &rarr; {destInfo.city}
        </h2>
      </div>

      {/* Flight Meta Info */}
      <div className="flex flex-wrap items-center gap-4 text-xs font-semibold text-slate-600">
        <span>{dep.fullDateStr}</span>
        <span>&bull;</span>
        <span>{stopsStr}</span>
        <span>&bull;</span>
        <span>{durationStr}</span>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef } from "react";
import { useSearchParams } from "react-router-dom";
import DatePickerModal from "@/components/ui/DatePickerModal";

const FALLBACK_AIRPORTS = {
  DEL: { city: "New Delhi", code: "DEL", name: "Indira Gandhi International Airport", country: "India" },
  HAM: { city: "Hamburg", code: "HAM", name: "Fuhlsbuettel", country: "Germany" },
  JFK: { city: "New York", code: "JFK", name: "John F. Kennedy International Airport", country: "USA" },
  LHR: { city: "London", code: "LHR", name: "Heathrow Airport", country: "UK" },
  HND: { city: "Tokyo", code: "HND", name: "Haneda Airport", country: "Japan" }
};

export default function FlightSearchHeader({ onSearchChange }) {
  const [searchParams, setSearchParams] = useSearchParams();

  // Read URL params or fallback
  const initialFrom = searchParams.get("from") || "DEL";
  const initialTo = searchParams.get("to") || "HAM";
  const initialDep = searchParams.get("depDate") || new Date().toISOString().split("T")[0];
  const initialArr = searchParams.get("arrDate") || "";
  const initialCabin = searchParams.get("cabinClass") || "Economy";

  const [from, setFrom] = useState(initialFrom);
  const [to, setTo] = useState(initialTo);
  const [fromSearch, setFromSearch] = useState("");
  const [toSearch, setToSearch] = useState("");

  const [isFromFocused, setIsFromFocused] = useState(false);
  const [isToFocused, setIsToFocused] = useState(false);

  const [depDate, setDepDate] = useState(initialDep);
  const [arrDate, setArrDate] = useState(initialArr);
  const [cabinClass, setCabinClass] = useState(initialCabin);

  const [isCalendarOpen, setIsCalendarOpen] = useState(false);
  const [calendarTab, setCalendarTab] = useState("dep");

  const [isCabinOpen, setIsCabinOpen] = useState(false);
  const [airports, setAirports] = useState([]);

  const fromInputRef = useRef(null);
  const toInputRef = useRef(null);
  const cabinDropdownRef = useRef(null);

  // Load airports
  useEffect(() => {
    import("../../../resources/airports.json")
      .then((module) => {
        setAirports(module.default || []);
      })
      .catch((err) => console.error("Failed to load airports:", err));
  }, []);

  // Update URL params whenever search inputs change
  const updateUrlAndNotify = (newFrom, newTo, newDep, newArr, newCabin) => {
    const params = new URLSearchParams(searchParams);
    if (newFrom) params.set("from", newFrom);
    if (newTo) params.set("to", newTo);
    if (newDep) params.set("depDate", newDep);
    if (newArr) params.set("arrDate", newArr); else params.delete("arrDate");
    if (newCabin) params.set("cabinClass", newCabin);

    setSearchParams(params, { replace: true });

    if (onSearchChange) {
      onSearchChange({
        from: newFrom,
        to: newTo,
        depDate: newDep,
        arrDate: newArr,
        cabinClass: newCabin
      });
    }
  };

  // Close cabin dropdown on click outside
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (cabinDropdownRef.current && !cabinDropdownRef.current.contains(e.target)) {
        setIsCabinOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Synchronize state with URL searchParams (e.g. when selected via DateStripCarousel)
  useEffect(() => {
    const urlFrom = searchParams.get("from");
    const urlTo = searchParams.get("to");
    const urlDep = searchParams.get("depDate");
    const urlArr = searchParams.get("arrDate") || "";
    const urlCabin = searchParams.get("cabinClass");

    if (urlFrom) setFrom(prev => urlFrom !== prev ? urlFrom : prev);
    if (urlTo) setTo(prev => urlTo !== prev ? urlTo : prev);
    if (urlDep) setDepDate(prev => urlDep !== prev ? urlDep : prev);
    setArrDate(prev => urlArr !== prev ? urlArr : prev);
    if (urlCabin) setCabinClass(prev => urlCabin !== prev ? urlCabin : prev);
  }, [searchParams]);

  const findAirport = (codeOrQuery) => {
    if (!codeOrQuery) return null;
    const query = codeOrQuery.trim().toUpperCase();
    if (FALLBACK_AIRPORTS[query]) return FALLBACK_AIRPORTS[query];
    return airports.find(
      (a) => a.code === query || a.city.toUpperCase() === query
    ) || null;
  };

  const getSuggestions = (query) => {
    if (!query || query.length < 2) return [];
    const q = query.toLowerCase();
    return airports
      .filter((a) =>
        a.code.toLowerCase().includes(q) ||
        a.city.toLowerCase().includes(q) ||
        a.name.toLowerCase().includes(q) ||
        a.country.toLowerCase().includes(q)
      )
      .slice(0, 6);
  };

  const handleSwap = (e) => {
    e.preventDefault();
    e.stopPropagation();
    const tempFrom = from;
    const tempTo = to;
    setFrom(tempTo);
    setTo(tempFrom);
    setFromSearch(findAirport(tempTo)?.city || tempTo);
    setToSearch(findAirport(tempFrom)?.city || tempFrom);
    updateUrlAndNotify(tempTo, tempFrom, depDate, arrDate, cabinClass);
  };

  const handleSelectDates = (selectedDep, selectedArr) => {
    setDepDate(selectedDep);
    setArrDate(selectedArr);
    updateUrlAndNotify(from, to, selectedDep, selectedArr, cabinClass);
  };

  const handleSelectCabin = (selectedClass) => {
    setCabinClass(selectedClass);
    setIsCabinOpen(false);
    updateUrlAndNotify(from, to, depDate, arrDate, selectedClass);
  };

  const formatHeaderDate = (dateStr) => {
    if (!dateStr) return { main: "-", sub: "" };
    try {
      const parts = String(dateStr).trim().split("-");
      let d;
      if (parts.length === 3) {
        d = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
      } else {
        d = new Date(dateStr);
      }
      if (isNaN(d.getTime())) return { main: "-", sub: "" };

      const day = d.getDate();
      const month = d.toLocaleString("en-US", { month: "short" });
      const weekday = d.toLocaleString("en-US", { weekday: "long" });

      return {
        main: `${day} ${month}`,
        sub: weekday
      };
    } catch (e) {
      return { main: "-", sub: "" };
    }
  };

  const fromAirport = findAirport(from);
  const toAirport = findAirport(to);
  const depFormatted = formatHeaderDate(depDate);
  const arrFormatted = formatHeaderDate(arrDate);

  const cabinOptions = [
    { label: "Economy", icon: "chair" },
    { label: "Business", icon: "airline_seat_recline_extra" },
    { label: "First Class", icon: "workspace_premium" }
  ];

  const currentCabinObj = cabinOptions.find(
    (c) => c.label.toLowerCase() === (cabinClass || "").toLowerCase()
  ) || cabinOptions[0];

  return (
    <div className="w-full mx-auto">
      {/* Compact Horizontal Header Container */}
      <div className="w-full shadow-sm flex flex-col lg:flex-row items-stretch divide-y lg:divide-y-0 lg:divide-x divide-slate-200/80 relative">

        {/* FROM BOX */}
        <div
          className="flex-1 px-6 py-2 relative cursor-pointer hover:bg-slate-200/40 transition-colors rounded-t-xl lg:rounded-l-xl lg:rounded-tr-none"
          onClick={() => {
            setIsFromFocused(true);
            setFromSearch(fromAirport?.city || from);
            setTimeout(() => fromInputRef.current?.focus(), 50);
          }}
        >
          <span className="text-[10px] font-bold text-slate-400 select-none block mb-1">
            From
          </span>

          {isFromFocused ? (
            <div className="mt-1">
              <input
                ref={fromInputRef}
                type="text"
                className="airport-input-field text-lg"
                value={fromSearch}
                onChange={(e) => setFromSearch(e.target.value)}
                onBlur={() => setTimeout(() => setIsFromFocused(false), 200)}
                placeholder="Search city/airport"
                autoComplete="off"
              />
            </div>
          ) : (
            <div className="mt-1">
              <div className="text-lg font-medium text-slate-900 truncate">
                {fromAirport ? fromAirport.city : from}
              </div>
              <div className="text-[10px] text-slate-500 truncate mt-0.5">
                {fromAirport ? `${fromAirport.code}, ${fromAirport.name} ${fromAirport.country || ''}` : from}
              </div>
            </div>
          )}

          {/* Autocomplete Dropdown */}
          {isFromFocused && getSuggestions(fromSearch).length > 0 && (
            <div className="absolute left-0 right-0 top-full mt-1 bg-white border border-slate-200 shadow-xl rounded-lg overflow-hidden z-50 max-h-56 overflow-y-auto divide-y divide-slate-100">
              {getSuggestions(fromSearch).map((airport) => (
                <div
                  key={airport.code}
                  className="px-3 py-2 hover:bg-amber-50 text-left transition-colors cursor-pointer"
                  onMouseDown={(e) => {
                    e.preventDefault();
                    setFrom(airport.code);
                    setFromSearch(airport.city);
                    setIsFromFocused(false);
                    updateUrlAndNotify(airport.code, to, depDate, arrDate, cabinClass);
                  }}
                >
                  <div className="font-bold text-slate-900 text-xs">{airport.city} ({airport.code})</div>
                  <div className="text-[10px] text-slate-500 truncate">{airport.name}, {airport.country}</div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* SWAP BUTTON DIVIDER */}
        <div className="relative flex items-center justify-center py-0.5 lg:py-0 lg:w-0">
          <button
            type="button"
            onClick={handleSwap}
            className="z-20 w-7 h-7 rounded-full bg-slate-200/90 hover:bg-slate-300 border border-slate-300/80 shadow-xs flex items-center justify-center transition-transform hover:scale-105 active:scale-95 cursor-pointer text-slate-700 lg:-mx-3.5"
            title="Swap Origin & Destination"
          >
            <span className="material-symbols-outlined text-base font-bold select-none">
              swap_horiz
            </span>
          </button>
        </div>

        {/* TO BOX */}
        <div
          className="flex-1 px-6 py-2 relative cursor-pointer hover:bg-slate-200/40 transition-colors"
          onClick={() => {
            setIsToFocused(true);
            setToSearch(toAirport?.city || to);
            setTimeout(() => toInputRef.current?.focus(), 50);
          }}
        >
          <span className="text-[10px] font-bold text-slate-400 select-none block mb-1">
            To
          </span>

          {isToFocused ? (
            <div className="mt-1">
              <input
                ref={toInputRef}
                type="text"
                className="airport-input-field text-lg"
                value={toSearch}
                onChange={(e) => setToSearch(e.target.value)}
                onBlur={() => setTimeout(() => setIsToFocused(false), 200)}
                placeholder="Search city/airport"
                autoComplete="off"
              />
            </div>
          ) : (
            <div className="mt-1">
              <div className="text-lg font-medium text-slate-900 truncate">
                {toAirport ? toAirport.city : to}
              </div>
              <div className="text-[10px] text-slate-500 mt-0.5 truncate">
                {toAirport ? `${toAirport.code}, ${toAirport.name} ${toAirport.country || ''}` : to}
              </div>
            </div>
          )}

          {/* Autocomplete Dropdown */}
          {isToFocused && getSuggestions(toSearch).length > 0 && (
            <div className="absolute left-0 right-0 top-full mt-1 bg-white border border-slate-200 shadow-xl rounded-lg overflow-hidden z-50 max-h-56 overflow-y-auto divide-y divide-slate-100">
              {getSuggestions(toSearch).map((airport) => (
                <div
                  key={airport.code}
                  className="px-3 py-2 hover:bg-amber-50 text-left transition-colors cursor-pointer"
                  onMouseDown={(e) => {
                    e.preventDefault();
                    setTo(airport.code);
                    setToSearch(airport.city);
                    setIsToFocused(false);
                    updateUrlAndNotify(from, airport.code, depDate, arrDate, cabinClass);
                  }}
                >
                  <div className="font-bold text-slate-900 text-xs">{airport.city} ({airport.code})</div>
                  <div className="text-[10px] text-slate-500 truncate">{airport.name}, {airport.country}</div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* DEPARTURE BOX */}
        <div
          className="flex-1 px-4 py-2 cursor-pointer hover:bg-slate-200/40 transition-colors"
          onClick={() => {
            setCalendarTab("dep");
            setIsCalendarOpen(true);
          }}
        >
          <span className="text-[10px] font-bold text-slate-400 select-none block">
            Departure
          </span>
          <div className="mt-1">
            <div className="text-lg font-medium text-slate-900 truncate">
              {depFormatted.main}
            </div>
            <div className="text-[10px] text-slate-500 truncate mt-0.5">
              {depFormatted.sub || "\u00A0"}
            </div>
          </div>
        </div>

        {/* RETURN BOX */}
        <div
          className="flex-1 px-4 py-2 cursor-pointer hover:bg-slate-200/40 transition-colors"
          onClick={() => {
            setCalendarTab("arr");
            setIsCalendarOpen(true);
          }}
        >
          <span className="text-[10px] font-bold text-slate-400 select-none block">
            Return
          </span>
          <div className="mt-1">
            <div className="text-lg font-medium text-slate-900 truncate">
              {arrFormatted.main}
            </div>
            <div className="text-[10px] text-slate-500 truncate mt-0.5">
              {arrFormatted.sub || "\u00A0"}
            </div>
          </div>
        </div>

        {/* CABIN CLASS BOX */}
        <div
          ref={cabinDropdownRef}
          className="flex-1 px-4 py-2 relative cursor-pointer hover:bg-slate-200/40 transition-colors rounded-b-xl lg:rounded-r-xl lg:rounded-bl-none"
          onClick={() => setIsCabinOpen(!isCabinOpen)}
        >
          <span className="text-[10px] font-bold text-slate-400 select-none block mb-1">
            Cabin Class
          </span>
          <div className="mt-1">
            <div className="text-lg font-medium text-slate-900 truncate flex items-center gap-1.5">
              <span className="material-symbols-outlined text-base font-semibold text-slate-700 select-none">
                {currentCabinObj.icon}
              </span>
              <span>{cabinClass}</span>
            </div>
            <div className="text-[10px] text-slate-500 font-normal truncate">
              &nbsp;
            </div>
          </div>

          {/* Cabin Class Dropdown */}
          {isCabinOpen && (
            <div className="absolute right-0 top-full mt-1 w-44 bg-white border border-slate-200 shadow-xl rounded-lg overflow-hidden z-50 py-1 animate-fade-in">
              {cabinOptions.map((option) => (
                <div
                  key={option.label}
                  className={`px-3 py-2 text-xs font-bold transition-colors cursor-pointer flex items-center gap-2 ${
                    cabinClass === option.label
                      ? "bg-amber-100 text-amber-900"
                      : "text-slate-700 hover:bg-slate-100"
                  }`}
                  onClick={(e) => {
                    e.stopPropagation();
                    handleSelectCabin(option.label);
                  }}
                >
                  <span className="material-symbols-outlined text-base font-semibold select-none">
                    {option.icon}
                  </span>
                  <span>{option.label}</span>
                </div>
              ))}
            </div>
          )}
        </div>

      </div>

      {/* Shared DatePicker Modal */}
      <DatePickerModal
        isOpen={isCalendarOpen}
        onClose={() => setIsCalendarOpen(false)}
        initialDepDate={depDate}
        initialArrDate={arrDate}
        onSelectDates={handleSelectDates}
        initialTab={calendarTab}
      />
    </div>
  );
}

import React from "react";
import CustomSelect from "@/components/ui/CustomSelect";

export default function PassengerListSection({
  passengers = [],
  onChangePassengers,
  errors = {}
}) {
  const handleAddPassenger = () => {
    const updated = [
      ...passengers,
      { id: Date.now(), name: "", age: "", gender: "Male", phone_number: "" }
    ];
    onChangePassengers(updated);
  };

  const handleRemovePassenger = (index) => {
    if (passengers.length <= 1) return;
    const updated = passengers.filter((_, i) => i !== index);
    onChangePassengers(updated);
  };

  const handleNameChange = (index, rawValue) => {
    // Only alphabets and spaces allowed, max 40 chars
    const sanitized = rawValue.replace(/[^A-Za-z\s]/g, "").slice(0, 40);
    const updated = [...passengers];
    updated[index] = { ...updated[index], name: sanitized };
    onChangePassengers(updated);
  };

  const handleAgeChange = (index, rawValue) => {
    // Only digits allowed
    let sanitized = rawValue.replace(/[^0-9]/g, "");
    if (sanitized !== "" && Number(sanitized) > 120) {
      sanitized = "120";
    }
    const updated = [...passengers];
    updated[index] = { ...updated[index], age: sanitized };
    onChangePassengers(updated);
  };

  const handleGenderChange = (index, value) => {
    const updated = [...passengers];
    updated[index] = { ...updated[index], gender: value };
    onChangePassengers(updated);
  };

  const handlePhoneChange = (index, rawValue) => {
    const sanitized = rawValue.replace(/[^0-9+\s-]/g, "").slice(0, 15);
    const updated = [...passengers];
    updated[index] = { ...updated[index], phone_number: sanitized };
    onChangePassengers(updated);
  };

  return (
    <div className="booking-container-card space-y-4 animate-fade-in transition-all duration-300">
      <div className="flex items-center gap-3 mb-4">
        <div className="w-10 h-10 rounded-2xl bg-gray-200 text-gray-900 flex items-center justify-center font-bold shadow-xs">
          <span className="material-symbols-outlined text-xl">people</span>
        </div>
        <h3 className="text-xl font-bold text-slate-950">
          Add Passengers
        </h3>
      </div>

      {/* Passenger List Cards */}
      <div className="space-y-4">
        {passengers.map((passenger, index) => {
          const pErrors = errors[index] || {};

          return (
            <div
              key={passenger.id || index}
              style={{ zIndex: 50 - index }}
              className="relative timeline-card animate-fade-in transition-all duration-300"
            >
              <div className="flex items-center justify-between mb-5">
                <span className="text-xs font-bold text-slate-700">
                  Passenger {index + 1}
                </span>
                {passengers.length > 1 && (
                  <button
                    type="button"
                    onClick={() => handleRemovePassenger(index)}
                    className="text-slate-400 hover:text-rose-500 transition-all duration-200 p-1 cursor-pointer"
                    title="Remove passenger"
                  >
                    <span className="material-symbols-outlined text-xs font-bold">
                      close
                    </span>
                  </button>
                )}
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-4 gap-3 items-start">
                {/* Name Field */}
                <div className="sm:col-span-2">
                  <div className="flex items-center justify-between mb-1.5">
                    <label className="text-[10px] font-bold text-slate-400 tracking-wider px-2">
                      Full Name
                    </label>
                    <span className="text-[9px] font-medium text-slate-400">
                      {passenger.name.length}/40
                    </span>
                  </div>
                  <input
                    type="text"
                    placeholder="e.g. John Doe"
                    maxLength={40}
                    value={passenger.name}
                    onChange={(e) => handleNameChange(index, e.target.value)}
                    className={`input-field transition-all duration-200 ${
                      pErrors.name ? "border border-rose-400 bg-rose-50/20 focus:ring-1 focus:ring-rose-500" : ""
                    }`}
                  />
                  {pErrors.name && (
                    <span className="field-error mt-1 block">
                      {pErrors.name}
                    </span>
                  )}
                </div>

                {/* Age Field */}
                <div>
                  <label className="text-[10px] font-bold text-slate-400 tracking-wider block mb-1.5 px-2">
                    Age
                  </label>
                  <input
                    type="text"
                    placeholder="e.g. 28"
                    value={passenger.age}
                    onChange={(e) => handleAgeChange(index, e.target.value)}
                    className={`input-field transition-all duration-200 ${
                      pErrors.age ? "border border-rose-400 bg-rose-50/20 focus:ring-1 focus:ring-rose-500" : ""
                    }`}
                  />
                  {pErrors.age && (
                    <span className="field-error mt-1 block">
                      {pErrors.age}
                    </span>
                  )}
                </div>

                {/* Gender Custom Dropdown Field */}
                <div>
                  <label className="text-[10px] font-bold text-slate-400 tracking-wider block mb-1.5 px-2">
                    Gender
                  </label>
                  <CustomSelect
                    value={passenger.gender || "Male"}
                    onChange={(val) => handleGenderChange(index, val)}
                    options={["Male", "Female", "Other"]}
                    placeholder="Select Gender"
                    error={Boolean(pErrors.gender)}
                  />
                  {pErrors.gender && (
                    <span className="field-error mt-1 block">
                      {pErrors.gender}
                    </span>
                  )}
                </div>
              </div>

              {/* Phone Number (Optional) Field */}
              <div className="mt-3">
                <label className="text-[10px] font-bold text-slate-400 tracking-wider block mb-1.5 px-2">
                  Phone Number (Optional)
                </label>
                <input
                  type="text"
                  placeholder="e.g. +91 98765 43210"
                  value={passenger.phone_number || ""}
                  onChange={(e) => handlePhoneChange(index, e.target.value)}
                  className="input-field transition-all duration-200"
                />
              </div>
            </div>
          );
        })}
      </div>

      {/* Add New Passenger Action Button */}
      <div className="pt-2">
        <button
          type="button"
          onClick={handleAddPassenger}
          className="text-sky-600 hover:text-sky-700 text-xs font-bold transition-all duration-200 cursor-pointer inline-flex items-center gap-1 hover:gap-1.5"
        >
          <span>+ Add New Passenger</span>
        </button>
      </div>
    </div>
  );
}

import { useState, useRef, useEffect } from "react";
import { useTranslation } from "react-i18next";
import { useNavigate, useLocation, Link } from "react-router-dom";
import { useSelector, useDispatch } from "react-redux";
import { logout } from "@/store/authSlice";
import { fetchNotifications } from "@/store/notificationsSlice";
import toast from "react-hot-toast";
import LogoutConfirmModal from "@/components/common/LogoutConfirmModal";

// ── Admin navigation data ────────────────────────────────────────────────────
const ADMIN_NAVIGATION = {
  directLinks: [
    { label: "Overview", href: "/admin/overview" },
    { label: "Analytics", href: "/admin/analytics" },
  ],
  groups: [
    {
      label: "Master Data",
      links: [
        { label: "Airports", href: "/admin/master/airports" },
        { label: "Airlines", href: "/admin/master/airlines" },
        { label: "Aircraft Models", href: "/admin/master/aircraft-models" },
        { label: "Aircraft", href: "/admin/master/aircraft" },
        { label: "Food Items", href: "/admin/master/food-items" },
      ],
    },
    {
      label: "Operations",
      links: [
        { label: "Flight Routes", href: "/admin/operations/flight-routes" },
        { label: "Instances", href: "/admin/operations/flight-instances" },
        { label: "Seat Map", href: "/admin/operations/seat-map" },
        { label: "Fares", href: "/admin/operations/fares" },
        { label: "Meals", href: "/admin/operations/meals" },
      ],
    },
    {
      label: "Records",
      links: [
        { label: "Bookings", href: "/admin/records/bookings" },
      ],
    },
    {
      label: "System",
      links: [
        { label: "Bulk Import", href: "/admin/system/data-management" },
      ],
    },
  ],
};

export default function Navbar() {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();
  const dispatch = useDispatch();

  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);
  const [showLogoutModal, setShowLogoutModal] = useState(false);
  const [openGroup, setOpenGroup] = useState(null);
  const profileMenuRef = useRef(null);
  const groupRefs = useRef({});

  const auth = useSelector((state) => state?.auth) || {};
  const { isAuthenticated, profile, decodedToken, isAdmin } = auth;
  const unreadCount = useSelector((state) => state?.notifications?.unreadCount || 0);

  useEffect(() => {
    if (isAuthenticated && !isAdmin) {
      dispatch(fetchNotifications());
    }
  }, [isAuthenticated, isAdmin, dispatch]);

  // Close profile dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (profileMenuRef.current && !profileMenuRef.current.contains(event.target)) {
        setIsProfileMenuOpen(false);
      }
      // Close open admin group if click is outside all group refs
      let insideGroup = false;
      Object.values(groupRefs.current).forEach((ref) => {
        if (ref && ref.contains(event.target)) insideGroup = true;
      });
      if (!insideGroup) setOpenGroup(null);
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const toggleLanguage = () => {
    const newLang = i18n.language?.startsWith("ja") ? "en" : "ja";
    i18n.changeLanguage(newLang);
  };

  const closeProfileMenu = () => {
    setIsProfileMenuOpen(false);
  };

  const handleLogout = () => {
    const targetPath = isAdmin ? "/admin/login" : "/login";
    setShowLogoutModal(false);
    closeProfileMenu();
    navigate(targetPath);
    dispatch(logout());
    if (isAdmin) {
      toast.success("Signed out successfully.", { position: "top-right" });
    } else {
      toast.success("You've been signed out.");
    }
  };

  const openLogoutModal = () => {
    closeProfileMenu();
    setShowLogoutModal(true);
  };

  const getInitials = () => {
    if (isAdmin) return "A";
    if (profile?.first_name && profile?.last_name) {
      return `${profile.first_name[0]}${profile.last_name[0]}`.toUpperCase();
    }
    if (profile?.username) return profile.username.substring(0, 2).toUpperCase();
    if (decodedToken?.username) return decodedToken.username.substring(0, 2).toUpperCase();
    return "AM";
  };

  // Active state helpers
  const isFlightsActive = location.pathname === "/" || location.pathname.startsWith("/flights");
  const isBookingsActive = location.pathname.startsWith("/my-bookings");

  const isAdminLinkActive = (href) => location.pathname === href;
  const isAdminGroupActive = (group) => group.links.some((l) => location.pathname.startsWith(l.href));

  return (
    <>
    <nav className="fixed top-0 left-0 right-0 z-[100] bg-white/20 backdrop-blur-md border-b border-white/10 shadow-sm transition-all duration-300 w-[90%] max-w-7xl rounded-b-3xl mx-auto">
      <div className="max-w-7xl w-full mx-auto px-8 h-[68px] flex items-center justify-between">

        {/* Left: Logo */}
        <div
          className="flex items-center cursor-pointer transform hover:scale-105 transition-transform duration-200"
          onClick={() => navigate(isAdmin ? "/admin/overview" : "/")}
        >
          <img
            src="/updated%20logo.png"
            alt="Passenger Logo"
            className="h-[34px] object-contain"
          />
        </div>

        {/* Center: Navigation Links */}
        {isAuthenticated ? (
          isAdmin ? (
            // ── Admin mega-nav ──────────────────────────────────────────────
            <div className="flex items-center gap-2 text-[14px] flex-1 px-8">

              {/* Direct links: Overview, Analytics */}
              {ADMIN_NAVIGATION.directLinks.map((link) => (
                <Link
                  key={link.href}
                  to={link.href}
                  onClick={() => setOpenGroup(null)}
                  className={`transition-all duration-200 px-4 py-2 rounded-full cursor-pointer ${
                    isAdminLinkActive(link.href)
                      ? "font-extrabold text-slate-900"
                      : "font-semibold text-slate-700 hover:text-slate-900"
                  }`}
                >
                  {link.label}
                </Link>
              ))}

              {/* Dropdown groups */}
              {ADMIN_NAVIGATION.groups.map((group) => {
                const isActive = isAdminGroupActive(group);
                const isOpen = openGroup === group.label;
                return (
                  <div
                    key={group.label}
                    className="relative"
                    ref={(el) => (groupRefs.current[group.label] = el)}
                  >
                    <button
                      onClick={() => setOpenGroup(isOpen ? null : group.label)}
                      className={`flex items-center gap-1.5 transition-all duration-200 px-4 py-2 rounded-full cursor-pointer ${
                        isActive
                          ? "font-extrabold text-slate-900"
                          : "font-semibold text-slate-700 hover:text-slate-900"
                      }`}
                    >
                      {group.label}
                      <svg
                        width="12"
                        height="12"
                        viewBox="0 0 10 10"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="1.5"
                        strokeLinecap="round"
                        className={`transition-transform duration-200 opacity-60 ${isOpen ? "rotate-180" : ""}`}
                      >
                        <path d="M1 3l4 4 4-4" />
                      </svg>
                    </button>

                    {/* Dropdown panel */}
                    {isOpen && (
                      <div className="absolute top-[calc(100%+10px)] left-0 min-w-[200px] bg-white backdrop-blur-xl border border-slate-200/60 shadow-2xl rounded-2xl py-2 z-[9999] animate-fade-in">
                        {group.links.map((link) => {
                          const active = location.pathname === link.href;
                          return (
                            <button
                              key={link.href}
                              onClick={() => { navigate(link.href); setOpenGroup(null); }}
                              className={`w-full text-left px-5 py-2.5 text-[13px] transition-colors duration-150 cursor-pointer ${
                                active
                                  ? "font-bold text-amber-700 bg-amber-50/80"
                                  : "font-medium text-slate-700 hover:bg-slate-100/80"
                              }`}
                            >
                              {link.label}
                            </button>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          ) : (
            // ── Passenger nav ───────────────────────────────────────────────
            <div className="flex items-center gap-10 text-[15px] px-12 flex-1">
              <Link
                to="/"
                className={`transition-all duration-200 px-4.5 py-2 rounded-full cursor-pointer ${
                  isFlightsActive
                    ? "font-extrabold text-slate-900"
                    : "font-semibold text-slate-700 hover:text-slate-900"
                }`}
              >
                Flights
              </Link>
              <Link
                to="/my-bookings"
                className={`transition-all duration-200 px-4.5 py-2 rounded-full cursor-pointer ${
                  isBookingsActive
                    ? "font-extrabold text-slate-900"
                    : "font-semibold text-slate-700 hover:text-slate-900"
                }`}
              >
                Bookings
              </Link>
            </div>
          )
        ) : (
          // ── Guest nav ─────────────────────────────────────────────────────
          <div className="hidden sm:flex items-center gap-10 text-[15px] flex-1 px-12">
            <Link
              to="/"
              className={`transition-all duration-200 px-4.5 py-2 rounded-full cursor-pointer ${
                isFlightsActive
                  ? "font-extrabold text-slate-900"
                  : "font-semibold text-slate-700 hover:text-slate-900"
              }`}
            >
              Flights
            </Link>
          </div>
        )}

        {/* Right: Actions */}
        <div className="flex items-center gap-5">

          {/* Language Switcher */}
          <button
            onClick={toggleLanguage}
            className="btn-secondary flex items-center gap-1.5 text-xs py-2 px-3.5 rounded-xl cursor-pointer"
          >
            <span className={i18n.language?.startsWith("ja") ? "opacity-40" : "opacity-100 font-bold"}>EN</span>
            <span className="opacity-20">|</span>
            <span className={i18n.language?.startsWith("ja") ? "opacity-100 font-bold" : "opacity-40"}>JA</span>
          </button>

          {isAuthenticated ? (
            <div className="flex items-center gap-4 relative" ref={profileMenuRef}>

              {/* Notification Bell — only for passengers */}
              {!isAdmin && (
                <button
                  type="button"
                  onClick={() => navigate("/notifications")}
                  className={`relative text-slate-900 hover:text-black transition-colors w-10 h-10 rounded-full hover:bg-black/5 cursor-pointer flex items-center justify-center ${
                    location.pathname === "/notifications" ? "bg-black/10 font-bold" : ""
                  }`}
                  title="Notifications"
                >
                  <span className="material-symbols-outlined text-2xl select-none">
                    notifications
                  </span>
                  {unreadCount > 0 && (
                    <span className="absolute top-1.5 right-1.5 w-2.5 h-2.5 rounded-full bg-amber-500 ring-2 ring-white animate-pulse" />
                  )}
                </button>
              )}

              {/* User Avatar Circle Badge */}
              <button
                type="button"
                onClick={() => { setIsProfileMenuOpen(!isProfileMenuOpen); setConfirmLogout(false); }}
                className="w-10 h-10 rounded-full bg-[#ffd600] text-black font-bold text-sm flex items-center justify-center shadow-[0_0_16px_rgba(255,214,0,0.85)] active:scale-95 transition-all cursor-pointer select-none"
              >
                {getInitials()}
              </button>

              {/* Dropdown Menu */}
              {isProfileMenuOpen && (
                <div className="absolute right-0 top-[72px] w-52 bg-white backdrop-blur-xl border border-slate-200/60 shadow-2xl rounded-2xl p-2.5 animate-fade-in z-[9999]">
                  <div className="px-3.5 py-2 border-b border-slate-100">
                    <p className="text-sm font-bold text-slate-800 truncate">
                      {profile?.username || decodedToken?.username || (isAdmin ? "Admin" : "Passenger")}
                    </p>
                    {profile?.email && (
                      <p className="text-xs text-slate-500 truncate">{profile.email}</p>
                    )}
                    {isAdmin && (
                      <span className="inline-flex items-center gap-1 mt-1.5 text-[10px] font-bold uppercase tracking-wider text-amber-700 bg-amber-50 border border-amber-200 rounded-full px-2.5 py-0.5">
                        <span className="w-1 h-1 rounded-full bg-amber-500" />
                        Admin
                      </span>
                    )}
                  </div>

                  {!isAdmin && (
                    <div className="py-1.5 border-b border-slate-100">
                      <Link
                        to="/profile"
                        onClick={() => setIsProfileMenuOpen(false)}
                        className="w-full flex items-center gap-2 px-3 py-2 text-xs font-semibold text-slate-700 hover:bg-slate-100/80 rounded-xl transition-colors cursor-pointer text-left"
                      >
                        <span className="material-symbols-outlined text-sm">person</span>
                        My Profile
                      </Link>
                    </div>
                  )}

                    <button
                      onClick={openLogoutModal}
                      className="w-full flex items-center gap-2 px-3 py-2 text-xs font-semibold text-rose-600 hover:bg-rose-50 rounded-xl transition-colors cursor-pointer text-left"
                    >
                      <span className="material-symbols-outlined text-sm">logout</span>
                      Sign Out
                    </button>
                </div>
              )}

            </div>
          ) : (
            <button
              onClick={() => navigate("/login")}
              className="btn-primary text-sm px-6 py-2.5 rounded-xl"
            >
              {t("navbar.loginOrRegister", "Login or Register")}
            </button>
          )}

        </div>

      </div>
    </nav>

    {/* ── Logout Confirmation Modal ────────────────────────────────────────── */}
    {showLogoutModal && (
      <LogoutConfirmModal
        isAdmin={isAdmin}
        onConfirm={handleLogout}
        onCancel={() => setShowLogoutModal(false)}
      />
    )}
  </>
  );
}

import React from "react";

export default function ComplimentaryMealCard({
  passengers = [],
  selectedCabin = "Economy",
  foodItems = [],
  flightMeals = [],
  isMealIncluded = false,
  targetCurrency = "INR",
  preferencesMap = {},
  selectedMealsMap = {},
  onMealSelect,
  onPreferenceChange,
}) {
  const defaultOptions = [
    {
      key: "VEG",
      title: "Vegetarian Meal Box",
      description: "Freshly prepared vegetarian meal, seasonal salad & dessert",
      icon: "eco",
      colorClass: "border-emerald-500 bg-emerald-50/40 text-emerald-950",
    },
    {
      key: "NON_VEG",
      title: "Non-Vegetarian Gourmet Box",
      description: "Chef's special non-veg meal, sides & dessert",
      icon: "restaurant",
      colorClass: "border-amber-500 bg-amber-50/40 text-amber-950",
    },
    {
      key: "NONE",
      title: "No Preference / Skip Meal",
      description: "Opt out of in-flight meal service",
      icon: "do_not_disturb_on",
      colorClass: "border-slate-300 bg-slate-50 text-slate-700",
    },
  ];

  const hasBackendItems = foodItems.length > 0 || flightMeals.length > 0;

  return (
    <div className="booking-container-card rounded-3xl p-6 space-y-6 animate-fade-in">
      {/* Header Banner */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-100 pb-4">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-2xl bg-amber-100 text-amber-900 flex items-center justify-center font-bold shadow-xs">
            <span className="material-symbols-outlined text-xl">restaurant_menu</span>
          </div>
          <div>
            <h3 className="text-xl font-bold text-slate-950">
              {isMealIncluded ? "Complimentary In-Flight Meal" : "In-Flight Food & Beverages"}
            </h3>
            <p className="pt-1 text-[10px] text-slate-500 font-medium">
              {isMealIncluded
                ? "Included with your ticket fare at no additional charge"
                : "Select delicious meals and refreshments for your flight"}
            </p>
          </div>
        </div>

        {isMealIncluded ? (
          <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl text-xs font-bold bg-emerald-100/80 text-emerald-900 border border-emerald-300/80">
            <span className="material-symbols-outlined text-sm font-bold">check_circle</span>
            Free Service
          </span>
        ) : (
          <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl text-xs font-bold bg-amber-100/80 text-amber-900 border border-amber-300/80">
            <span className="material-symbols-outlined text-sm font-bold">shopping_bag</span>
            Add-on Menu
          </span>
        )}
      </div>

      {/* Passengers Selection List */}
      <div className="space-y-5">
        {passengers.map((p, idx) => {
          const paxName = p.name?.trim() ? p.name.trim() : `Passenger ${idx + 1}`;
          const paxPaidMeals = selectedMealsMap[idx] || [];
          const currentPref = preferencesMap[idx] || "VEG";

          const genderRaw = (p.gender || "").toUpperCase();
          const genderLabel =
            genderRaw === "F" || genderRaw === "FEMALE"
              ? "Female"
              : genderRaw === "M" || genderRaw === "MALE"
                ? "Male"
                : genderRaw === "O" || genderRaw === "OTHER"
                  ? "Other"
                  : null;

          const ageLabel = p.age ? `${p.age} yrs` : null;
          const metaText = [genderLabel, ageLabel].filter(Boolean).join(", ");

          return (
            <div key={idx} className="p-4 rounded-2xl plain-card space-y-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className="material-symbols-outlined text-slate-500 text-lg">
                    person
                  </span>
                  <h4 className="text-sm font-bold text-slate-950">{paxName}</h4>
                  {metaText && (
                    <span className="text-xs text-slate-400 font-medium">
                      ({metaText})
                    </span>
                  )}
                </div>

                <span className="text-xs font-medium text-slate-400">
                  Select Meal Choice
                </span>
              </div>

              {/* Dynamic Backend Food Items Grid */}
              {hasBackendItems ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                  {/* Backend Food Items */}
                  {foodItems.map((item) => {
                    const isSelected = paxPaidMeals.some((m) => m.food_item_id === item.id);
                    const displayPrice = item.display_price || item.price;
                    const priceLabel = isMealIncluded
                      ? "Included (Free)"
                      : `${item.display_currency || targetCurrency} ${Number(displayPrice).toLocaleString()}`;

                    return (
                      <button
                        key={`food_${item.id}`}
                        type="button"
                        onClick={() =>
                          onMealSelect
                            ? onMealSelect(idx, {
                                food_item_id: item.id,
                                name: item.name,
                                is_veg: item.is_veg,
                                display_price: displayPrice,
                                display_currency: item.display_currency || targetCurrency,
                              })
                            : onPreferenceChange && onPreferenceChange(idx, item.is_veg ? "VEG" : "NON_VEG")
                        }
                        className={`p-3.5 rounded-2xl border text-left transition-all duration-200 cursor-pointer flex flex-col justify-between gap-2 ${
                          isSelected
                            ? `${item.is_veg ? "border-emerald-500 bg-emerald-50/40 text-emerald-950" : "border-amber-500 bg-amber-50/40 text-amber-950"} ring-2 ring-slate-950/10 shadow-sm`
                            : "border-slate-200/80 bg-white hover:border-slate-300 text-slate-700"
                        }`}
                      >
                        <div className="flex items-center justify-between w-full">
                          <span className="material-symbols-outlined text-lg font-bold">
                            {item.is_veg ? "eco" : "restaurant"}
                          </span>
                          {isSelected && (
                            <span className="material-symbols-outlined text-sm font-bold text-slate-950">
                              check_circle
                            </span>
                          )}
                        </div>

                        <div>
                          <div className="flex items-center justify-between gap-2">
                            <span className="text-xs font-bold block">{item.name}</span>
                          </div>

                          <div className="flex items-center gap-1.5 mt-1">
                            <span
                              className={`text-[9px] font-bold px-1.5 py-0.5 rounded-md ${
                                item.is_veg
                                  ? "bg-emerald-100 text-emerald-800"
                                  : "bg-amber-100 text-amber-900"
                              }`}
                            >
                              {item.is_veg ? "VEG" : "NON-VEG"}
                            </span>
                            {item.is_vegan && (
                              <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-md bg-green-100 text-green-800">
                                VEGAN
                              </span>
                            )}
                            {item.is_halal && (
                              <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-md bg-sky-100 text-sky-800">
                                HALAL
                              </span>
                            )}
                          </div>

                          <span className="text-xs font-bold text-slate-900 block mt-2">
                            {priceLabel}
                          </span>
                        </div>
                      </button>
                    );
                  })}

                  {/* Backend Flight Meals (Combos) */}
                  {flightMeals.map((meal) => {
                    const isSelected = paxPaidMeals.some((m) => m.flight_meal_id === meal.id);
                    const displayPrice = meal.display_price || meal.price;
                    const priceLabel = isMealIncluded
                      ? "Included (Free)"
                      : `${meal.display_currency || targetCurrency} ${Number(displayPrice).toLocaleString()}`;
                    const itemsDesc = meal.items?.map((it) => `${it.quantity}x ${it.name}`).join(", ");

                    return (
                      <button
                        key={`combo_${meal.id}`}
                        type="button"
                        onClick={() =>
                          onMealSelect
                            ? onMealSelect(idx, {
                                flight_meal_id: meal.id,
                                name: meal.name,
                                display_price: displayPrice,
                                display_currency: meal.display_currency || targetCurrency,
                              })
                            : onPreferenceChange && onPreferenceChange(idx, "NON_VEG")
                        }
                        className={`p-3.5 rounded-2xl border text-left transition-all duration-200 cursor-pointer flex flex-col justify-between gap-2 ${
                          isSelected
                            ? "border-sky-500 bg-sky-50/40 text-sky-950 ring-2 ring-slate-950/10 shadow-sm"
                            : "border-slate-200/80 bg-white hover:border-slate-300 text-slate-700"
                        }`}
                      >
                        <div className="flex items-center justify-between w-full">
                          <span className="material-symbols-outlined text-lg font-bold">
                            dinner_dining
                          </span>
                          {isSelected && (
                            <span className="material-symbols-outlined text-sm font-bold text-slate-950">
                              check_circle
                            </span>
                          )}
                        </div>

                        <div>
                          <span className="text-xs font-bold block">{meal.name}</span>
                          {itemsDesc && (
                            <span className="text-[10px] text-slate-500 font-medium block mt-0.5 line-clamp-1">
                              {itemsDesc}
                            </span>
                          )}
                          <span className="text-xs font-bold text-slate-900 block mt-2">
                            {priceLabel}
                          </span>
                        </div>
                      </button>
                    );
                  })}

                  {/* Option: Skip Meal */}
                  <button
                    type="button"
                    onClick={() =>
                      onMealSelect
                        ? onMealSelect(idx, { key: "NONE" })
                        : onPreferenceChange && onPreferenceChange(idx, "NONE")
                    }
                    className={`p-3.5 rounded-2xl border text-left transition-all duration-200 cursor-pointer flex flex-col justify-between gap-2 ${
                      paxPaidMeals.length === 0 && currentPref === "NONE"
                        ? "border-slate-400 bg-slate-100 text-slate-900 ring-2 ring-slate-950/10 shadow-sm"
                        : "border-slate-200/80 bg-white hover:border-slate-300 text-slate-700"
                    }`}
                  >
                    <div className="flex items-center justify-between w-full">
                      <span className="material-symbols-outlined text-lg font-bold">
                        do_not_disturb_on
                      </span>
                      {paxPaidMeals.length === 0 && currentPref === "NONE" && (
                        <span className="material-symbols-outlined text-sm font-bold text-slate-950">
                          check_circle
                        </span>
                      )}
                    </div>

                    <div>
                      <span className="text-xs font-bold block">No Meal / Skip</span>
                      <span className="text-[10px] text-slate-500 font-medium block mt-0.5">
                        Opt out of in-flight meal service
                      </span>
                    </div>
                  </button>
                </div>
              ) : (
                /* Fallback General Preferences Grid */
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                  {defaultOptions.map((opt) => {
                    const isSelected = currentPref === opt.key;
                    return (
                      <button
                        key={opt.key}
                        type="button"
                        onClick={() => onPreferenceChange && onPreferenceChange(idx, opt.key)}
                        className={`p-3.5 rounded-2xl border text-left transition-all duration-200 cursor-pointer flex flex-col justify-between gap-2 ${
                          isSelected
                            ? `${opt.colorClass} ring-2 ring-slate-950/10 shadow-sm`
                            : "border-slate-200/80 bg-white hover:border-slate-300 text-slate-700"
                        }`}
                      >
                        <div className="flex items-center justify-between w-full">
                          <span className="material-symbols-outlined text-lg font-bold">
                            {opt.icon}
                          </span>
                          {isSelected && (
                            <span className="material-symbols-outlined text-sm font-bold text-slate-950">
                              check_circle
                            </span>
                          )}
                        </div>

                        <div>
                          <span className="text-xs font-bold block">{opt.title}</span>
                          <span className="text-[10px] text-slate-500 font-medium block mt-0.5 line-clamp-2">
                            {opt.description}
                          </span>
                        </div>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState, useMemo } from "react";
import { profileAPI } from "@/services/profile-service/profileService";
import { useTranslation } from "react-i18next";
import toast from "react-hot-toast";
import { handleApiError } from "@/utils/errorUtils";
import { PASSWORD_RULES } from "@/utils/validators";

export default function ChangePasswordModal({ isOpen, onClose, hasUsablePassword = true }) {
  const { t } = useTranslation();

  const [pwdData, setPwdData] = useState({ oldPassword: "", newPassword: "", confirmPassword: "" });
  const [touched, setTouched] = useState({ oldPassword: false, newPassword: false, confirmPassword: false });
  const [pwdSaving, setPwdSaving] = useState(false);

  const [showOldPwd, setShowOldPwd] = useState(false);
  const [showNewPwd, setShowNewPwd] = useState(false);
  const [showConfirmPwd, setShowConfirmPwd] = useState(false);
  const [isPasswordFocused, setIsPasswordFocused] = useState(false);

  /* ── derived validation ── */
  const passwordRules = PASSWORD_RULES.map((rule) => ({
    ...rule,
    met: rule.test(pwdData.newPassword),
  }));

  if (hasUsablePassword) {
    passwordRules.push({
      id: "different",
      label: "Different from current password",
      met: !!pwdData.oldPassword && pwdData.newPassword !== pwdData.oldPassword,
    });
  }

  const isPasswordStrong = passwordRules.every((rule) => rule.met);

  const showPasswordRequirements =
    isPasswordFocused || (pwdData.newPassword.length > 0 && !isPasswordStrong);

  const errors = useMemo(() => {
    const e = {};
    if (hasUsablePassword && !pwdData.oldPassword && touched.oldPassword)
      e.oldPassword = "Current password is required.";

    if (touched.newPassword) {
      if (!pwdData.newPassword)
        e.newPassword = "New password is required.";
      else if (!isPasswordStrong)
        e.newPassword = "Please fulfill all password requirements";
    }

    if (touched.confirmPassword) {
      if (!pwdData.confirmPassword)
        e.confirmPassword = "Please confirm your new password.";
      else if (pwdData.confirmPassword !== pwdData.newPassword)
        e.confirmPassword = "Passwords do not match.";
    }

    return e;
  }, [pwdData, touched, isPasswordStrong, hasUsablePassword]);

  const isFormValid =
    (hasUsablePassword ? !!pwdData.oldPassword : true) &&
    pwdData.newPassword &&
    pwdData.confirmPassword &&
    Object.keys(errors).length === 0 &&
    isPasswordStrong &&
    pwdData.newPassword === pwdData.confirmPassword;

  if (!isOpen) return null;

  /* ── handlers ── */
  const resetForm = () => {
    setPwdData({ oldPassword: "", newPassword: "", confirmPassword: "" });
    setTouched({ oldPassword: false, newPassword: false, confirmPassword: false });
    setIsPasswordFocused(false);
  };

  const handleClose = () => {
    resetForm();
    onClose();
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setPwdData((prev) => ({ ...prev, [name]: value }));
    setTouched((prev) => ({ ...prev, [name]: true }));
  };

  const handleBlur = (e) => {
    const { name } = e.target;
    setTouched((prev) => ({ ...prev, [name]: true }));
    if (name === "newPassword") {
      setIsPasswordFocused(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setTouched({ oldPassword: true, newPassword: true, confirmPassword: true });
    if (!isFormValid) return;

    setPwdSaving(true);
    try {
      const payload = {
        new_password: pwdData.newPassword,
      };
      if (hasUsablePassword) {
        payload.old_password = pwdData.oldPassword;
      }

      await profileAPI.changePassword(payload);
      toast.success(hasUsablePassword ? "Password changed successfully! " : "Password set successfully! ");
      resetForm();
      setTimeout(onClose, 800);
    } catch (err) {
      handleApiError(err, { fallback: 'Failed to change password.' });
    }
    setPwdSaving(false);
  };

  const isPasswordMatched =
    pwdData.confirmPassword !== "" && pwdData.confirmPassword === pwdData.newPassword;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-fade-in" onClick={handleClose}>
      <div className="relative w-full max-w-md bg-white rounded-3xl p-8 shadow-2xl animate-scale-up" onClick={(e) => e.stopPropagation()}>

        {/* Close Button */}
        <button
          onClick={handleClose}
          className="absolute top-6 right-6 w-8 h-8 flex items-center justify-center rounded-full text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors"
        >
          <span className="material-symbols-outlined text-xl">close</span>
        </button>

        {/* Header */}
        <div className="mb-6">
          <h2 className="text-xl font-bold text-slate-800">
            {hasUsablePassword ? t("profile.updatePassword") : "Create a Password"}
          </h2>
          <p className="text-sm font-medium text-slate-500 mt-1">
            {hasUsablePassword ? t("profile.updatePassDesc") : "Set a password so you can log in with your email."}
          </p>
        </div>

        <form onSubmit={handleSubmit} noValidate className="space-y-4">

          {/* ── Current Password ── */}
          {hasUsablePassword && (
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-2 ml-2" htmlFor="oldPassword">
                {t("profile.currentPassword")}
              </label>
              <div className="relative flex items-center">
                <input
                  id="oldPassword" name="oldPassword"
                  type={showOldPwd ? "text" : "password"}
                  value={pwdData.oldPassword}
                  onChange={handleChange}
                  onBlur={handleBlur}
                  placeholder="Enter current password"
                  className="input-field pr-12"
                />
                <button
                  type="button"
                  onClick={() => setShowOldPwd(!showOldPwd)}
                  className="absolute right-3.5 text-slate-500 hover:text-slate-800 transition-colors cursor-pointer select-none"
                >
                  <span className="material-symbols-outlined text-sm">
                    {showOldPwd ? "visibility_off" : "visibility"}
                  </span>
                </button>
              </div>
              {errors.oldPassword && (
                <div className="overflow-hidden transition-all duration-200 mt-1 animate-fade-in">
                  <p className="field-error ml-2">{errors.oldPassword}</p>
                </div>
              )}
            </div>
          )}

          {/* ── New Password ── */}
          <div>
            <label className="block text-xs font-semibold text-slate-600 mb-2 ml-2" htmlFor="newPassword">
              {t("profile.newPassword")}
            </label>
            <div className="relative flex items-center">
              <input
                id="newPassword" name="newPassword"
                type={showNewPwd ? "text" : "password"}
                value={pwdData.newPassword}
                onChange={handleChange}
                onFocus={() => setIsPasswordFocused(true)}
                onBlur={handleBlur}
                placeholder="Create a strong password"
                className="input-field pr-12"
              />
              <button
                type="button"
                onClick={() => setShowNewPwd(!showNewPwd)}
                className="absolute right-3.5 text-slate-500 hover:text-slate-800 transition-colors cursor-pointer select-none"
              >
                <span className="material-symbols-outlined text-sm">
                  {showNewPwd ? "visibility_off" : "visibility"}
                </span>
              </button>
            </div>

            {/* Collapsible Password Requirements List in Vertical Order */}
            {showPasswordRequirements && (
              <div className="mt-2.5 p-3 bg-[#f8f9fa] rounded-2xl border border-slate-100 animate-fade-in">
                <div className="flex flex-col gap-1.5">
                  {passwordRules.map((rule) => (
                    <div
                      key={rule.id}
                      className={`flex items-center gap-2 transition-colors duration-200 ${rule.met ? "text-emerald-600 font-semibold" : "text-slate-400 font-medium"
                        }`}
                    >
                      <span
                        className={`material-symbols-outlined text-sm font-bold transition-all ${rule.met ? "text-emerald-500 scale-110" : "text-slate-300"
                          }`}
                      >
                        {rule.met ? "check_circle" : "radio_button_unchecked"}
                      </span>
                      <span className="text-[11px] select-none">{rule.label}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {errors.newPassword && touched.newPassword && !isPasswordStrong && !showPasswordRequirements && (
              <div className="overflow-hidden transition-all duration-200 mt-1 animate-fade-in">
                <p className="field-error ml-2">{errors.newPassword}</p>
              </div>
            )}
          </div>

          {/* ── Confirm Password ── */}
          <div>
            <label className="block text-xs font-semibold text-slate-600 mb-2 ml-2" htmlFor="confirmPassword">
              {t("profile.confirmNewPassword")}
            </label>
            <div className="relative flex items-center">
              <input
                id="confirmPassword" name="confirmPassword"
                type={showConfirmPwd ? "text" : "password"}
                value={pwdData.confirmPassword}
                onChange={handleChange}
                onBlur={handleBlur}
                placeholder="Repeat your password"
                className="input-field pr-16"
              />
              <div className="absolute right-3.5 flex items-center gap-1.5">
                {isPasswordMatched && (
                  <span className="material-symbols-outlined text-xs font-bold text-slate-800 animate-fade-in">
                    check
                  </span>
                )}
                <button
                  type="button"
                  onClick={() => setShowConfirmPwd(!showConfirmPwd)}
                  className="text-slate-500 hover:text-slate-800 transition-colors cursor-pointer select-none"
                >
                  <span className="material-symbols-outlined text-sm">
                    {showConfirmPwd ? "visibility_off" : "visibility"}
                  </span>
                </button>
              </div>
            </div>
            {errors.confirmPassword && (
              <div className="overflow-hidden transition-all duration-200 mt-1 animate-fade-in">
                <p className="field-error ml-2">{errors.confirmPassword}</p>
              </div>
            )}
          </div>

          {/* ── Actions ── */}
          <div className="flex justify-end gap-3 pt-4">
            <button
              type="button"
              onClick={handleClose}
              className="px-5 py-2 rounded-xl text-sm font-semibold text-slate-600 bg-slate-100 hover:bg-slate-200 transition-colors"
            >
              {t("profile.cancel")}
            </button>
            <button
              type="submit"
              disabled={pwdSaving}
              className="btn-primary px-5 py-2 rounded-xl text-sm"
            >
              {pwdSaving ? (
                <>
                  <span className="w-4 h-4 border-2 border-slate-900 border-t-transparent rounded-full animate-spin inline-block align-text-bottom mr-2" />
                  {t("profile.updating")}
                </>
              ) : (
                t("profile.saveChanges")
              )}
            </button>
          </div>

        </form>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import CustomSelect from "./CustomSelect";

export function getOrdinalSuffix(day) {
  if (day > 3 && day < 21) return "th";
  switch (day % 10) {
    case 1:  return "st";
    case 2:  return "nd";
    case 3:  return "rd";
    default: return "th";
  }
}

export function formatDisplayDate(dateStr) {
  if (!dateStr) return "";
  try {
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return dateStr;
    const day = date.getDate();
    const month = date.toLocaleDateString("en-US", { month: "long" });
    const year = date.getFullYear();
    return `${day}${getOrdinalSuffix(day)} ${month}, ${year}`;
  } catch {
    return dateStr;
  }
}

export default function DatePickerModal({
  isOpen,
  onClose,
  initialDepDate,
  initialArrDate,
  onSelectDates,
  initialTab
}) {
  const { t } = useTranslation();

  const [depDate, setDepDate] = useState(initialDepDate || "");
  const [arrDate, setArrDate] = useState(initialArrDate || "");
  const [activeTab, setActiveTab] = useState(initialTab || "dep");

  // Current calendar navigation
  const [viewDate, setViewDate] = useState(new Date());
  const [hoveredDate, setHoveredDate] = useState(null);

  // Sync state with props when modal opens
  useEffect(() => {
    if (isOpen) {
      setDepDate(initialDepDate || "");
      setArrDate(initialArrDate || "");
      setActiveTab(initialTab || "dep");
      setViewDate(initialDepDate ? new Date(initialDepDate) : new Date());
    }
  }, [isOpen, initialDepDate, initialArrDate, initialTab]);

  if (!isOpen) return null;

  const currentYear = viewDate.getFullYear();
  const currentMonth = viewDate.getMonth();

  // Days in current month
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
  // First day of month (0-6)
  const firstDayIndex = new Date(currentYear, currentMonth, 1).getDay();

  const handleYearChange = (yearVal) => {
    const year = parseInt(yearVal, 10);
    setViewDate(new Date(year, currentMonth, 1));
  };

  const handleMonthChange = (monthVal) => {
    const month = parseInt(monthVal, 10);
    setViewDate(new Date(currentYear, month, 1));
  };

  const handleDateClick = (dateStr) => {
    if (activeTab === "dep") {
      setDepDate(dateStr);
      if (arrDate && dateStr > arrDate) {
        setArrDate("");
      }
    } else {
      setArrDate(dateStr);
    }
  };

  const handleConfirm = () => {
    onSelectDates(depDate, arrDate);
    onClose();
  };

  const handleClear = () => {
    setDepDate("");
    setArrDate("");
    setActiveTab("dep");
  };

  const monthNames = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];

  const monthOptions = monthNames.map((name, index) => ({
    label: name,
    value: index.toString(),
  }));

  const nowYear = new Date().getFullYear();
  const yearOptions = [];
  for (let y = nowYear + 2; y >= nowYear - 1; y--) {
    yearOptions.push({ label: y.toString(), value: y.toString() });
  }

  const weekdayNames = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

  // Generate calendar day list
  const days = [];
  for (let i = 0; i < firstDayIndex; i++) {
    days.push(null);
  }
  for (let d = 1; d <= daysInMonth; d++) {
    days.push(new Date(currentYear, currentMonth, d));
  }

  // Format date utility
  const toDateString = (date) => {
    if (!date) return "";
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  };

  const todayStr = toDateString(new Date());

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/40 backdrop-blur-sm transition-all duration-300 animate-fade-in">

      {/* Backdrop click closer */}
      <div className="absolute inset-0" onClick={onClose} />

      {/* Modal Container */}
      <div className="relative w-full max-w-md mx-4 bg-white/90 backdrop-blur-2xl border border-white/40 shadow-2xl rounded-3xl p-6 overflow-hidden transition-transform duration-300 scale-100 hover:shadow-primary/5">

        {/* Selected Dates summary bar / Tabs */}
        <div className="flex gap-2 p-1.5 bg-black/5 rounded-2xl mb-6 text-xs">
          <button
            type="button"
            onClick={() => setActiveTab("dep")}
            className={`flex-1 py-3 text-center transition-all duration-200 rounded-xl cursor-pointer ${
              activeTab === "dep"
                ? "bg-white shadow-sm ring-1 ring-black/5"
                : "hover:bg-white/50"
            }`}
          >
            <div className="text-[10px] font-extrabold tracking-wider text-slate-400 uppercase select-none">Departure</div>
            <div className="font-extrabold text-on-surface mt-0.5">
              {depDate ? formatDisplayDate(depDate) : "Select date"}
            </div>
          </button>
          <button
            type="button"
            onClick={() => setActiveTab("arr")}
            className={`flex-1 py-3 text-center transition-all duration-200 rounded-xl cursor-pointer ${
              activeTab === "arr"
                ? "bg-white shadow-sm ring-1 ring-black/5"
                : "hover:bg-white/50"
            }`}
          >
            <div className="text-[10px] font-extrabold tracking-wider text-slate-400 uppercase select-none">Return</div>
            <div className="font-extrabold text-on-surface mt-0.5">
              {arrDate ? formatDisplayDate(arrDate) : "One way / Select"}
            </div>
          </button>
        </div>

        {/* Month & Year Navigation with CustomSelect */}
        <div className="flex items-center gap-2 mb-4">
          <div className="flex-1">
            <CustomSelect
              value={currentMonth.toString()}
              onChange={handleMonthChange}
              options={monthOptions}
              className="py-1.5 px-3 text-xs"
            />
          </div>
          <div className="w-28">
            <CustomSelect
              value={currentYear.toString()}
              onChange={handleYearChange}
              options={yearOptions}
              className="py-1.5 px-3 text-xs"
            />
          </div>
        </div>

        {/* Calendar Grid */}
        <div className="grid grid-cols-7 gap-1 text-center mb-6">
          {/* Weekdays */}
          {weekdayNames.map((w) => (
            <div key={w} className="text-xs font-bold text-on-surface-variant opacity-60 py-1 select-none">
              {w}
            </div>
          ))}

          {/* Days */}
          {days.map((date, idx) => {
            if (!date) return <div key={`empty-${idx}`} />;

            const dateStr = toDateString(date);
            const isToday = dateStr === todayStr;
            const isDep = dateStr === depDate;
            const isArr = dateStr === arrDate;

            let isInRange = false;
            if (depDate && arrDate && dateStr > depDate && dateStr < arrDate) {
              isInRange = true;
            } else if (depDate && !arrDate && hoveredDate && dateStr > depDate && dateStr < hoveredDate) {
              isInRange = true;
            }

            const isPast = dateStr < todayStr;
            const isBeforeDep = activeTab === "arr" && depDate && dateStr < depDate;
            const isDisabled = isPast || isBeforeDep;

            return (
              <button
                key={dateStr}
                disabled={isDisabled}
                onClick={() => handleDateClick(dateStr)}
                onMouseEnter={() => !isDisabled && setHoveredDate(dateStr)}
                onMouseLeave={() => setHoveredDate(null)}
                className={`
                  aspect-square rounded-full flex flex-col items-center justify-center text-xs font-bold relative transition-all duration-150 cursor-pointer
                  ${isDisabled ? "opacity-20 cursor-not-allowed" : "hover:bg-primary-container hover:text-primary-dark"}
                  ${isToday && !isDep && !isArr ? "border border-primary text-primary font-extrabold" : ""}
                  ${isDep ? "bg-primary text-white scale-105 shadow-md shadow-primary/20 font-extrabold" : ""}
                  ${isArr ? "bg-primary text-white scale-105 shadow-md shadow-primary/20 font-extrabold" : ""}
                  ${isInRange ? "bg-primary-container/60 text-primary-dark rounded-none" : ""}
                `}
              >
                {date.getDate()}
              </button>
            );
          })}
        </div>

        {/* Action Controls */}
        <div className="flex justify-between items-center gap-3">
          <button
            onClick={handleClear}
            className="px-4 py-2.5 rounded-full text-xs font-extrabold text-on-surface-variant/80 hover:bg-black/5 active:scale-95 transition-all cursor-pointer"
          >
            Clear
          </button>

          <div className="flex gap-2">
            <button
              onClick={onClose}
              className="px-4 py-2 rounded-xl text-xs font-semibold text-slate-600 hover:bg-slate-100 transition-colors"
            >
              Cancel
            </button>
            <button
              disabled={!depDate}
              onClick={handleConfirm}
              className="btn-primary px-5 py-2 rounded-xl text-xs disabled:opacity-50"
            >
              Confirm
            </button>
          </div>
        </div>

      </div>
    </div>
  );
}

import React, { useState, useRef, useEffect, useId, useLayoutEffect } from 'react';
import { ChevronLeft, ChevronRight, X, Calendar, Clock } from 'lucide-react';

/* ─────────────────────────────────────────────
   TimeInput: custom HH : MM keyboard input
───────────────────────────────────────────── */
function TimeInput({ timeVal, onTimeChange, selectId }) {
  const [hRaw, setHRaw] = useState(() => timeVal.split(':')[0] || '00');
  const [mRaw, setMRaw] = useState(() => timeVal.split(':')[1] || '00');
  const [hFocused, setHFocused] = useState(false);
  const [mFocused, setMFocused] = useState(false);
  const minRef = useRef(null);

  // Sync inbound value changes (e.g. preset click)
  useEffect(() => {
    const [h, m] = timeVal.split(':');
    setHRaw(h || '00');
    setMRaw(m || '00');
  }, [timeVal]);

  const commit = (h, m) => {
    const hc = String(Math.min(23, Math.max(0, parseInt(h, 10) || 0))).padStart(2, '0');
    const mc = String(Math.min(59, Math.max(0, parseInt(m, 10) || 0))).padStart(2, '0');
    onTimeChange(`${hc}:${mc}`);
    return { hc, mc };
  };

  const segStyle = (focused) => ({
    width: 36,
    textAlign: 'center',
    fontSize: 16,
    fontWeight: 800,
    fontFamily: 'Inter, monospace',
    background: focused ? 'rgba(112,93,0,0.06)' : '#f5f5f3',
    border: focused ? '1.5px solid #705d00' : '1.5px solid rgba(0,0,0,0.12)',
    borderRadius: 7,
    padding: '5px 4px',
    outline: 'none',
    color: '#1a1c1d',
    cursor: 'text',
    boxShadow: focused ? '0 0 0 3px rgba(112,93,0,0.1)' : 'none',
    transition: 'border-color 0.15s, box-shadow 0.15s, background 0.15s',
    letterSpacing: 1,
  });

  return (
    <div
      style={{ display: 'flex', alignItems: 'center', gap: 4 }}
      onClick={e => e.stopPropagation()}
    >
      {/* Hours */}
      <input
        id={`${selectId}-h`}
        type="text"
        inputMode="numeric"
        maxLength={2}
        value={hFocused ? hRaw : hRaw.padStart(2, '0')}
        style={segStyle(hFocused)}
        onFocus={e => { setHFocused(true); e.target.select(); }}
        onBlur={() => {
          setHFocused(false);
          const { hc } = commit(hRaw || '00', mRaw || '00');
          setHRaw(hc);
        }}
        onChange={e => {
          const val = e.target.value.replace(/\D/g, '').slice(0, 2);
          setHRaw(val);
        }}
        onKeyDown={e => {
          const h = parseInt(hRaw, 10) || 0;
          if (e.key === 'ArrowUp') {
            e.preventDefault();
            const next = String((h + 1) % 24).padStart(2, '0');
            setHRaw(next);
            commit(next, mRaw);
          }
          if (e.key === 'ArrowDown') {
            e.preventDefault();
            const next = String((h - 1 + 24) % 24).padStart(2, '0');
            setHRaw(next);
            commit(next, mRaw);
          }
        }}
      />

      <span style={{ fontSize: 15, fontWeight: 900, color: '#705d00', lineHeight: 1 }}>:</span>

      {/* Minutes */}
      <input
        ref={minRef}
        id={`${selectId}-m`}
        type="text"
        inputMode="numeric"
        maxLength={2}
        value={mFocused ? mRaw : (mRaw || '00').padStart(2, '0')}
        style={segStyle(mFocused)}
        onFocus={e => { setMFocused(true); e.target.select(); }}
        onBlur={() => {
          setMFocused(false);
          const { mc } = commit(hRaw || '00', mRaw || '00');
          setMRaw(mc);
        }}
        onChange={e => {
          const val = e.target.value.replace(/\D/g, '').slice(0, 2);
          setMRaw(val);
        }}
        onKeyDown={e => {
          const m = parseInt(mRaw, 10) || 0;
          if (e.key === 'ArrowUp') {
            e.preventDefault();
            const next = String((m + 5) % 60).padStart(2, '0');
            setMRaw(next);
            commit(hRaw, next);
          }
          if (e.key === 'ArrowDown') {
            e.preventDefault();
            const next = String((m - 5 + 60) % 60).padStart(2, '0');
            setMRaw(next);
            commit(hRaw, next);
          }
        }}
      />
      <span style={{ fontSize: 10, fontWeight: 700, color: '#9e9488', marginLeft: 2, letterSpacing: '0.04em' }}>0–23h</span>
    </div>
  );
}

export default function DateTimePicker({
  id,
  name,
  label,
  placeholder = 'Select Date & Time',
  value,
  onChange,
  disabled = false,
  error,
  style = {},
  ...props
}) {
  const MONTH_NAMES = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
  ];

  const WEEKDAYS = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];
  const TIME_PRESETS = ['06:00', '09:00', '12:00', '15:00', '18:00', '21:00'];

  const [isOpen, setIsOpen] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const [popoverStyle, setPopoverStyle] = useState({});

  const containerRef = useRef(null);
  const popoverRef = useRef(null);
  const uniqueId = useId();
  const selectId = id || uniqueId;
  const selectName = name || id;

  // Split value into date and time parts
  let dateVal = '';
  let timeVal = '12:00';

  if (value && typeof value === 'string') {
    if (value.includes('T')) {
      const parts = value.split('T');
      dateVal = parts[0];
      timeVal = parts[1].substring(0, 5) || '12:00';
    } else if (value.includes(' ')) {
      const parts = value.split(' ');
      dateVal = parts[0];
      timeVal = parts[1].substring(0, 5) || '12:00';
    } else {
      dateVal = value;
    }
  }

  const initialCalendarDate = dateVal ? new Date(dateVal) : new Date();
  const [viewYear, setViewYear] = useState(initialCalendarDate.getFullYear());
  const [viewMonth, setViewMonth] = useState(initialCalendarDate.getMonth());

  // Update view month/year if value changes externally
  useEffect(() => {
    if (dateVal) {
      const parsed = new Date(dateVal);
      if (!isNaN(parsed.getTime())) {
        setViewYear(parsed.getFullYear());
        setViewMonth(parsed.getMonth());
      }
    }
  }, [dateVal]);

  // Compute fixed position for the popover so it never clips off-screen or off-modal
  const updatePopoverPosition = () => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const popoverHeight = 370; // approx popover height
    const spaceBelow = window.innerHeight - rect.bottom;

    let top;
    // Prefer opening downwards unless space below is constrained and space above is larger
    if (spaceBelow < popoverHeight && rect.top > spaceBelow) {
      top = rect.top - popoverHeight - 6;
    } else {
      top = rect.bottom + 6;
    }

    // Always clamp top to prevent overflowing above top of viewport
    top = Math.max(10, Math.min(top, window.innerHeight - popoverHeight - 10));

    let left = rect.left;
    if (left + 290 > window.innerWidth) {
      left = Math.max(10, window.innerWidth - 300);
    }

    setPopoverStyle({
      position: 'fixed',
      top: `${top}px`,
      left: `${left}px`,
      width: '290px',
      zIndex: 99999,
    });
  };

  useLayoutEffect(() => {
    if (isOpen) {
      updatePopoverPosition();
    }
  }, [isOpen]);

  // Handle window scroll/resize to update fixed position
  useEffect(() => {
    if (!isOpen) return;
    const handleScrollOrResize = () => updatePopoverPosition();
    window.addEventListener('scroll', handleScrollOrResize, true);
    window.addEventListener('resize', handleScrollOrResize);
    return () => {
      window.removeEventListener('scroll', handleScrollOrResize, true);
      window.removeEventListener('resize', handleScrollOrResize);
    };
  }, [isOpen]);

  // Close calendar on click outside
  useEffect(() => {
    function handleClickOutside(event) {
      if (
        containerRef.current &&
        !containerRef.current.contains(event.target) &&
        popoverRef.current &&
        !popoverRef.current.contains(event.target)
      ) {
        setIsOpen(false);
      }
    }
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen]);

  const handleToggle = () => {
    if (disabled) return;
    if (isOpen) {
      setIsOpen(false);
    } else {
      const activeDate = dateVal ? new Date(dateVal) : new Date();
      setViewYear(activeDate.getFullYear());
      setViewMonth(activeDate.getMonth());
      setIsOpen(true);
    }
  };

  const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
  const firstDayIndex = new Date(viewYear, viewMonth, 1).getDay();

  const days = [];
  for (let i = 0; i < firstDayIndex; i++) {
    days.push(null);
  }
  for (let d = 1; d <= daysInMonth; d++) {
    days.push(d);
  }

  const handlePrevMonth = () => {
    if (viewMonth === 0) {
      setViewMonth(11);
      setViewYear(prev => prev - 1);
    } else {
      setViewMonth(prev => prev - 1);
    }
  };

  const handleNextMonth = () => {
    if (viewMonth === 11) {
      setViewMonth(0);
      setViewYear(prev => prev + 1);
    } else {
      setViewMonth(prev => prev + 1);
    }
  };

  const handleSelectDay = (day) => {
    if (!day) return;
    const formattedMonth = String(viewMonth + 1).padStart(2, '0');
    const formattedDay = String(day).padStart(2, '0');
    const dateStr = `${viewYear}-${formattedMonth}-${formattedDay}`;
    if (onChange) {
      onChange({
        target: {
          id: selectId,
          name: selectName,
          value: `${dateStr}T${timeVal}`
        }
      });
    }
  };

  const handleTimeChange = (newTime) => {
    const formattedTime = newTime || '12:00';
    const finalDate = dateVal || new Date().toISOString().substring(0, 10);
    if (onChange) {
      onChange({
        target: {
          id: selectId,
          name: selectName,
          value: `${finalDate}T${formattedTime}`
        }
      });
    }
  };

  const handleClear = (e) => {
    e.stopPropagation();
    if (disabled) return;
    if (onChange) {
      onChange({
        target: {
          id: selectId,
          name: selectName,
          value: ''
        }
      });
    }
    setIsOpen(false);
  };

  const isSelected = (day) => {
    if (!day || !dateVal) return false;
    const parts = dateVal.split('-');
    if (parts.length !== 3) return false;
    const year = parseInt(parts[0], 10);
    const month = parseInt(parts[1], 10) - 1;
    const date = parseInt(parts[2], 10);
    return year === viewYear && month === viewMonth && date === day;
  };

  const displayValue = value && typeof value === 'string' ? value.replace('T', ' ') : '';

  const triggerStyle = {
    width: '100%',
    background: disabled ? 'rgba(0,0,0,0.03)' : '#ffffff',
    border: error 
      ? '1.5px solid #b91c1c' 
      : (isFocused && !disabled ? '1.5px solid #705d00' : '1.5px solid rgba(0,0,0,0.15)'),
    borderRadius: 10,
    padding: '9px 13px',
    fontSize: 14,
    fontWeight: 500,
    color: disabled ? '#a09888' : '#1a1c1d',
    fontFamily: 'Inter, sans-serif',
    outline: 'none',
    cursor: disabled ? 'not-allowed' : 'pointer',
    textAlign: 'left',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    boxShadow: error 
      ? (isFocused ? '0 0 0 3px rgba(185,28,28,0.1)' : 'none')
      : (isFocused && !disabled ? '0 0 0 3px rgba(112,93,0,0.1)' : 'none'),
    transition: 'border-color 0.2s, box-shadow 0.2s, background 0.2s',
    ...style,
  };

  return (
    <div ref={containerRef} style={{ display: 'flex', flexDirection: 'column', gap: 5, position: 'relative', width: '100%' }}>
      {label && (
        <label
          htmlFor={selectId}
          style={{
            fontSize: 11,
            fontWeight: 700,
            letterSpacing: '0.06em',
            textTransform: 'uppercase',
            color: '#5e5e5e',
            userSelect: 'none',
          }}
        >
          {label}
        </label>
      )}

      <div style={{ position: 'relative', width: '100%' }}>
        <button
          id={selectId}
          data-testid="datetime-trigger"
          type="button"
          disabled={disabled}
          onClick={handleToggle}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          style={triggerStyle}
          {...props}
        >
          <span>{displayValue || placeholder}</span>

          {value && !disabled ? (
            <span
              role="button"
              aria-label="Clear"
              onClick={handleClear}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.stopPropagation();
                  handleClear(e);
                }
              }}
              tabIndex={0}
              style={{
                background: 'none',
                border: 'none',
                color: '#9e9488',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                padding: 0,
                marginLeft: 8,
                flexShrink: 0,
                outline: 'none',
              }}
            >
              <X size={14} />
            </span>
          ) : (
            <Calendar
              size={14}
              style={{
                color: '#9e9488',
                marginLeft: 8,
                flexShrink: 0,
              }}
            />
          )}
        </button>

        {isOpen && (
          <div
            ref={popoverRef}
            className="glass-card"
            style={{
              padding: 16,
              borderRadius: 16,
              background: '#ffffff',
              border: '1px solid rgba(0,0,0,0.12)',
              boxShadow: '0 12px 36px rgba(0, 0, 0, 0.18)',
              ...popoverStyle,
            }}
          >
            {/* Header */}
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
              <button
                type="button"
                onClick={handlePrevMonth}
                style={{
                  background: 'none',
                  border: 'none',
                  color: '#1a1c1d',
                  cursor: 'pointer',
                  padding: 4,
                  borderRadius: '50%',
                  display: 'flex',
                  alignItems: 'center',
                }}
              >
                <ChevronLeft size={16} />
              </button>

              <span style={{ fontSize: 14, fontWeight: 800, color: '#1a1c1d' }}>
                {MONTH_NAMES[viewMonth]} {viewYear}
              </span>

              <button
                type="button"
                onClick={handleNextMonth}
                style={{
                  background: 'none',
                  border: 'none',
                  color: '#1a1c1d',
                  cursor: 'pointer',
                  padding: 4,
                  borderRadius: '50%',
                  display: 'flex',
                  alignItems: 'center',
                }}
              >
                <ChevronRight size={16} />
              </button>
            </div>

            {/* Weekdays */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 4, textAlign: 'center', marginBottom: 8 }}>
              {WEEKDAYS.map(w => (
                <span key={w} style={{ fontSize: 11, fontWeight: 700, color: '#9e9488' }}>
                  {w}
                </span>
              ))}
            </div>

            {/* Days Grid */}
            <div role="grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 4 }}>
              {days.map((day, idx) => {
                if (day === null) {
                  return <div key={`empty-${idx}`} />;
                }
                const active = isSelected(day);
                return (
                  <button
                    key={`day-${day}`}
                    type="button"
                    onClick={() => handleSelectDay(day)}
                    style={{
                      background: active ? '#ffd700' : 'none',
                      border: 'none',
                      borderRadius: 8,
                      height: 30,
                      fontSize: 12,
                      fontWeight: active ? 800 : 600,
                      color: '#1a1c1d',
                      cursor: 'pointer',
                      transition: 'all 0.2s',
                      outline: 'none',
                    }}
                    onMouseEnter={(e) => {
                      if (!active) {
                        e.currentTarget.style.background = 'rgba(255, 215, 0, 0.15)';
                      }
                    }}
                    onMouseLeave={(e) => {
                      if (!active) {
                        e.currentTarget.style.background = 'none';
                      }
                    }}
                  >
                    {day}
                  </button>
                );
              })}
            </div>

            {/* Time selector section */}
            <div style={{ marginTop: 12, paddingTop: 12, borderTop: '1px solid rgba(0,0,0,0.08)' }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                  <Clock size={13} style={{ color: '#9e9488' }} />
                  <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase', color: '#5e5e5e' }}>Time</span>
                </div>
                <TimeInput timeVal={timeVal} onTimeChange={handleTimeChange} selectId={selectId} />
              </div>
            </div>

            {/* Done button */}
            <button
              type="button"
              onClick={() => setIsOpen(false)}
              style={{
                background: '#ffd700',
                border: 'none',
                borderRadius: 8,
                padding: '8px 12px',
                fontSize: 12,
                fontWeight: 700,
                color: '#1a1c1d',
                cursor: 'pointer',
                width: '100%',
                marginTop: 12,
                textAlign: 'center',
                boxShadow: '0 2px 6px rgba(255,215,0,0.2)',
                transition: 'transform 0.1s',
              }}
              onMouseEnter={(e) => { e.currentTarget.style.transform = 'scale(1.02)'; }}
              onMouseLeave={(e) => { e.currentTarget.style.transform = 'scale(1)'; }}
            >
              Done
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState } from 'react';

export function Input({ id, label, type = 'text', error, onFocus, onBlur, ...props }) {
  const [isFocused, setIsFocused] = useState(false);

  const borderColor = error
    ? '#b91c1c'
    : (isFocused ? '#705d00' : 'rgba(0,0,0,0.1)');

  const boxShadow = error
    ? (isFocused ? '0 0 0 3px rgba(185,28,28,0.18)' : '0 0 0 3px rgba(185,28,28,0.1)')
    : (isFocused ? '0 0 0 3px rgba(112,93,0,0.1)' : 'none');

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 5 }}>
      {label && (
        <label
          htmlFor={id}
          style={{
            fontSize: 11,
            fontWeight: 700,
            letterSpacing: '0.06em',
            textTransform: 'uppercase',
            color: '#5e5e5e',
          }}
        >
          {label}
        </label>
      )}
      <input
        id={id}
        name={id}
        type={type}
        {...props}
        style={{
          width: '100%',
          background: isFocused ? 'rgba(255,255,255,0.92)' : 'rgba(255,255,255,0.65)',
          border: `1.5px solid ${borderColor}`,
          borderRadius: 10,
          padding: '9px 13px',
          fontSize: 14,
          fontWeight: 500,
          color: '#1a1c1d',
          fontFamily: 'Inter, sans-serif',
          outline: 'none',
          boxShadow: boxShadow,
          transition: 'border-color 0.2s, box-shadow 0.2s, background 0.2s',
          ...props.style,
        }}
        onFocus={e => {
          setIsFocused(true);
          onFocus?.(e);
        }}
        onBlur={e => {
          setIsFocused(false);
          onBlur?.(e);
        }}
      />
      {error && (
        <p style={{ fontSize: 12, color: '#b91c1c', marginTop: 2, paddingLeft: 2 }}>{error}</p>
      )}
    </div>
  );
}

import React, { useState, useRef, useEffect, useId, useMemo, useCallback } from 'react';
import ReactDOM from 'react-dom';
import { ChevronDown } from 'lucide-react';

export function Select({
  id,
  name,
  label,
  options = [],
  value,
  onChange,
  disabled = false,
  error,
  placeholder = 'Select...',
  style = {},
  ...props
}) {
  const [isOpen, setIsOpen] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const [dropdownStyle, setDropdownStyle] = useState({});
  const [searchQuery, setSearchQuery] = useState('');

  const containerRef = useRef(null);
  const inputRef = useRef(null);
  const uniqueId = useId();
  const selectId = id || uniqueId;
  const selectName = name || id;

  const normalizedOptions = useMemo(() => {
    return options.map(opt => {
      if (typeof opt === 'string') {
        return { value: opt, label: opt };
      }
      return opt;
    });
  }, [options]);

  const selectedOption = useMemo(() => {
    return normalizedOptions.find(opt => String(opt.value) === String(value));
  }, [normalizedOptions, value]);

  // Options filtered by user typing in the main input
  const filteredOptions = useMemo(() => {
    if (!isOpen || !searchQuery.trim()) return normalizedOptions;
    const term = searchQuery.toLowerCase().trim();
    return normalizedOptions.filter(opt =>
      String(opt.label).toLowerCase().includes(term) ||
      String(opt.value).toLowerCase().includes(term)
    );
  }, [normalizedOptions, searchQuery, isOpen]);

  // Compute position of dropdown below input bar
  const updateDropdownPosition = useCallback(() => {
    if (!inputRef.current) return;
    const rect = inputRef.current.getBoundingClientRect();
    const dropdownHeight = Math.min(240, filteredOptions.length * 38 + 10);
    let top = rect.bottom + 5;
    if (top + dropdownHeight > window.innerHeight) {
      if (rect.top - dropdownHeight - 5 > 0) {
        top = rect.top - dropdownHeight - 5;
      } else {
        top = Math.max(10, window.innerHeight - dropdownHeight - 10);
      }
    }
    setDropdownStyle({
      position: 'fixed',
      top: top,
      left: rect.left,
      width: rect.width,
      zIndex: 9999,
    });
  }, [filteredOptions.length]);

  // Close dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event) {
      if (containerRef.current && !containerRef.current.contains(event.target)) {
        const listbox = document.getElementById(`${selectId}-listbox`);
        if (listbox && listbox.contains(event.target)) return;
        setIsOpen(false);
        setSearchQuery('');
      }
    }
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, selectId]);

  // Recompute position on scroll / resize while open
  useEffect(() => {
    if (!isOpen) return;
    updateDropdownPosition();
    window.addEventListener('scroll', updateDropdownPosition, true);
    window.addEventListener('resize', updateDropdownPosition);
    return () => {
      window.removeEventListener('scroll', updateDropdownPosition, true);
      window.removeEventListener('resize', updateDropdownPosition);
    };
  }, [isOpen, updateDropdownPosition]);

  const handleSelect = (val) => {
    if (disabled) return;
    setIsOpen(false);
    setSearchQuery('');
    if (onChange) {
      onChange({
        target: {
          id: selectId,
          name: selectName,
          value: val,
        }
      });
    }
  };

  const handleInputChange = (e) => {
    const val = e.target.value;
    setSearchQuery(val);
    if (!isOpen) setIsOpen(true);
    setHighlightedIndex(0);
  };

  const handleInputFocus = () => {
    setIsFocused(true);
    if (!isOpen) {
      updateDropdownPosition();
      setIsOpen(true);
      setSearchQuery('');
      const idx = normalizedOptions.findIndex(opt => String(opt.value) === String(value));
      setHighlightedIndex(idx >= 0 ? idx : 0);
    }
  };

  const handleKeyDown = (e) => {
    if (disabled) return;

    switch (e.key) {
      case 'Enter':
        if (isOpen) {
          e.preventDefault();
          if (highlightedIndex >= 0 && highlightedIndex < filteredOptions.length) {
            handleSelect(filteredOptions[highlightedIndex].value);
          }
        }
        break;
      case 'ArrowDown':
        e.preventDefault();
        if (!isOpen) {
          setIsOpen(true);
          updateDropdownPosition();
        } else if (filteredOptions.length > 0) {
          setHighlightedIndex(prev => (prev + 1) % filteredOptions.length);
        }
        break;
      case 'ArrowUp':
        e.preventDefault();
        if (!isOpen) {
          setIsOpen(true);
          updateDropdownPosition();
        } else if (filteredOptions.length > 0) {
          setHighlightedIndex(prev => (prev - 1 + filteredOptions.length) % filteredOptions.length);
        }
        break;
      case 'Escape':
        if (isOpen) {
          e.preventDefault();
          setIsOpen(false);
          setSearchQuery('');
        }
        break;
      default:
        break;
    }
  };

  // What text is displayed inside the input element
  const displayValue = isOpen ? searchQuery : (selectedOption ? selectedOption.label : '');

  const inputStyle = {
    width: '100%',
    background: disabled ? 'rgba(0,0,0,0.03)' : 'rgba(255,255,255,0.65)',
    border: error
      ? '1.5px solid #b91c1c'
      : (isFocused && !disabled ? '1.5px solid #705d00' : '1.5px solid rgba(0,0,0,0.1)'),
    borderRadius: 10,
    padding: '9px 36px 9px 13px',
    fontSize: 14,
    fontWeight: 500,
    color: disabled ? '#a09888' : '#1a1c1d',
    fontFamily: 'Inter, sans-serif',
    outline: 'none',
    cursor: disabled ? 'not-allowed' : 'text',
    boxShadow: error
      ? '0 0 0 3px rgba(185,28,28,0.1)'
      : (isFocused && !disabled ? '0 0 0 3px rgba(112,93,0,0.1)' : 'none'),
    transition: 'border-color 0.2s, box-shadow 0.2s, background 0.2s',
    boxSizing: 'border-box',
    ...style,
  };

  const dropdown = isOpen && ReactDOM.createPortal(
    <ul
      id={`${selectId}-listbox`}
      role="listbox"
      tabIndex={-1}
      aria-activedescendant={highlightedIndex >= 0 ? `${selectId}-opt-${highlightedIndex}` : undefined}
      style={{
        ...dropdownStyle,
        background: 'rgba(255, 255, 255, 0.98)',
        border: '1px solid rgba(0,0,0,0.12)',
        boxShadow: '0 12px 36px rgba(0, 0, 0, 0.15)',
        borderRadius: 12,
        maxHeight: 230,
        overflowY: 'auto',
        padding: '4px 0',
        margin: 0,
        listStyle: 'none',
      }}
    >
      {filteredOptions.length === 0 ? (
        <li style={{ padding: '12px 14px', fontSize: 13, color: '#888', textAlign: 'center' }}>
          No matching options
        </li>
      ) : (
        filteredOptions.map((opt, index) => {
          const isSelected = String(opt.value) === String(value);
          const isHighlighted = index === highlightedIndex;

          let itemBackground = 'transparent';
          let itemColor = '#1a1c1d';

          if (isSelected) {
            itemBackground = 'rgba(255, 215, 0, 0.18)';
            itemColor = '#705d00';
          }
          if (isHighlighted) {
            itemBackground = 'rgba(255, 215, 0, 0.35)';
          }

          return (
            <li
              key={opt.value}
              id={`${selectId}-opt-${index}`}
              role="option"
              aria-selected={isSelected}
              onMouseDown={(e) => {
                e.preventDefault();
                handleSelect(opt.value);
              }}
              onMouseEnter={() => setHighlightedIndex(index)}
              style={{
                padding: '9px 14px',
                fontSize: 13.5,
                fontWeight: isSelected ? 600 : 500,
                color: itemColor,
                background: itemBackground,
                cursor: 'pointer',
                transition: 'background 0.15s, color 0.15s',
                userSelect: 'none',
              }}
            >
              {opt.label}
            </li>
          );
        })
      )}
    </ul>,
    document.body
  );

  return (
    <div ref={containerRef} style={{ display: 'flex', flexDirection: 'column', gap: 5, position: 'relative', width: '100%' }}>
      {label && (
        <label
          htmlFor={selectId}
          style={{
            fontSize: 11,
            fontWeight: 700,
            letterSpacing: '0.06em',
            textTransform: 'uppercase',
            color: '#5e5e5e',
            userSelect: 'none',
          }}
        >
          {label}
        </label>
      )}
      <div style={{ position: 'relative', width: '100%' }}>
        <input
          ref={inputRef}
          id={selectId}
          type="text"
          disabled={disabled}
          value={displayValue}
          onChange={handleInputChange}
          onFocus={handleInputFocus}
          onBlur={() => setIsFocused(false)}
          onKeyDown={handleKeyDown}
          placeholder={selectedOption ? selectedOption.label : placeholder}
          aria-haspopup="listbox"
          aria-expanded={isOpen}
          aria-controls={`${selectId}-listbox`}
          style={inputStyle}
          autoComplete="off"
          {...props}
        />
        <ChevronDown
          size={14}
          onClick={() => {
            if (!disabled) {
              if (isOpen) {
                setIsOpen(false);
              } else {
                inputRef.current?.focus();
              }
            }
          }}
          style={{
            position: 'absolute',
            right: 12,
            top: '50%',
            transform: isOpen ? 'translateY(-50%) rotate(180deg)' : 'translateY(-50%)',
            color: disabled ? '#b0a896' : '#5e5e5e',
            transition: 'transform 0.2s',
            cursor: 'pointer',
            pointerEvents: 'auto',
          }}
        />

        {dropdown}
      </div>
      {error && (
        <p style={{ fontSize: 12, color: '#b91c1c', marginTop: 2, paddingLeft: 2 }}>{error}</p>
      )}
    </div>
  );
}

