import { useState, useRef } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { registerUser } from "@/store/authSlice";
import toast from "react-hot-toast";
import CustomSelect from "@/components/ui/CustomSelect";
import SingleDatePickerModal from "@/components/ui/SingleDatePickerModal";
import { formatDisplayDate } from "@/components/ui/DatePickerModal";
import { PASSWORD_RULES } from "@/utils/validators";

export default function RegisterPage() {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { loading } = useSelector((state) => state.auth);

  const [formData, setFormData] = useState({
    first_name: "",
    last_name: "",
    gender: "Male",
    date_of_birth: "",
    username: "",
    email: "",
    password: "",
    confirm_password: "",
  });

  const [touched, setTouched] = useState({});
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isDobModalOpen, setIsDobModalOpen] = useState(false);
  const [isPasswordFocused, setIsPasswordFocused] = useState(false);

  // Input Refs for Auto-Focus
  const inputRefs = {
    first_name: useRef(null),
    last_name: useRef(null),
    date_of_birth: useRef(null),
    username: useRef(null),
    email: useRef(null),
    password: useRef(null),
    confirm_password: useRef(null),
  };

  const genderOptions = [
    { label: "Male", value: "Male" },
    { label: "Female", value: "Female" },
    { label: "Other", value: "Other" },
  ];

  // Age Calculator
  const calculateAge = (dobString) => {
    if (!dobString) return 0;
    const birthDate = new Date(dobString);
    const today = new Date();
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      age--;
    }
    return age;
  };

  // Password Live Strength Criteria Checks
  const passwordRules = PASSWORD_RULES.map(rule => ({
    ...rule,
    met: rule.test(formData.password)
  }));

  const isPasswordStrong = passwordRules.every((rule) => rule.met);

  // Show requirements when typing, focused, or if password has errors
  const showPasswordRequirements =
    isPasswordFocused || (formData.password.length > 0 && !isPasswordStrong);

  const handleChange = (e) => {
    const { name, value } = e.target;

    // First and last name: only alphabets, max 20 chars
    if (name === "first_name" || name === "last_name") {
      if (value.length > 20) return;
      if (value !== "" && !/^[a-zA-Z]+$/.test(value)) return;
    }

    // Username: max 20 chars
    if (name === "username" && value.length > 20) {
      return;
    }

    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleBlur = (e) => {
    const { name } = e.target;
    setTouched((prev) => ({ ...prev, [name]: true }));
    if (name === "password") {
      setIsPasswordFocused(false);
    }
  };

  const handlePasswordFocus = () => {
    setIsPasswordFocused(true);
  };

  // Field validation rules
  const getFieldError = (name) => {
    if (!touched[name] && !formData[name]) return "";

    switch (name) {
      case "first_name":
        if (!formData.first_name.trim()) return "First name is required";
        if (!/^[a-zA-Z]+$/.test(formData.first_name)) return "Only alphabets are allowed";
        break;

      case "last_name":
        if (!formData.last_name.trim()) return "Last name is required";
        if (!/^[a-zA-Z]+$/.test(formData.last_name)) return "Only alphabets are allowed";
        break;

      case "date_of_birth":
        if (!formData.date_of_birth) return "Date of birth is required";
        const age = calculateAge(formData.date_of_birth);
        if (age < 18) return "You must be at least 18 years old to register";
        break;

      case "username":
        if (!formData.username.trim()) return "Username is required";
        if (formData.username.startsWith("_")) return "Cannot start with an underscore";
        if (!/^[a-zA-Z0-9_]+$/.test(formData.username)) return "Only letters, numbers, and underscores allowed";
        if (formData.username.length < 3) return "Must be at least 3 characters";
        break;

      case "email":
        if (!formData.email.trim()) return "Email is required";
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) return "Invalid email address";
        break;

      case "password":
        if (!formData.password) return "Password is required";
        if (!isPasswordStrong) return "Please fulfill all password requirements";
        break;

      case "confirm_password":
        if (!formData.confirm_password) return "Please confirm password";
        if (formData.confirm_password !== formData.password) return "Passwords do not match";
        break;

      default:
        return "";
    }
    return "";
  };

  const errors = {
    first_name: getFieldError("first_name"),
    last_name: getFieldError("last_name"),
    date_of_birth: getFieldError("date_of_birth"),
    username: getFieldError("username"),
    email: getFieldError("email"),
    password: getFieldError("password"),
    confirm_password: getFieldError("confirm_password"),
  };

  const isPasswordMatched =
    formData.confirm_password !== "" && formData.confirm_password === formData.password;

  const userAge = calculateAge(formData.date_of_birth);

  const isFormValid =
    formData.first_name.trim() !== "" &&
    formData.last_name.trim() !== "" &&
    formData.date_of_birth !== "" &&
    userAge >= 18 &&
    formData.username.trim() !== "" &&
    !formData.username.startsWith("_") &&
    formData.email.trim() !== "" &&
    isPasswordStrong &&
    formData.confirm_password !== "" &&
    isPasswordMatched &&
    !Object.values(errors).some((err) => err !== "");

  // Focus first invalid element
  const focusFirstInvalidField = () => {
    const fieldOrder = [
      "first_name",
      "last_name",
      "date_of_birth",
      "username",
      "email",
      "password",
      "confirm_password",
    ];

    for (const field of fieldOrder) {
      let isInvalid = false;

      if (field === "first_name" && (!formData.first_name.trim() || !/^[a-zA-Z]+$/.test(formData.first_name))) {
        isInvalid = true;
      } else if (field === "last_name" && (!formData.last_name.trim() || !/^[a-zA-Z]+$/.test(formData.last_name))) {
        isInvalid = true;
      } else if (field === "date_of_birth" && (!formData.date_of_birth || calculateAge(formData.date_of_birth) < 18)) {
        isInvalid = true;
      } else if (field === "username" && (!formData.username.trim() || formData.username.startsWith("_") || !/^[a-zA-Z0-9_]+$/.test(formData.username) || formData.username.length < 3)) {
        isInvalid = true;
      } else if (field === "email" && (!formData.email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email))) {
        isInvalid = true;
      } else if (field === "password" && (!formData.password || !isPasswordStrong)) {
        isInvalid = true;
      } else if (field === "confirm_password" && (!formData.confirm_password || formData.confirm_password !== formData.password)) {
        isInvalid = true;
      }

      if (isInvalid) {
        if (field === "date_of_birth") {
          setIsDobModalOpen(true);
        } else if (inputRefs[field]?.current) {
          inputRefs[field].current.focus();
        }
        break;
      }
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setTouched({
      first_name: true,
      last_name: true,
      date_of_birth: true,
      username: true,
      email: true,
      password: true,
      confirm_password: true,
    });

    if (!isFormValid) {
      focusFirstInvalidField();
      return;
    }

    try {
      const payload = {
        username: formData.username.trim(),
        email: formData.email.trim(),
        first_name: formData.first_name.trim(),
        last_name: formData.last_name.trim(),
        password: formData.password,
      };

      const resultAction = await dispatch(registerUser(payload));

      if (registerUser.fulfilled.match(resultAction)) {
        toast.success("Account created successfully! Please sign in.");
        navigate("/login");
      } else {
        const errorMsg = resultAction.payload || "Registration failed";
        toast.error(errorMsg);
      }
    } catch (err) {
      toast.error("An unexpected error occurred. Please try again.");
    }
  };

  return (
    <div className="relative overflow-hidden min-h-[calc(100vh-3.5rem)] flex flex-col items-center justify-center px-4 py-12 mt-16 bg-slate-50/60">

      {/* Sky-themed Soft Ambient Aesthetic Blobs */}
      <div className="absolute top-1/4 -left-20 w-96 h-96 bg-sky-200/50 rounded-full blur-3xl pointer-events-none animate-pulse" />
      <div className="absolute bottom-10 -right-20 w-96 h-96 bg-amber-200/40 rounded-full blur-3xl pointer-events-none" />
      <div className="absolute top-10 right-1/4 w-72 h-72 bg-blue-100/60 rounded-full blur-3xl pointer-events-none" />

      {/* Header */}
      <div className="relative z-10 text-center mb-4">
        <h2 className="text-xl font-bold text-slate-800">Create an Account</h2>
      </div>

      {/* Container Card */}
      <div className="relative z-10 w-full max-w-lg rounded-3xl p-8 sm:px-10 animate-fade-in plain-card">

        {/* Back to Sign In Header */}
        <div className="mb-4">
          <Link
            to="/login"
            className="inline-flex items-center gap-2 text-slate-600 font-semibold text-xs hover:text-slate-900 transition-colors mb-3"
          >
            <span className="material-symbols-outlined text-xs select-none">arrow_back</span>
            Back to Sign In
          </Link>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-4">

          {/* First & Last Name */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-2 ml-2">
                First name
              </label>
              <input
                ref={inputRefs.first_name}
                type="text"
                name="first_name"
                value={formData.first_name}
                onChange={handleChange}
                onBlur={handleBlur}
                placeholder="First name"
                className="input-field"
              />
              {errors.first_name && (
                <div className="overflow-hidden transition-all duration-200 mt-1 animate-fade-in">
                  <p className="field-error ml-2">{errors.first_name}</p>
                </div>
              )}
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-2 ml-2">
                Last name
              </label>
              <input
                ref={inputRefs.last_name}
                type="text"
                name="last_name"
                value={formData.last_name}
                onChange={handleChange}
                onBlur={handleBlur}
                placeholder="Last name"
                className="input-field"
              />
              {errors.last_name && (
                <div className="overflow-hidden transition-all duration-200 mt-1 animate-fade-in">
                  <p className="field-error ml-2">{errors.last_name}</p>
                </div>
              )}
            </div>
          </div>

          {/* Gender & Date of Birth */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-2 ml-2">
                Gender
              </label>
              <CustomSelect
                value={formData.gender}
                onChange={(val) => setFormData((prev) => ({ ...prev, gender: val }))}
                options={genderOptions}
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-2 ml-2">
                Date of Birth
              </label>
              <button
                ref={inputRefs.date_of_birth}
                type="button"
                onClick={() => setIsDobModalOpen(true)}
                className="input-field flex items-center justify-between text-left cursor-pointer w-full"
              >
                <span className={formData.date_of_birth ? "text-slate-800 font-semibold" : "text-slate-400"}>
                  {formData.date_of_birth ? formatDisplayDate(formData.date_of_birth) : "Select DOB"}
                </span>
                <span className="material-symbols-outlined text-sm text-slate-500">calendar_today</span>
              </button>
              {errors.date_of_birth && (
                <div className="overflow-hidden transition-all duration-200 mt-1 animate-fade-in">
                  <p className="field-error ml-2">{errors.date_of_birth}</p>
                </div>
              )}
            </div>
          </div>

          {/* Username & Email */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-2 ml-2">
                Username
              </label>
              <input
                ref={inputRefs.username}
                type="text"
                name="username"
                value={formData.username}
                onChange={handleChange}
                onBlur={handleBlur}
                placeholder="Choose username"
                className="input-field"
              />
              {errors.username && (
                <div className="overflow-hidden transition-all duration-200 mt-1 animate-fade-in">
                  <p className="field-error ml-2">{errors.username}</p>
                </div>
              )}
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-2 ml-2">
                Email
              </label>
              <input
                ref={inputRefs.email}
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                onBlur={handleBlur}
                placeholder="your@email.com"
                className="input-field"
              />
              {errors.email && (
                <div className="overflow-hidden transition-all duration-200 mt-1 animate-fade-in">
                  <p className="field-error ml-2">{errors.email}</p>
                </div>
              )}
            </div>
          </div>

          {/* Password with Collapsible Vertical Live Strength Checklist */}
          <div>
            <label className="block text-xs font-semibold text-slate-600 mb-2 ml-2">
              Password
            </label>
            <div className="relative flex items-center">
              <input
                ref={inputRefs.password}
                type={showPassword ? "text" : "password"}
                name="password"
                value={formData.password}
                onChange={handleChange}
                onFocus={handlePasswordFocus}
                onBlur={handleBlur}
                placeholder="Create a strong password"
                className="input-field"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3.5 text-slate-500 hover:text-slate-800 transition-colors cursor-pointer select-none"
              >
                <span className="material-symbols-outlined text-sm">
                  {showPassword ? "visibility_off" : "visibility"}
                </span>
              </button>
            </div>

            {/* Collapsible Password Requirements List in Vertical Order */}
            {showPasswordRequirements && (
              <div className="mt-2.5 p-3 bg-[#f8f9fa] rounded-2xl border border-slate-100 animate-fade-in">
                <div className="flex flex-col gap-1.5">
                  {passwordRules.map((rule) => (
                    <div
                      key={rule.id}
                      className={`flex items-center gap-2 transition-colors duration-200 ${rule.met ? "text-emerald-600 font-semibold" : "text-slate-400 font-medium"
                        }`}
                    >
                      <span
                        className={`material-symbols-outlined text-sm font-bold transition-all ${rule.met ? "text-emerald-500 scale-110" : "text-slate-300"
                          }`}
                      >
                        {rule.met ? "check_circle" : "radio_button_unchecked"}
                      </span>
                      <span className="text-[11px] select-none">{rule.label}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {errors.password && touched.password && !isPasswordStrong && !showPasswordRequirements && (
              <div className="overflow-hidden transition-all duration-200 mt-1 animate-fade-in">
                <p className="field-error ml-2">{errors.password}</p>
              </div>
            )}
          </div>

          {/* Confirm Password */}
          <div>
            <label className="block text-xs font-semibold text-slate-600 mb-2 ml-2">
              Confirm Password
            </label>
            <div className="relative flex items-center">
              <input
                ref={inputRefs.confirm_password}
                type={showConfirmPassword ? "text" : "password"}
                name="confirm_password"
                value={formData.confirm_password}
                onChange={handleChange}
                onBlur={handleBlur}
                placeholder="Repeat your password"
                className="input-field pr-16"
              />
              <div className="absolute right-3.5 flex items-center gap-1.5">
                {isPasswordMatched && (
                  <span className="material-symbols-outlined text-xs font-bold text-slate-800 animate-fade-in">
                    check
                  </span>
                )}
                <button
                  type="button"
                  onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                  className="text-slate-500 hover:text-slate-800 transition-colors cursor-pointer select-none"
                >
                  <span className="material-symbols-outlined text-sm">
                    {showConfirmPassword ? "visibility_off" : "visibility"}
                  </span>
                </button>
              </div>
            </div>
            {errors.confirm_password && (
              <div className="overflow-hidden transition-all duration-200 mt-1 animate-fade-in">
                <p className="field-error ml-2">{errors.confirm_password}</p>
              </div>
            )}
          </div>

          {/* Create Account Button */}
          <div className="flex justify-center pt-2">
            <button
              type="submit"
              disabled={loading}
              className="btn-primary px-5 py-2 rounded-xl text-sm"
            >
              {loading ? (
                <>
                  <span className="w-4 h-4 border-2 border-slate-900 border-t-transparent rounded-full animate-spin" />
                  Creating account...
                </>
              ) : (
                "Create account"
              )}
            </button>
          </div>

        </form>

        {/* Footer Link */}
        <div className="mt-8 text-center pt-5 border-t border-slate-100">
          <p className="text-xs font-semibold text-slate-500">
            Already have an account?{" "}
            <Link to="/login" className="text-slate-900 font-bold hover:underline transition-all">
              Sign In
            </Link>
          </p>
        </div>

      </div>

      {/* Date of Birth Picker Modal */}
      <SingleDatePickerModal
        isOpen={isDobModalOpen}
        onClose={() => setIsDobModalOpen(false)}
        initialDate={formData.date_of_birth}
        title="Select Date of Birth"
        onSelectDate={(dateStr) => {
          setFormData((prev) => ({ ...prev, date_of_birth: dateStr }));
          setTouched((prev) => ({ ...prev, date_of_birth: true }));
        }}
      />
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { useParams, useNavigate, useLocation } from "react-router-dom";
import { flightsAPI } from "@/services/flight-service/flightService";
import { bookingAPI } from "@/services/booking-service/bookingService";
import { waitlistAPI } from "@/services/waitlist-service/waitlistService";
import FlightItinerarySummaryCard from "@/components/flights/FlightItinerarySummaryCard";
import FareDetailsCard from "@/components/flights/FareDetailsCard";
import CheckoutStepper from "@/components/bookings/CheckoutStepper";
import BookingReviewCard from "@/components/bookings/BookingReviewCard";
import ComplimentaryMealCard from "@/components/meals/ComplimentaryMealCard";
import PassengerListSection from "@/components/flights/PassengerListSection";
import toast from "react-hot-toast";

export default function BookingCheckoutPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const location = useLocation();

  // Selected cabin and initial seat count passed from FlightDetailPage state (defaults if accessed directly)
  const initialCabin = location.state?.selectedCabin || "ECONOMY";
  const initialSeatCount = location.state?.seatCount || 1;

  const [flight, setFlight] = useState(null);
  const [mealsData, setMealsData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  const [selectedCabin, setSelectedCabin] = useState(initialCabin);
  const [currentStepIndex, setCurrentStepIndex] = useState(0);

  // Passenger data state
  const [passengers, setPassengers] = useState(
    Array.from({ length: initialSeatCount }, (_, i) => ({
      id: Date.now() + i,
      name: "",
      age: "",
      gender: "Male",
    }))
  );

  // Complimentary meal preferences state: { [paxIdx]: 'VEG' | 'NON_VEG' | 'NONE' }
  const [complimentaryPrefMap, setComplimentaryPrefMap] = useState({});

  // Paid add-on meals mapping state: { [paxIdx]: [{ food_item_id, flight_meal_id, flight_leg_id, quantity, price, name }] }
  const [selectedMealsMap, setSelectedMealsMap] = useState({});

  useEffect(() => {
    async function loadCheckoutData() {
      try {
        setLoading(true);
        const [flightData, mealsResp] = await Promise.all([
          flightsAPI.retrieve(id),
          flightsAPI.getMeals(id, { cabin_class: selectedCabin }).catch((err) => {
            console.warn("Could not load meals data from backend API:", err);
            return null;
          }),
        ]);
        setFlight(flightData);
        setMealsData(mealsResp);
      } catch (err) {
        console.error("Failed to load flight details:", err);
        toast.error("Flight not found or unavailable.");
      } finally {
        setLoading(false);
      }
    }
    loadCheckoutData();
  }, [id, selectedCabin]);

  if (loading) {
    return (
      <div className="flex-1 min-h-screen mt-12 pt-12 pb-16 px-4 md:px-8 max-w-6xl mx-auto w-full animate-pulse space-y-8">
        <div className="h-20 bg-slate-200 rounded-3xl" />
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-8 h-96 bg-slate-100 rounded-3xl" />
          <div className="lg:col-span-4 h-96 bg-slate-200 rounded-3xl" />
        </div>
      </div>
    );
  }

  if (!flight) {
    return (
      <div className="flex-1 min-h-screen mt-12 pt-16 pb-16 px-4 max-w-md mx-auto text-center space-y-4">
        <h2 className="text-xl font-bold text-slate-900">Flight Not Found</h2>
        <button
          onClick={() => navigate("/flights")}
          className="btn-primary py-2.5 px-6"
        >
          Back to Search
        </button>
      </div>
    );
  }

  // Active fare for cabin & meals backend data
  const normCabin = (selectedCabin || "ECONOMY").toUpperCase();
  const fareObj = flight.fares?.[normCabin] || flight.fares?.["ECONOMY"] || null;
  const isMealIncluded = Boolean(mealsData?.meal_included ?? fareObj?.meal_included);
  const foodItems = mealsData?.food_items || [];
  const flightMeals = mealsData?.flight_meals || [];
  const targetCurrency = mealsData?.target_currency || fareObj?.currency || "INR";
  const availableSeats = fareObj?.available_seats ?? flight.available_seats ?? 0;
  const isWaitlisted = Number(availableSeats) === 0;

  const hasMealsOrAddons = isMealIncluded || foodItems.length > 0 || flightMeals.length > 0;

  // Calculate total meal cost from paid add-ons
  const calculateMealTotal = () => {
    let sum = 0;
    Object.values(selectedMealsMap).forEach((mealList) => {
      if (Array.isArray(mealList)) {
        mealList.forEach((m) => {
          sum += (Number(m.price) || 0) * (Number(m.quantity) || 1);
        });
      }
    });
    return sum;
  };

  const mealTotal = calculateMealTotal();

  // Dynamically define stepper steps
  const steps = [
    { id: "passengers", title: "Passengers", subtitle: "Passenger Details" },
    ...(hasMealsOrAddons
      ? [{ id: "free_meal", title: "Meals & Menu", subtitle: "In-Flight Selection" }]
      : []),
    { id: "review", title: "Payment", subtitle: "Confirm Booking" },
  ];

  const currentStepObj = steps[currentStepIndex] || steps[0];
  const currentStepNumber = currentStepIndex + 1;

  const handleComplimentaryPrefChange = (paxIdx, prefKey) => {
    setComplimentaryPrefMap((prev) => ({
      ...prev,
      [paxIdx]: prefKey,
    }));
    setSelectedMealsMap((prev) => ({
      ...prev,
      [paxIdx]: [],
    }));
  };

  const handleMealSelection = (paxIdx, selectedItem) => {
    if (!selectedItem || selectedItem.key === "NONE") {
      setComplimentaryPrefMap((prev) => ({ ...prev, [paxIdx]: "NONE" }));
      setSelectedMealsMap((prev) => ({ ...prev, [paxIdx]: [] }));
      return;
    }

    const itemPrice = isMealIncluded ? 0 : Number(selectedItem.display_price || selectedItem.price || 0);

    if (selectedItem.food_item_id) {
      const pref = selectedItem.is_veg ? "VEG" : "NON_VEG";
      setComplimentaryPrefMap((prev) => ({ ...prev, [paxIdx]: pref }));
      setSelectedMealsMap((prev) => ({
        ...prev,
        [paxIdx]: [
          {
            food_item_id: selectedItem.food_item_id,
            name: selectedItem.name,
            price: itemPrice,
            display_currency: selectedItem.display_currency || targetCurrency,
            quantity: 1,
          },
        ],
      }));
    } else if (selectedItem.flight_meal_id) {
      setComplimentaryPrefMap((prev) => ({ ...prev, [paxIdx]: "NON_VEG" }));
      setSelectedMealsMap((prev) => ({
        ...prev,
        [paxIdx]: [
          {
            flight_meal_id: selectedItem.flight_meal_id,
            name: selectedItem.name,
            price: itemPrice,
            display_currency: selectedItem.display_currency || targetCurrency,
            quantity: 1,
          },
        ],
      }));
    }
  };

  // Step Validation & Navigation
  const validateCurrentStep = () => {
    if (currentStepObj.id === "passengers") {
      for (let i = 0; i < passengers.length; i++) {
        const p = passengers[i];
        if (!p.name || p.name.trim().length < 2) {
          toast.error(`Please enter a valid name for Passenger ${i + 1}.`);
          return false;
        }
        if (!p.age || Number(p.age) < 1 || Number(p.age) > 120) {
          toast.error(`Please enter a valid age (1-120) for Passenger ${i + 1}.`);
          return false;
        }
      }
    }
    return true;
  };

  const handleNext = () => {
    if (!validateCurrentStep()) return;
    if (currentStepIndex < steps.length - 1) {
      setCurrentStepIndex(currentStepIndex + 1);
    }
  };

  const handleBack = () => {
    if (currentStepIndex > 0) {
      setCurrentStepIndex(currentStepIndex - 1);
    } else {
      navigate(`/flights/${id}`);
    }
  };

  // Submit Booking
  const handleConfirmBooking = async () => {
    if (!validateCurrentStep()) return;

    setSubmitting(true);
    try {
      const formattedPassengers = passengers.map((p, idx) => {
        const mealPref = complimentaryPrefMap[idx] || (isMealIncluded ? "VEG" : "NONE");
        const paidMeals = selectedMealsMap[idx] || [];

        const g = (p.gender || "").toUpperCase();
        const genderCode = g.startsWith("F") ? "F" : g.startsWith("O") ? "O" : "M";

        return {
          name: p.name.trim(),
          age: parseInt(p.age, 10),
          gender: genderCode,
          phone_number: p.phone_number?.trim() || "",
          meal_preference: mealPref,
          selected_meals: paidMeals.map((m) => ({
            food_item_id: m.food_item_id || null,
            flight_meal_id: m.flight_meal_id || null,
            flight_leg_id: m.flight_leg_id || null,
            quantity: m.quantity || 1,
          })),
        };
      });

      if (isWaitlisted) {
        const response = await waitlistAPI.join(id, formattedPassengers, selectedCabin);
        toast.success(`Successfully joined waitlist (Position #${response.queue_position || 1})!`);
        navigate(`/booking-confirmation/waitlist/${response.id}`);
      } else {
        const response = await bookingAPI.create(id, formattedPassengers, selectedCabin);
        toast.success("Flight booking confirmed successfully!");
        navigate(`/booking-confirmation/${response.id}`);
      }
    } catch (err) {
      console.error("Booking error:", err);
      const errMsg =
        err.message ||
        err.response?.data?.error ||
        err.response?.data?.detail ||
        "Failed to process booking. Please try again.";
      toast.error(errMsg);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="flex-1 min-h-screen mt-12 pt-12 pb-8 px-4 md:px-6 max-w-6xl mx-auto w-full space-y-6 animate-fade-in">
      {/* Top Navigation */}
      <div className="ml-4">
        <button
          type="button"
          onClick={() => navigate(`/flights/${id}`)}
          className="text-xs font-semibold text-slate-600 hover:text-slate-950 cursor-pointer transition-colors flex items-center gap-1.5"
        >
          <span className="material-symbols-outlined text-base">arrow_back</span>
          Back to Flight Details
        </button>
        <h1 className="text-xl font-bold text-slate-950 mt-3">
          Confirm Booking
        </h1>
      </div>

      {/* Flight Header Summary */}
      <FlightItinerarySummaryCard flight={flight} />

      {/* Main Grid: Left Stepper Forms, Right Sticky Fare Details */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        {/* Left Column - Active Step Content */}
        <div className="lg:col-span-8 space-y-6">

          {/* Stepper Progress Bar */}
          <CheckoutStepper
            currentStep={currentStepNumber}
            steps={steps}
            onStepClick={(stepNum) => {
              const targetIdx = stepNum - 1;
              if (targetIdx < currentStepIndex) {
                setCurrentStepIndex(targetIdx);
              } else if (targetIdx > currentStepIndex) {
                if (validateCurrentStep()) {
                  setCurrentStepIndex(targetIdx);
                }
              }
            }}
          />

          {/* STEP: Passenger Information */}
          {currentStepObj.id === "passengers" && (
            <PassengerListSection
              passengers={passengers}
              onChangePassengers={setPassengers}
            />
          )}

          {/* STEP: Meal / Food Selection */}
          {currentStepObj.id === "free_meal" && (
            <ComplimentaryMealCard
              passengers={passengers}
              selectedCabin={selectedCabin}
              foodItems={foodItems}
              flightMeals={flightMeals}
              isMealIncluded={isMealIncluded}
              targetCurrency={targetCurrency}
              preferencesMap={complimentaryPrefMap}
              selectedMealsMap={selectedMealsMap}
              onMealSelect={handleMealSelection}
              onPreferenceChange={handleComplimentaryPrefChange}
            />
          )}

          {/* STEP: Review & Final Confirmation */}
          {currentStepObj.id === "review" && (
            <BookingReviewCard
              passengers={passengers}
              isMealIncluded={isMealIncluded}
              complimentaryPrefMap={complimentaryPrefMap}
              selectedMealsMap={selectedMealsMap}
            />
          )}

          {/* Stepper Navigation Actions */}
          <div className="flex items-center justify-between pt-2">
            <button
              type="button"
              onClick={handleBack}
              className="btn-outline-plain py-2.5 px-6 text-xs font-bold rounded-xl cursor-pointer"
            >
              &larr; Back
            </button>

            {currentStepIndex < steps.length - 1 ? (
              <button
                type="button"
                onClick={handleNext}
                className="btn-primary py-2.5 px-5 text-xs font-bold rounded-xl cursor-pointer flex items-center gap-2"
              >
                <span>Continue</span>
                <span className="material-symbols-outlined text-xs">arrow_forward</span>
              </button>
            ) : (
              <button
                type="button"
                disabled={submitting}
                onClick={handleConfirmBooking}
                className="btn-primary py-2.5 px-5 text-xs font-bold rounded-xl cursor-pointer flex items-center gap-2"
              >
                {submitting ? (
                  <span>Processing Booking...</span>
                ) : isWaitlisted ? (
                  <span>Join Waitlist</span>
                ) : (
                  <span>Confirm Ticket & Pay &rarr;</span>
                )}
              </button>
            )}
          </div>
        </div>

        {/* Right Column - Sticky Fare Details Summary */}
        <div className="lg:col-span-4 lg:sticky lg:top-24 space-y-6">
          <FareDetailsCard
            flight={flight}
            selectedCabin={selectedCabin}
            passengerCount={passengers.length}
            mealTotal={mealTotal}
            onBookingAction={currentStepIndex < steps.length - 1 ? handleNext : handleConfirmBooking}
            actionButtonText={currentStepIndex < steps.length - 1 ? "Continue" : (isWaitlisted ? "Join Waitlist" : "Confirm Ticket & Pay")}
          />
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useParams, useNavigate, useSearchParams, useLocation } from "react-router-dom";
import { useSelector } from "react-redux";
import { flightsAPI } from "@/services/flight-service/flightService";
import FlightItineraryCard from "@/components/flights/FlightItineraryCard";
import CabinClassSelector from "@/components/flights/CabinClassSelector";
import FareDetailsCard from "@/components/flights/FareDetailsCard";
import toast from "react-hot-toast";

export default function FlightDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const [searchParams] = useSearchParams();
  const auth = useSelector((state) => state?.auth) || {};
  const isAuthenticated = Boolean(auth.isAuthenticated || auth.token);

  const initialCabinParam = searchParams.get("cabinClass");
  const initialCabinKey = initialCabinParam
    ? initialCabinParam.toUpperCase().includes("BUSINESS")
      ? "BUSINESS"
      : initialCabinParam.toUpperCase().includes("FIRST")
      ? "FIRST"
      : "ECONOMY"
    : "ECONOMY";

  const [flight, setFlight] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedCabin, setSelectedCabin] = useState(initialCabinKey);
  const [passengerCount, setPassengerCount] = useState(1);

  useEffect(() => {
    let isMounted = true;
    setLoading(true);
    setError(null);

    async function fetchFlightDetail() {
      try {
        const data = await flightsAPI.retrieve(id);
        if (isMounted) {
          setFlight(data);
        }
      } catch (err) {
        console.error("Error fetching flight details:", err);
        if (isMounted) {
          setError("Unable to load flight details. The flight may not exist.");
        }
      } finally {
        if (isMounted) setLoading(false);
      }
    }

    if (id) {
      fetchFlightDetail();
    }

    return () => {
      isMounted = false;
    };
  }, [id]);

  const handleProceedToCheckout = () => {
    if (!isAuthenticated) {
      toast.error("Please login to proceed with flight booking.");
      navigate("/login", { state: { from: `/flights/${id}` } });
      return;
    }

    navigate(`/flights/${id}/checkout`, {
      state: {
        selectedCabin,
        seatCount: passengerCount,
      },
    });
  };

  if (loading) {
    return (
      <div className="flex-1 min-h-screen bg-slate-50/60 pt-16 pb-16 px-4 md:px-6 max-w-6xl mx-auto w-full">
        <div className="flex flex-col lg:flex-row gap-6 items-start">
          <div className="flex-1 w-full space-y-6 animate-pulse">
            <div className="h-64 bg-slate-200 rounded-3xl" />
            <div className="h-44 bg-slate-200 rounded-3xl" />
          </div>
          <div className="w-full lg:w-80 xl:w-96 h-64 bg-slate-200 rounded-3xl animate-pulse" />
        </div>
      </div>
    );
  }

  if (error || !flight) {
    return (
      <div className="flex-1 min-h-screen bg-slate-50/60 pt-20 pb-12 px-4 max-w-4xl mx-auto w-full text-center">
        <div className="plain-card rounded-3xl p-10 max-w-md mx-auto space-y-4">
          <span className="material-symbols-outlined text-4xl text-rose-500">
            error_outline
          </span>
          <h2 className="text-lg font-bold text-slate-900">Flight Not Found</h2>
          <p className="text-xs text-slate-500">{error || "Flight details are unavailable."}</p>
          <button
            type="button"
            onClick={() => navigate("/flights")}
            className="btn-primary px-5 py-2.5 rounded-xl text-xs"
          >
            Back to Search Results
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 min-h-screen mt-12 pt-12 pb-8 px-4 md:px-6 max-w-6xl mx-auto w-full">
      {/* Top Navigation */}
      <div className="mb-6 ml-4">
        <button
          type="button"
          onClick={() => navigate("/flights", { state: { showPastBookings: location.state?.showPastBookings } })}
          className="text-xs font-semibold text-slate-600 hover:text-slate-950 cursor-pointer transition-colors flex items-center gap-1.5"
        >
          <span className="material-symbols-outlined text-base">arrow_back</span>
          Back to Flights List
        </button>
        <h1 className="text-xl font-bold text-slate-950 mt-3">
          Flight Details & Selection
        </h1>
      </div>

      {/* Main 2-Column Responsive Layout */}
      <div className="flex flex-col lg:flex-row gap-6 items-start relative">
        {/* Left Panel */}
        <div className="flex-1 w-full space-y-6">
          {/* Flight Itinerary Card */}
          <FlightItineraryCard flight={flight} selectedCabinClass={selectedCabin} />

          {/* Cabin Class Selection */}
          <CabinClassSelector
            flight={flight}
            selectedCabin={selectedCabin}
            onSelectCabin={setSelectedCabin}
          />
        </div>

        {/* Right Panel (Sticky Fare Details & Proceed Action) */}
        <div className="w-full lg:w-80 xl:w-96 lg:sticky lg:top-24 flex-shrink-0 space-y-4">
          <FareDetailsCard
            flight={flight}
            selectedCabin={selectedCabin}
            passengerCount={1}
            onBookingAction={handleProceedToCheckout}
            actionButtonText="Book Seats"
          />
        </div>
      </div>
    </div>
  );
}

import { parseApiError } from '@/utils/errorUtils';

export const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || '/api';

const dispatchServerDown = async () => {
  try {
    const { store } = await import('@/store');
    const { setServerDown } = await import('@/store/systemSlice');
    store.dispatch(setServerDown(true));
  } catch (err) {
    console.error("Could not dispatch server down state:", err);
  }
};

export const getResponseData = async (res) => {
  if (res.status === 204) return null;
  const text = await res.text();
  if (!text) return null;
  try {
    const json = JSON.parse(text);
    // Unwrap global API response envelope: { status: "success", data: ... }
    if (json && typeof json === 'object' && json.status === 'success') {
      return json.data !== undefined ? json.data : json;
    }
    return json;
  } catch (_) {
    return text;
  }
};

// extractErrorMessage is intentionally not re-exported.
// Use parseApiError from '@/utils/errorUtils' instead.

// Helper to make authenticated requests
export const fetchWithAuth = async (endpoint, options = {}) => {
  const token = localStorage.getItem('access_token');

  const headers = {
    'Content-Type': 'application/json',
    ...(token && { Authorization: `Bearer ${token}` }),
    ...options.headers,
  };

  let response;
  try {
    response = await fetch(`${API_BASE_URL}${endpoint}`, {
      ...options,
      headers,
    });
  } catch (netErr) {
    // Catch network connectivity failure / connection refused
    dispatchServerDown();
    throw new Error("Unable to connect to server. Please check backend connection.");
  }

  // Handle server outage / maintenance statuses (502 Bad Gateway, 503 Service Unavailable, 504 Timeout)
  if (response.status === 502 || response.status === 503 || response.status === 504) {
    dispatchServerDown();
    throw new Error("Server is currently experiencing issues. Please try again shortly.");
  }

  // If unauthorized, attempt token refresh (if a refresh token is present)
  if (response.status === 401 && localStorage.getItem('refresh_token')) {
    try {
      const refreshResponse = await fetch(`${API_BASE_URL}/auth/token/refresh/`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ refresh: localStorage.getItem('refresh_token') }),
      });

      if (refreshResponse.ok) {
        const refreshRaw = await refreshResponse.json();
        const refreshData = (refreshRaw && refreshRaw.status === 'success' && refreshRaw.data)
          ? refreshRaw.data
          : refreshRaw;

        const newAccess = refreshData.access;
        const newRefresh = refreshData.refresh || localStorage.getItem('refresh_token');

        if (newAccess) localStorage.setItem('access_token', newAccess);
        if (newRefresh) localStorage.setItem('refresh_token', newRefresh);

        // Retry the original request with the new token
        headers['Authorization'] = `Bearer ${newAccess}`;
        const retryResponse = await fetch(`${API_BASE_URL}${endpoint}`, {
          ...options,
          headers,
        });
        const retryData = await getResponseData(retryResponse);
        if (!retryResponse.ok) throw new Error(parseApiError(retryData));
        return retryData;
      }
    } catch (refreshErr) {
      console.error("Token refresh failed. Logging out.", refreshErr);
      localStorage.removeItem('access_token');
      localStorage.removeItem('refresh_token');
      window.location.href = '/';
      throw new Error("Session expired. Please log in again.");
    }
  }

  const data = await getResponseData(response);
  if (!response.ok) throw new Error(parseApiError(data));
  return data;
};

import { configureStore } from '@reduxjs/toolkit';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import bookingsReducer, {
  createBooking,
  fetchMyBookings,
  cancelBooking,
  clearCreateState,
} from '@/store/bookingSlice';
import * as bookingService from '@/services/booking-service/bookingService';

/* ── helpers ─────────────────────────────────────── */
vi.mock('@/services/booking-service/bookingService');

const makeStore = () =>
  configureStore({ reducer: { bookings: bookingsReducer } });

const MOCK_FLIGHT = {
  id: 'flight-uuid-1',
  flight_number: 'AG-101',
  airline: 'Passenger',
  aircraft: 'Boeing 737',
  source_airport: 'DEL',
  destination_airport: 'BOM',
  departure_time: new Date(Date.now() + 86400000).toISOString(),
  arrival_time:   new Date(Date.now() + 90000000).toISOString(),
  base_fare: 5000,
  status: 'SCHEDULED',
};

const MOCK_BOOKING = {
  id: 'booking-uuid-1',
  flight: MOCK_FLIGHT.id,
  flight_detail: MOCK_FLIGHT,
  status: 'CONFIRMED',
  created_at: new Date().toISOString(),
};

/* ── tests ────────────────────────────────────────── */
describe('bookingSlice', () => {
  let store;

  beforeEach(() => {
    store = makeStore();
    vi.clearAllMocks();
  });

  // ── Initial state ──
  it('has correct initial state', () => {
    const state = store.getState().bookings;
    expect(state.list).toEqual([]);
    expect(state.createLoading).toBe(false);
    expect(state.createError).toBeNull();
    expect(state.lastCreated).toBeNull();
    expect(state.listLoading).toBe(false);
    expect(state.cancelLoadingId).toBeNull();
  });

  // ── Create booking ──
  describe('createBooking', () => {
    it('sets createLoading=true while pending', async () => {
      bookingService.bookingAPI.create = vi.fn(() => new Promise(() => {}));
      store.dispatch(createBooking('flight-uuid-1'));
      expect(store.getState().bookings.createLoading).toBe(true);
      expect(store.getState().bookings.createError).toBeNull();
    });

    it('sets lastCreated and prepends to list on success', async () => {
      bookingService.bookingAPI.create = vi.fn().mockResolvedValue(MOCK_BOOKING);
      await store.dispatch(createBooking('flight-uuid-1'));

      const state = store.getState().bookings;
      expect(state.createLoading).toBe(false);
      expect(state.lastCreated).toEqual(MOCK_BOOKING);
