      expect(state.list[0]).toEqual(MOCK_BOOKING);
    });

    it('sets createError on failure', async () => {
      bookingService.bookingAPI.create = vi.fn().mockRejectedValue(
        new Error(JSON.stringify({ detail: 'No available seats on this flight.' }))
