const initialToken = localStorage.getItem('access_token');
const decoded = decodeToken(initialToken);

const initialState = {
  token: initialToken,
  decodedToken: decoded,
  profile: null,
  isAuthenticated: !!initialToken,
  isAdmin: decoded?.is_superuser || false,
  loading: false,
  isInitializing: !!initialToken,
  error: null,
};

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    logout: (state) => {
      localStorage.removeItem('access_token');
      localStorage.removeItem('refresh_token');
      state.token = null;
      state.decodedToken = null;
      state.profile = null;
      state.isAuthenticated = false;
      state.isAdmin = false;
      state.error = null;
    },
    clearAuthError: (state) => {
      state.error = null;
    },
    updateProfileSuccess: (state, action) => {
      state.profile = action.payload;
      if (action.payload?.role) {
        state.isAdmin = state.decodedToken?.is_superuser || action.payload.role === 'ADMIN';
      }
    }
  },
  extraReducers: (builder) => {
    builder
      // Login
      .addCase(loginUser.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(loginUser.fulfilled, (state, action) => {
        state.loading = false;
        state.token = action.payload.token;
        state.decodedToken = decodeToken(action.payload.token);
        state.profile = action.payload.profile;
        state.isAuthenticated = true;
        state.isAdmin = state.decodedToken?.is_superuser || action.payload.profile?.role === 'ADMIN';
      })
      .addCase(loginUser.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      })
      // Google Login
      .addCase(googleLoginUser.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(googleLoginUser.fulfilled, (state, action) => {
        state.loading = false;
        state.token = action.payload.token;
        state.decodedToken = decodeToken(action.payload.token);
        state.profile = action.payload.profile;
        state.isAuthenticated = true;
        state.isAdmin = state.decodedToken?.is_superuser || action.payload.profile?.role === 'ADMIN';
      })
      .addCase(googleLoginUser.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      })
      // Register
      .addCase(registerUser.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(registerUser.fulfilled, (state) => {
        state.loading = false;
        state.error = null;
      })
      .addCase(registerUser.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      })
      // Fetch Profile
      .addCase(fetchProfile.pending, (state) => {
        state.isInitializing = true;
      })
      .addCase(fetchProfile.fulfilled, (state, action) => {
        state.isInitializing = false;
        state.profile = action.payload;
        state.isAdmin = state.decodedToken?.is_superuser || action.payload.role === 'ADMIN';
      })
      .addCase(fetchProfile.rejected, (state) => {
        state.isInitializing = false;
        // Don't force logout immediately on profile fail, but clear profile state
        state.profile = null;
      });
  },
});

export const { logout, clearAuthError, updateProfileSuccess } = authSlice.actions;
export default authSlice.reducer;

